window.CONTENT_BUNDLE = {"sql":{"cheatsheet":{"ansi":"\u001b[1m\u001b[33mSQL CHEATSHEET\u001b[39m\u001b[22m\r\n\r\n  \u001b[90mA working reference for the whole language. Skim it once, come back when stuck.\u001b[39m\r\n\r\n\u001b[1m\u001b[33mSELECT AND PROJECTION\u001b[39m\u001b[22m\r\n\r\n  \u001b[33mSELECT\u001b[39m picks columns out of a table. \u001b[1m*\u001b[22m grabs every column; naming columns is better practice because the query keeps working when the schema changes.\r\n\r\n      \u001b[33mSELECT\u001b[39m name, phone \u001b[33mFROM\u001b[39m customers;\r\n      \u001b[33mSELECT\u001b[39m \u001b[33mDISTINCT\u001b[39m make \u001b[33mFROM\u001b[39m vehicles;\r\n\r\n  \u001b[90mAliases rename a column or expression in the result. See \u001b[34m\u001b[4msql_am_10\u001b[24m\u001b[39m.\u001b[39m\r\n\r\n      \u001b[33mSELECT\u001b[39m total_cost \u001b[33mAS\u001b[39m cost_usd \u001b[33mFROM\u001b[39m work_orders;\r\n\r\n\u001b[1m\u001b[33mWHERE: FILTERING ROWS\u001b[39m\u001b[22m\r\n\r\n  Predicates filter rows before any aggregation or grouping happens. Combine with \u001b[33mAND\u001b[39m / \u001b[33mOR\u001b[39m. Strings go in single quotes.\r\n\r\n      \u001b[33mWHERE\u001b[39m make = \u001b[32m'Nissan'\u001b[39m \u001b[33mAND\u001b[39m year \u001b[33mBETWEEN\u001b[39m \u001b[34m1990\u001b[39m \u001b[33mAND\u001b[39m \u001b[34m1999\u001b[39m\r\n      \u001b[33mWHERE\u001b[39m status \u001b[33mIN\u001b[39m (\u001b[32m'Open'\u001b[39m, \u001b[32m'In Progress'\u001b[39m)\r\n      \u001b[33mWHERE\u001b[39m name \u001b[33mLIKE\u001b[39m \u001b[32m'K%'\u001b[39m\r\n\r\n  \u001b[31mNULL is not equal to anything\u001b[39m, not even itself. Use \u001b[33mIS NULL\u001b[39m and \u001b[33mIS NOT NULL\u001b[39m, never \u001b[33m= NULL\u001b[39m.\r\n\r\n\u001b[1m\u001b[33mAGGREGATION\u001b[39m\u001b[22m\r\n\r\n  Aggregates collapse many rows into one. Bare aggregates over the whole table produce one row. With \u001b[33mGROUP BY\u001b[39m you get one row per group.\r\n\r\n      \u001b[33mSELECT\u001b[39m \u001b[33mCOUNT\u001b[39m(*), \u001b[33mAVG\u001b[39m(total_cost), \u001b[33mSUM\u001b[39m(total_cost) \u001b[33mFROM\u001b[39m work_orders;\r\n      \u001b[33mSELECT\u001b[39m status, \u001b[33mCOUNT\u001b[39m(*) \u001b[33mFROM\u001b[39m work_orders \u001b[33mGROUP BY\u001b[39m status;\r\n\r\n  \u001b[33mHAVING\u001b[39m filters groups after aggregation. \u001b[33mWHERE\u001b[39m filters rows before. Use the right one or you will count things twice.\r\n\r\n      \u001b[33mGROUP BY\u001b[39m customer_id \u001b[33mHAVING\u001b[39m \u001b[33mCOUNT\u001b[39m(*) >= \u001b[34m2\u001b[39m\r\n\r\n\u001b[1m\u001b[33mJOINS\u001b[39m\u001b[22m\r\n\r\n  A join walks two tables side by side, matching rows on a shared key. Inner join keeps only matched rows. \u001b[33mLEFT JOIN\u001b[39m keeps every row from the left table even when the right has no match.\r\n\r\n      \u001b[33mSELECT\u001b[39m c.name, v.make\r\n      \u001b[33mFROM\u001b[39m customers c\r\n      \u001b[33mJOIN\u001b[39m vehicles v \u001b[33mON\u001b[39m v.customer_id = c.id;\r\n\r\n  \u001b[90mThree tables chain the same way. See \u001b[34m\u001b[4msql_int_09\u001b[24m\u001b[39m.\u001b[39m\r\n\r\n\u001b[1m\u001b[33mCASE EXPRESSIONS\u001b[39m\u001b[22m\r\n\r\n  \u001b[33mCASE\u001b[39m is SQL's if/else. Use it to bucket continuous values, or to count conditional matches inside an aggregate (the pivot trick).\r\n\r\n      \u001b[33mCASE\u001b[39m \u001b[33mWHEN\u001b[39m total_cost >= \u001b[34m2000\u001b[39m \u001b[33mTHEN\u001b[39m \u001b[32m'High'\u001b[39m \u001b[33mELSE\u001b[39m \u001b[32m'Low'\u001b[39m \u001b[33mEND\u001b[39m\r\n\r\n\u001b[1m\u001b[33mWINDOW FUNCTIONS\u001b[39m\u001b[22m\r\n\r\n  Window functions compute a value per row using a frame of related rows. Unlike \u001b[33mGROUP BY\u001b[39m, the original rows are preserved.\r\n\r\n      \u001b[35mRANK\u001b[39m() \u001b[33mOVER\u001b[39m (\u001b[33mORDER BY\u001b[39m revenue \u001b[33mDESC\u001b[39m)\r\n      \u001b[35mROW_NUMBER\u001b[39m() \u001b[33mOVER\u001b[39m (\u001b[33mPARTITION BY\u001b[39m status \u001b[33mORDER BY\u001b[39m total_cost \u001b[33mDESC\u001b[39m)\r\n      \u001b[35mSUM\u001b[39m(total_cost) \u001b[33mOVER\u001b[39m (\u001b[33mORDER BY\u001b[39m id) \u001b[33mAS\u001b[39m running_total\r\n\r\n\u001b[1m\u001b[33mCTEs AND SUBQUERIES\u001b[39m\u001b[22m\r\n\r\n  A common table expression is a named query you can reuse downstream. Easier to read than nested subqueries when the logic has steps.\r\n\r\n      \u001b[33mWITH\u001b[39m rev \u001b[33mAS\u001b[39m (\r\n          \u001b[33mSELECT\u001b[39m mechanic_id, \u001b[33mSUM\u001b[39m(total_cost) \u001b[33mAS\u001b[39m revenue\r\n          \u001b[33mFROM\u001b[39m work_orders \u001b[33mGROUP BY\u001b[39m mechanic_id\r\n      )\r\n      \u001b[33mSELECT\u001b[39m * \u001b[33mFROM\u001b[39m rev \u001b[33mWHERE\u001b[39m revenue > \u001b[34m5000\u001b[39m;\r\n\r\n  \u001b[35mWITH RECURSIVE\u001b[39m generates sequences or walks hierarchies. The base case unions to itself with a guard.\r\n\r\n\u001b[1m\u001b[33mQUALITY-OF-LIFE\u001b[39m\u001b[22m\r\n\r\n  \u001b[33mCOALESCE\u001b[39m(col, \u001b[32m'fallback'\u001b[39m) replaces NULLs. \u001b[33mROUND\u001b[39m(x, \u001b[34m2\u001b[39m) trims float noise. \u001b[33mLOWER\u001b[39m/\u001b[33mUPPER\u001b[39m normalize case before LIKE comparisons. \u001b[33mORDER BY\u001b[39m x \u001b[33mDESC\u001b[39m \u001b[33mLIMIT\u001b[39m \u001b[34mN\u001b[39m is the standard top-N pattern.\r\n\r\n\u001b[1m\u001b[33mTAG REFERENCE\u001b[39m\u001b[22m\r\n\r\n  \u001b[33mamber\u001b[39m keywords. \u001b[36mteal\u001b[39m types. \u001b[32mgreen\u001b[39m strings. \u001b[34mblue\u001b[39m numerics. \u001b[35mpurple\u001b[39m window/CTE syntax. \u001b[31mred\u001b[39m warnings. \u001b[90mdim\u001b[39m asides. \u001b[1mbold\u001b[22m emphasis.\r\n","html":"<div class=\"cs-section\"><h4 class=\"cs-h\">SQL CHEATSHEET</h4><p class=\"cs-prose\"><span class=\"cs-dim\">A working reference for the whole language. Skim it once, come back when stuck.</span></p></div><div class=\"cs-section\"><h4 class=\"cs-h\">SELECT AND PROJECTION</h4><p class=\"cs-prose\"><span class=\"cs-amber\">SELECT</span> picks columns out of a table. <span class=\"cs-bold\">*</span> grabs every column; naming columns is better practice because the query keeps working when the schema changes.</p><pre class=\"cs-code\"><code>  <span class=\"cs-amber\">SELECT</span> name, phone <span class=\"cs-amber\">FROM</span> customers;\n  <span class=\"cs-amber\">SELECT</span> <span class=\"cs-amber\">DISTINCT</span> make <span class=\"cs-amber\">FROM</span> vehicles;</code></pre><p class=\"cs-prose\"><span class=\"cs-dim\">Aliases rename a column or expression in the result. See <a class=\"cs-qid\" data-qid=\"sql_am_10\">sql_am_10</a>.</span></p><pre class=\"cs-code\"><code>  <span class=\"cs-amber\">SELECT</span> total_cost <span class=\"cs-amber\">AS</span> cost_usd <span class=\"cs-amber\">FROM</span> work_orders;</code></pre></div><div class=\"cs-section\"><h4 class=\"cs-h\">WHERE: FILTERING ROWS</h4><p class=\"cs-prose\">Predicates filter rows before any aggregation or grouping happens. Combine with <span class=\"cs-amber\">AND</span> / <span class=\"cs-amber\">OR</span>. Strings go in single quotes.</p><pre class=\"cs-code\"><code>  <span class=\"cs-amber\">WHERE</span> make = <span class=\"cs-green\">'Nissan'</span> <span class=\"cs-amber\">AND</span> year <span class=\"cs-amber\">BETWEEN</span> <span class=\"cs-blue\">1990</span> <span class=\"cs-amber\">AND</span> <span class=\"cs-blue\">1999</span>\n  <span class=\"cs-amber\">WHERE</span> status <span class=\"cs-amber\">IN</span> (<span class=\"cs-green\">'Open'</span>, <span class=\"cs-green\">'In Progress'</span>)\n  <span class=\"cs-amber\">WHERE</span> name <span class=\"cs-amber\">LIKE</span> <span class=\"cs-green\">'K%'</span></code></pre><p class=\"cs-prose\"><span class=\"cs-red\">NULL is not equal to anything</span>, not even itself. Use <span class=\"cs-amber\">IS NULL</span> and <span class=\"cs-amber\">IS NOT NULL</span>, never <span class=\"cs-amber\">= NULL</span>.</p></div><div class=\"cs-section\"><h4 class=\"cs-h\">AGGREGATION</h4><p class=\"cs-prose\">Aggregates collapse many rows into one. Bare aggregates over the whole table produce one row. With <span class=\"cs-amber\">GROUP BY</span> you get one row per group.</p><pre class=\"cs-code\"><code>  <span class=\"cs-amber\">SELECT</span> <span class=\"cs-amber\">COUNT</span>(*), <span class=\"cs-amber\">AVG</span>(total_cost), <span class=\"cs-amber\">SUM</span>(total_cost) <span class=\"cs-amber\">FROM</span> work_orders;\n  <span class=\"cs-amber\">SELECT</span> status, <span class=\"cs-amber\">COUNT</span>(*) <span class=\"cs-amber\">FROM</span> work_orders <span class=\"cs-amber\">GROUP BY</span> status;</code></pre><p class=\"cs-prose\"><span class=\"cs-amber\">HAVING</span> filters groups after aggregation. <span class=\"cs-amber\">WHERE</span> filters rows before. Use the right one or you will count things twice.</p><pre class=\"cs-code\"><code>  <span class=\"cs-amber\">GROUP BY</span> customer_id <span class=\"cs-amber\">HAVING</span> <span class=\"cs-amber\">COUNT</span>(*) &gt;= <span class=\"cs-blue\">2</span></code></pre></div><div class=\"cs-section\"><h4 class=\"cs-h\">JOINS</h4><p class=\"cs-prose\">A join walks two tables side by side, matching rows on a shared key. Inner join keeps only matched rows. <span class=\"cs-amber\">LEFT JOIN</span> keeps every row from the left table even when the right has no match.</p><pre class=\"cs-code\"><code>  <span class=\"cs-amber\">SELECT</span> c.name, v.make\n  <span class=\"cs-amber\">FROM</span> customers c\n  <span class=\"cs-amber\">JOIN</span> vehicles v <span class=\"cs-amber\">ON</span> v.customer_id = c.id;</code></pre><p class=\"cs-prose\"><span class=\"cs-dim\">Three tables chain the same way. See <a class=\"cs-qid\" data-qid=\"sql_int_09\">sql_int_09</a>.</span></p></div><div class=\"cs-section\"><h4 class=\"cs-h\">CASE EXPRESSIONS</h4><p class=\"cs-prose\"><span class=\"cs-amber\">CASE</span> is SQL's if/else. Use it to bucket continuous values, or to count conditional matches inside an aggregate (the pivot trick).</p><pre class=\"cs-code\"><code>  <span class=\"cs-amber\">CASE</span> <span class=\"cs-amber\">WHEN</span> total_cost &gt;= <span class=\"cs-blue\">2000</span> <span class=\"cs-amber\">THEN</span> <span class=\"cs-green\">'High'</span> <span class=\"cs-amber\">ELSE</span> <span class=\"cs-green\">'Low'</span> <span class=\"cs-amber\">END</span></code></pre></div><div class=\"cs-section\"><h4 class=\"cs-h\">WINDOW FUNCTIONS</h4><p class=\"cs-prose\">Window functions compute a value per row using a frame of related rows. Unlike <span class=\"cs-amber\">GROUP BY</span>, the original rows are preserved.</p><pre class=\"cs-code\"><code>  <span class=\"cs-purple\">RANK</span>() <span class=\"cs-amber\">OVER</span> (<span class=\"cs-amber\">ORDER BY</span> revenue <span class=\"cs-amber\">DESC</span>)\n  <span class=\"cs-purple\">ROW_NUMBER</span>() <span class=\"cs-amber\">OVER</span> (<span class=\"cs-amber\">PARTITION BY</span> status <span class=\"cs-amber\">ORDER BY</span> total_cost <span class=\"cs-amber\">DESC</span>)\n  <span class=\"cs-purple\">SUM</span>(total_cost) <span class=\"cs-amber\">OVER</span> (<span class=\"cs-amber\">ORDER BY</span> id) <span class=\"cs-amber\">AS</span> running_total</code></pre></div><div class=\"cs-section\"><h4 class=\"cs-h\">CTEs AND SUBQUERIES</h4><p class=\"cs-prose\">A common table expression is a named query you can reuse downstream. Easier to read than nested subqueries when the logic has steps.</p><pre class=\"cs-code\"><code>  <span class=\"cs-amber\">WITH</span> rev <span class=\"cs-amber\">AS</span> (\n      <span class=\"cs-amber\">SELECT</span> mechanic_id, <span class=\"cs-amber\">SUM</span>(total_cost) <span class=\"cs-amber\">AS</span> revenue\n      <span class=\"cs-amber\">FROM</span> work_orders <span class=\"cs-amber\">GROUP BY</span> mechanic_id\n  )\n  <span class=\"cs-amber\">SELECT</span> * <span class=\"cs-amber\">FROM</span> rev <span class=\"cs-amber\">WHERE</span> revenue &gt; <span class=\"cs-blue\">5000</span>;</code></pre><p class=\"cs-prose\"><span class=\"cs-purple\">WITH RECURSIVE</span> generates sequences or walks hierarchies. The base case unions to itself with a guard.</p></div><div class=\"cs-section\"><h4 class=\"cs-h\">QUALITY-OF-LIFE</h4><p class=\"cs-prose\"><span class=\"cs-amber\">COALESCE</span>(col, <span class=\"cs-green\">'fallback'</span>) replaces NULLs. <span class=\"cs-amber\">ROUND</span>(x, <span class=\"cs-blue\">2</span>) trims float noise. <span class=\"cs-amber\">LOWER</span>/<span class=\"cs-amber\">UPPER</span> normalize case before LIKE comparisons. <span class=\"cs-amber\">ORDER BY</span> x <span class=\"cs-amber\">DESC</span> <span class=\"cs-amber\">LIMIT</span> <span class=\"cs-blue\">N</span> is the standard top-N pattern.</p></div><div class=\"cs-section\"><h4 class=\"cs-h\">TAG REFERENCE</h4><p class=\"cs-prose\"><span class=\"cs-amber\">amber</span> keywords. <span class=\"cs-teal\">teal</span> types. <span class=\"cs-green\">green</span> strings. <span class=\"cs-blue\">blue</span> numerics. <span class=\"cs-purple\">purple</span> window/CTE syntax. <span class=\"cs-red\">red</span> warnings. <span class=\"cs-dim\">dim</span> asides. <span class=\"cs-bold\">bold</span> emphasis.</p></div>"},"tiers":{"1":"\u001b[1m\u001b[33mSQL \u00b7 TIER 1 CONCEPTS (INTRODUCTORY)\u001b[39m\u001b[22m\r\n\r\n  \u001b[90mRead this once. The first ten questions cover the four verbs below.\u001b[39m\r\n\r\n  SQL is a language for asking questions of structured data. A relational database stores facts in tables, where each row is a record and each column is an attribute. Your job at this tier is to pull the right rows and the right columns.\r\n\r\n\u001b[1m\u001b[33mTHE FOUR PRIMITIVES\u001b[39m\u001b[22m\r\n\r\n  \u001b[33mSELECT\u001b[39m picks the columns you want. \u001b[1m*\u001b[22m grabs all of them. \u001b[33mFROM\u001b[39m names the table. \u001b[33mWHERE\u001b[39m filters which rows survive. \u001b[33mORDER BY\u001b[39m sorts the result.\r\n\r\n  Every clause is optional except \u001b[33mSELECT\u001b[39m and \u001b[33mFROM\u001b[39m. The order you write them is fixed: SELECT, FROM, WHERE, ORDER BY. The order the database evaluates them is different (FROM first, SELECT last) but that only matters later.\r\n\r\n\u001b[1m\u001b[33mCOMPARISONS AND TYPES\u001b[39m\u001b[22m\r\n\r\n  Strings need single quotes. Numbers don't. Booleans live in \u001b[34m1\u001b[39m/\u001b[34m0\u001b[39m in this dialect. Type mismatches won't error in SQLite, they'll just return zero rows, which is the most confusing failure mode in the language.\r\n\r\n      \u001b[33mWHERE\u001b[39m make = \u001b[32m'Nissan'\u001b[39m      \u001b[90mstring\u001b[39m\r\n      \u001b[33mWHERE\u001b[39m year = \u001b[34m2020\u001b[39m          \u001b[90minteger\u001b[39m\r\n      \u001b[33mWHERE\u001b[39m active = \u001b[34m1\u001b[39m           \u001b[90mboolean as int\u001b[39m\r\n\r\n\u001b[1m\u001b[33mCOUNTING AND DISTINCT\u001b[39m\u001b[22m\r\n\r\n  \u001b[33mCOUNT\u001b[39m(*) returns the number of rows that survived the filter. It is one row of output, regardless of how many rows came in. \u001b[33mDISTINCT\u001b[39m inside \u001b[33mSELECT\u001b[39m removes duplicate rows from the result.\r\n\r\n  \u001b[90mWhy both exist: COUNT tells you how many, DISTINCT tells you which. Compare\u001b[39m \u001b[90m\u001b[34m\u001b[4msql_intro_04\u001b[24m\u001b[39m (count) with \u001b[34m\u001b[4msql_intro_07\u001b[24m\u001b[39m (distinct).\u001b[39m\r\n\r\n  NEXT TIER: AND/OR combinations, BETWEEN, IN, LIKE wildcards, basic aggregates beyond COUNT, and conditional bucketing with CASE.\r\n","2":"\u001b[1m\u001b[33mSQL \u00b7 TIER 2 CONCEPTS (AMATEUR)\u001b[39m\u001b[22m\r\n\r\n  \u001b[90mFiltering gets richer. You stop saying \"equal to\" and start saying \"in this\u001b[39m \u001b[90mrange, in this set, matching this pattern.\"\u001b[39m\r\n\r\n  At this tier the queries answer questions a real shop manager actually asks: what's the average cost, who hasn't given us a phone number, find me anything in the 1990s.\r\n\r\n\u001b[1m\u001b[33mRANGES, SETS, PATTERNS\u001b[39m\u001b[22m\r\n\r\n  \u001b[33mBETWEEN\u001b[39m is inclusive on both endpoints. It's syntactic sugar for two comparisons joined by \u001b[33mAND\u001b[39m.\r\n\r\n      \u001b[33mWHERE\u001b[39m year \u001b[33mBETWEEN\u001b[39m \u001b[34m1990\u001b[39m \u001b[33mAND\u001b[39m \u001b[34m1999\u001b[39m\r\n\r\n  \u001b[33mIN\u001b[39m tests membership in a small set. Cleaner than chained \u001b[33mOR\u001b[39m statements and easier to extend.\r\n\r\n      \u001b[33mWHERE\u001b[39m status \u001b[33mIN\u001b[39m (\u001b[32m'Open'\u001b[39m, \u001b[32m'In Progress'\u001b[39m)\r\n\r\n  \u001b[33mLIKE\u001b[39m does pattern matching. \u001b[1m%\u001b[22m matches any run of characters, \u001b[1m_\u001b[22m matches exactly one. \u001b[33mNOT LIKE\u001b[39m inverts.\r\n\r\n      \u001b[33mWHERE\u001b[39m name \u001b[33mLIKE\u001b[39m \u001b[32m'K%'\u001b[39m          \u001b[90mstarts with K\u001b[39m\r\n      \u001b[33mWHERE\u001b[39m name \u001b[33mLIKE\u001b[39m \u001b[32m'%son'\u001b[39m        \u001b[90mends with son\u001b[39m\r\n      \u001b[33mWHERE\u001b[39m name \u001b[33mLIKE\u001b[39m \u001b[32m'_a%'\u001b[39m         \u001b[90ma is the second letter\u001b[39m\r\n\r\n\u001b[1m\u001b[33mNULL\u001b[39m\u001b[22m\r\n\r\n  Missing data is its own thing. Three-valued logic: \u001b[33mNULL\u001b[39m is neither true nor false in any comparison. \u001b[31m= NULL\u001b[39m always returns nothing. Use \u001b[33mIS NULL\u001b[39m and \u001b[33mIS NOT NULL\u001b[39m.\r\n\r\n  \u001b[90mWhy this matters: in customer records phone numbers, optional addresses,\u001b[39m \u001b[90mand unfilled-in fields are all NULLs. Filtering them needs the right operator\u001b[39m \u001b[90mor you get phantom empty results.\u001b[39m\r\n\r\n\u001b[1m\u001b[33mAGGREGATES BEYOND COUNT\u001b[39m\u001b[22m\r\n\r\n  \u001b[33mSUM\u001b[39m, \u001b[33mAVG\u001b[39m, \u001b[33mMIN\u001b[39m, \u001b[33mMAX\u001b[39m all reduce a column to a single value. They ignore NULLs. You can put several in one SELECT.\r\n\r\n      \u001b[33mSELECT\u001b[39m \u001b[33mMIN\u001b[39m(total_cost), \u001b[33mMAX\u001b[39m(total_cost) \u001b[33mFROM\u001b[39m work_orders;\r\n\r\n  \u001b[33mORDER BY\u001b[39m x \u001b[33mDESC\u001b[39m \u001b[33mLIMIT\u001b[39m \u001b[34mN\u001b[39m is the top-N recipe. Order then trim. The reverse order doesn't make sense.\r\n\r\n\u001b[1m\u001b[33mCONDITIONAL EXPRESSIONS\u001b[39m\u001b[22m\r\n\r\n  \u001b[33mCASE\u001b[39m \u001b[33mWHEN\u001b[39m cond \u001b[33mTHEN\u001b[39m a \u001b[33mELSE\u001b[39m b \u001b[33mEND\u001b[39m is the SQL ternary. Use it inside \u001b[33mSELECT\u001b[39m to bucket continuous values or label rows.\r\n\r\n  \u001b[90mThis is the building block for the pivot trick at Master tier. See\u001b[39m \u001b[90m\u001b[39m\u001b[34m\u001b[4msql_mas_08\u001b[24m\u001b[39m\u001b[90m.\u001b[39m\r\n\r\n  NEXT TIER: joins. Once you can pull rows from one table cleanly, the next step is combining facts that live in two tables.\r\n","3":"\u001b[1m\u001b[33mSQL \u00b7 TIER 3 CONCEPTS (INTERMEDIATE)\u001b[39m\u001b[22m\r\n\r\n  \u001b[90mTwo new ideas that let you ask vastly harder questions: combining tables and\u001b[39m \u001b[90mcollapsing groups. Most production queries use both.\u001b[39m\r\n\r\n\u001b[1m\u001b[33mJOINS\u001b[39m\u001b[22m\r\n\r\n  Real schemas split related facts across tables. Customers in one, vehicles in another, work_orders in a third. A join walks them side by side, matching rows on a shared key.\r\n\r\n      \u001b[33mSELECT\u001b[39m customers.name, vehicles.make\r\n      \u001b[33mFROM\u001b[39m customers\r\n      \u001b[33mJOIN\u001b[39m vehicles \u001b[33mON\u001b[39m customers.id = vehicles.customer_id;\r\n\r\n  Bare \u001b[33mJOIN\u001b[39m is an inner join. Only rows that match on both sides survive. \u001b[33mLEFT JOIN\u001b[39m keeps every row from the left table, filling NULL where the right has no match. That distinction matters when you want a customer's vehicle count \u001b[1mincluding zeros\u001b[22m.\r\n\r\n  \u001b[90mA vehicle row without a matching customer is a referential bug. A customer\u001b[39m \u001b[90mrow without a matching vehicle is a normal business state.\u001b[39m\r\n\r\n\u001b[1m\u001b[33mAGGREGATING IN GROUPS\u001b[39m\u001b[22m\r\n\r\n  \u001b[33mGROUP BY\u001b[39m divides the rows into buckets and runs an aggregate per bucket. The output has one row per group. Every column in the \u001b[33mSELECT\u001b[39m must either be in the \u001b[33mGROUP BY\u001b[39m or be wrapped in an aggregate.\r\n\r\n      \u001b[33mSELECT\u001b[39m status, \u001b[33mCOUNT\u001b[39m(*) \u001b[33mFROM\u001b[39m work_orders \u001b[33mGROUP BY\u001b[39m status;\r\n\r\n  This is the right tool when you want a count per category, a sum per customer, or an average per mechanic.\r\n\r\n\u001b[1m\u001b[33mWHERE VS HAVING\u001b[39m\u001b[22m\r\n\r\n  Two filters, two stages. \u001b[33mWHERE\u001b[39m runs before grouping, on individual rows. \u001b[33mHAVING\u001b[39m runs after grouping, on the aggregated result.\r\n\r\n      \u001b[33mWHERE\u001b[39m  status = \u001b[32m'Completed'\u001b[39m   \u001b[90mdrops uncompleted rows\u001b[39m\r\n      \u001b[33mHAVING\u001b[39m \u001b[33mCOUNT\u001b[39m(*) >= \u001b[34m2\u001b[39m            \u001b[90mdrops small groups\u001b[39m\r\n\r\n  Putting an aggregate inside \u001b[33mWHERE\u001b[39m is an error. Putting a row predicate inside \u001b[33mHAVING\u001b[39m is legal but slow.\r\n\r\n\u001b[1m\u001b[33mJOINING THREE TABLES\u001b[39m\u001b[22m\r\n\r\n  Chain \u001b[33mJOIN\u001b[39m clauses. Each one matches the running result against the next table. Order doesn't change the answer for inner joins, only LEFT joins.\r\n\r\n      \u001b[33mFROM\u001b[39m work_orders\r\n      \u001b[33mJOIN\u001b[39m vehicles  \u001b[33mON\u001b[39m work_orders.vehicle_id = vehicles.id\r\n      \u001b[33mJOIN\u001b[39m customers \u001b[33mON\u001b[39m vehicles.customer_id = customers.id\r\n\r\n  \u001b[90mThis is the canonical \"trace a transaction back to its root entity\"\u001b[39m \u001b[90mpattern. See \u001b[39m\u001b[34m\u001b[4msql_int_09\u001b[24m\u001b[39m\u001b[90m.\u001b[39m\r\n\r\n\u001b[1m\u001b[33mROUNDING AND ALIASING\u001b[39m\u001b[22m\r\n\r\n  \u001b[33mROUND\u001b[39m(x, n) trims float noise from averages. \u001b[33mAS\u001b[39m gives an expression a friendly column name. Both small but they make output readable.\r\n\r\n  NEXT TIER: window functions. Same idea as GROUP BY but the original rows survive. You'll be able to rank, partition, and run cumulative sums.\r\n","4":"\u001b[1m\u001b[33mSQL \u00b7 TIER 4 CONCEPTS (EXPERIENCED)\u001b[39m\u001b[22m\r\n\r\n  \u001b[90mThe big shift here: you stop collapsing rows when you aggregate. Window\u001b[39m \u001b[90mfunctions let you compute a per-row value that sees its neighbors.\u001b[39m\r\n\r\n\u001b[1m\u001b[33mWINDOW FUNCTIONS\u001b[39m\u001b[22m\r\n\r\n  A window function is an aggregate or rank computed across a set of related rows, but the original rows are kept. The shape stays the same, you just gain a new column.\r\n\r\n      \u001b[35mRANK\u001b[39m() \u001b[33mOVER\u001b[39m (\u001b[33mORDER BY\u001b[39m revenue \u001b[33mDESC\u001b[39m)\r\n\r\n  Three pieces: a function (\u001b[35mRANK\u001b[39m, \u001b[35mROW_NUMBER\u001b[39m, \u001b[35mDENSE_RANK\u001b[39m, any aggregate), the \u001b[33mOVER\u001b[39m keyword, and a window spec inside parens.\r\n\r\n  \u001b[1mRANK\u001b[22m gives ties the same number and skips the next: 1, 2, 2, 4. \u001b[1mDENSE_RANK\u001b[22m also ties but doesn't skip: 1, 2, 2, 3. \u001b[1mROW_NUMBER\u001b[22m never ties: 1, 2, 3, 4 even when values are equal.\r\n\r\n  \u001b[90mYou pick the one whose tie semantics match what downstream code expects.\u001b[39m \u001b[90mMost ranking dashboards want DENSE_RANK to avoid gaps.\u001b[39m\r\n\r\n\u001b[1m\u001b[33mPARTITIONING\u001b[39m\u001b[22m\r\n\r\n  Add \u001b[33mPARTITION BY\u001b[39m to compute the window separately within each group. Rank within status, running total within customer, that kind of thing.\r\n\r\n      \u001b[35mROW_NUMBER\u001b[39m() \u001b[33mOVER\u001b[39m (\u001b[33mPARTITION BY\u001b[39m status \u001b[33mORDER BY\u001b[39m total_cost \u001b[33mDESC\u001b[39m)\r\n\r\n  Without \u001b[33mPARTITION BY\u001b[39m the window is the whole table.\r\n\r\n\u001b[1m\u001b[33mSUBQUERIES IN WHERE AND SELECT\u001b[39m\u001b[22m\r\n\r\n  A subquery is a SELECT inside another SELECT. Two flavors matter at this tier: scalar subqueries (return one value) and table subqueries (return rows you query against).\r\n\r\n      \u001b[33mWHERE\u001b[39m revenue = (\u001b[33mSELECT\u001b[39m \u001b[33mMAX\u001b[39m(rev) \u001b[33mFROM\u001b[39m (...))\r\n\r\n  \u001b[90mThe \"find the row matching the max of a derived column\" pattern. The\u001b[39m \u001b[90minner SELECT computes the threshold, the outer SELECT filters by it.\u001b[39m\r\n\r\n\u001b[1m\u001b[33mCOALESCE AND UNION\u001b[39m\u001b[22m\r\n\r\n  \u001b[33mCOALESCE\u001b[39m(a, b, c) returns the first non-NULL argument. Use it to swap missing values for a sensible default at display time.\r\n\r\n      \u001b[33mCOALESCE\u001b[39m(phone, \u001b[32m'N/A'\u001b[39m) \u001b[33mAS\u001b[39m phone_display\r\n\r\n  \u001b[33mUNION\u001b[39m stacks two result sets vertically. They must have the same number of columns and compatible types. \u001b[33mUNION\u001b[39m dedupes, \u001b[33mUNION ALL\u001b[39m keeps duplicates and is faster.\r\n\r\n  \u001b[90mML aside: ranking and partitioning are how leaderboards, top-K\u001b[39m \u001b[90mretrieval, and bucketed evaluation metrics are computed at the SQL layer\u001b[39m \u001b[90mbefore any model sees the rows.\u001b[39m\r\n\r\n  NEXT TIER: CTEs and recursive queries, self-joins, and the pivot trick. Anything that requires steps you can name and reuse, or queries that talk to themselves.\r\n","5":"\u001b[1m\u001b[33mSQL \u00b7 TIER 5 CONCEPTS (MASTER)\u001b[39m\u001b[22m\r\n\r\n  \u001b[90mLast tier. The patterns here are how analysts and DEs actually compose\u001b[39m \u001b[90mhard queries: name your steps, reuse them, recurse when the data has\u001b[39m \u001b[90mstructure.\u001b[39m\r\n\r\n\u001b[1m\u001b[33mCOMMON TABLE EXPRESSIONS\u001b[39m\u001b[22m\r\n\r\n  A CTE is a named subquery you write at the top with \u001b[33mWITH\u001b[39m. The body references the name like a real table. Two reasons to prefer them over nested subqueries: they read top-down, and you can chain them.\r\n\r\n      \u001b[33mWITH\u001b[39m rev \u001b[33mAS\u001b[39m (\r\n          \u001b[33mSELECT\u001b[39m mechanic_id, \u001b[33mSUM\u001b[39m(total_cost) \u001b[33mAS\u001b[39m revenue\r\n          \u001b[33mFROM\u001b[39m work_orders \u001b[33mGROUP BY\u001b[39m mechanic_id\r\n      ),\r\n      avg_rev \u001b[33mAS\u001b[39m (\r\n          \u001b[33mSELECT\u001b[39m \u001b[33mAVG\u001b[39m(revenue) \u001b[33mAS\u001b[39m avg_rev \u001b[33mFROM\u001b[39m rev\r\n      )\r\n      \u001b[33mSELECT\u001b[39m rev.mechanic_id, rev.revenue, avg_rev.avg_rev\r\n      \u001b[33mFROM\u001b[39m rev, avg_rev;\r\n\r\n  \u001b[90mSame answer as a nested subquery, but each step has a name and a single\u001b[39m \u001b[90mresponsibility. Treat each CTE like a Python function.\u001b[39m\r\n\r\n\u001b[1m\u001b[33mRECURSIVE CTEs\u001b[39m\u001b[22m\r\n\r\n  \u001b[35mWITH RECURSIVE\u001b[39m lets a CTE reference itself, with a base case and a recursive case joined by \u001b[33mUNION ALL\u001b[39m. The classic uses are generating number sequences and walking parent-child hierarchies.\r\n\r\n      \u001b[35mWITH RECURSIVE\u001b[39m cnt(n) \u001b[33mAS\u001b[39m (\r\n          \u001b[33mSELECT\u001b[39m \u001b[34m1\u001b[39m\r\n          \u001b[33mUNION ALL\u001b[39m\r\n          \u001b[33mSELECT\u001b[39m n + \u001b[34m1\u001b[39m \u001b[33mFROM\u001b[39m cnt \u001b[33mWHERE\u001b[39m n < \u001b[34m5\u001b[39m\r\n      )\r\n      \u001b[33mSELECT\u001b[39m n \u001b[33mFROM\u001b[39m cnt;\r\n\r\n  \u001b[31mAlways include a stop condition\u001b[39m in the \u001b[33mWHERE\u001b[39m clause of the recursive arm or the database will spin until you cancel it.\r\n\r\n\u001b[1m\u001b[33mSELF-JOINS\u001b[39m\u001b[22m\r\n\r\n  A table joined to itself, aliased twice. Use it to compare rows against other rows in the same table: pairs with the same key, transitive relationships, \"find duplicates.\"\r\n\r\n      \u001b[33mFROM\u001b[39m mechanics a \u001b[33mJOIN\u001b[39m mechanics b\r\n      \u001b[33mON\u001b[39m a.specialty = b.specialty \u001b[33mAND\u001b[39m a.id < b.id\r\n\r\n  \u001b[90mThe id < id constraint dedupes pairs (a,b) and (b,a) so you don't get\u001b[39m \u001b[90mevery match twice.\u001b[39m\r\n\r\n\u001b[1m\u001b[33mCORRELATED SUBQUERIES\u001b[39m\u001b[22m\r\n\r\n  A subquery that references the outer query's row. Logically, it runs once per outer row. Use sparingly because the cost is per-row.\r\n\r\n      \u001b[33mSELECT\u001b[39m id, name,\r\n             (\u001b[33mSELECT\u001b[39m \u001b[33mCOUNT\u001b[39m(*) \u001b[33mFROM\u001b[39m vehicles \u001b[33mWHERE\u001b[39m customer_id = customers.id) \u001b[33mAS\u001b[39m vc\r\n      \u001b[33mFROM\u001b[39m customers;\r\n\r\n  Often equivalent to a \u001b[33mLEFT JOIN\u001b[39m + \u001b[33mGROUP BY\u001b[39m. The join form is usually faster on real data.\r\n\r\n\u001b[1m\u001b[33mWINDOWS WITH AGGREGATE FUNCTIONS\u001b[39m\u001b[22m\r\n\r\n  Aggregates inside \u001b[33mOVER\u001b[39m become running calculations. With \u001b[33mORDER BY\u001b[39m inside the window, the frame defaults to \"all rows up to this one\" \u2014 that's the cumulative pattern.\r\n\r\n      \u001b[33mSELECT\u001b[39m id, total_cost,\r\n             \u001b[33mSUM\u001b[39m(total_cost) \u001b[33mOVER\u001b[39m (\u001b[33mORDER BY\u001b[39m id) \u001b[33mAS\u001b[39m running_total\r\n\r\n  Empty \u001b[33mOVER\u001b[39m () is the whole table. That gives you \"this row's share of the total\" in one expression: total_cost * 100.0 / \u001b[33mSUM\u001b[39m(total_cost) \u001b[33mOVER\u001b[39m ().\r\n\r\n\u001b[1m\u001b[33mTHE PIVOT TRICK\u001b[39m\u001b[22m\r\n\r\n  \u001b[33mSUM\u001b[39m(\u001b[33mCASE WHEN\u001b[39m cond \u001b[33mTHEN\u001b[39m \u001b[34m1\u001b[39m \u001b[33mELSE\u001b[39m \u001b[34m0\u001b[39m \u001b[33mEND\u001b[39m) counts conditional matches per group. Stack one per category and you've pivoted long-format rows into wide-format columns without a true PIVOT operator.\r\n\r\n\u001b[1m\u001b[33mNTILE\u001b[39m\u001b[22m\r\n\r\n  \u001b[35mNTILE\u001b[39m(\u001b[34m4\u001b[39m) \u001b[33mOVER\u001b[39m (...) splits ordered rows into N roughly-equal buckets. Quartiles, deciles, percentile bins. ML uses the same trick to discretize continuous features for tree models or to define evaluation cohorts.\r\n\r\n  NEXT TIER: there isn't one in SQL terms. You've got the working vocabulary for analytics queries. The next axis is performance: indexes, query plans, partitioning at the storage layer. That's a different track.\r\n"},"examples":{"1":["\u001b[1m\u001b[33mEXAMPLE 1\u001b[39m\u001b[22m\r\n\r\n  Pull every column from a table.\r\n\r\n      \u001b[33mSELECT\u001b[39m * \u001b[33mFROM\u001b[39m mechanics;\r\n\r\n  \u001b[90mThe \u001b[39m\u001b[1m*\u001b[22m\u001b[90m is shorthand for \"all columns in declaration order.\"\u001b[39m \u001b[90mUseful for exploring; risky in production code because adding a column to the\u001b[39m \u001b[90mtable silently changes the query's output shape.\u001b[39m\r\n","\u001b[1m\u001b[33mEXAMPLE 2\u001b[39m\u001b[22m\r\n\r\n  Filter rows by a string match.\r\n\r\n      \u001b[33mSELECT\u001b[39m name, phone\r\n      \u001b[33mFROM\u001b[39m customers\r\n      \u001b[33mWHERE\u001b[39m name = \u001b[32m'Riley Evans'\u001b[39m;\r\n\r\n  \u001b[90mStrings are case-sensitive in most dialects. SQLite is loosely typed but\u001b[39m \u001b[90mcase-sensitive on equality by default. The fix at the next tier is LOWER().\u001b[39m\r\n","\u001b[1m\u001b[33mEXAMPLE 3\u001b[39m\u001b[22m\r\n\r\n  Sort by a column. This previews the next tier's tooling because real queries almost always combine WHERE with sorting and limiting.\r\n\r\n      \u001b[33mSELECT\u001b[39m id, total_cost\r\n      \u001b[33mFROM\u001b[39m work_orders\r\n      \u001b[33mWHERE\u001b[39m status = \u001b[32m'Completed'\u001b[39m\r\n      \u001b[33mORDER BY\u001b[39m total_cost \u001b[33mDESC\u001b[39m;\r\n\r\n  \u001b[90mORDER BY total_cost DESC sorts highest first. At Amateur tier you'll add\u001b[39m \u001b[90mLIMIT to grab just the top N. The two together are how you answer \"what are\u001b[39m \u001b[90mthe biggest jobs we've ever done.\" See \u001b[39m\u001b[34m\u001b[4msql_am_04\u001b[24m\u001b[39m\u001b[90m.\u001b[39m\r\n"],"2":["\u001b[1m\u001b[33mEXAMPLE 1\u001b[39m\u001b[22m\r\n\r\n  Find the most expensive open work_order. Two filters and a sort.\r\n\r\n      \u001b[33mSELECT\u001b[39m id, total_cost\r\n      \u001b[33mFROM\u001b[39m work_orders\r\n      \u001b[33mWHERE\u001b[39m status = \u001b[32m'Open'\u001b[39m\r\n      \u001b[33mORDER BY\u001b[39m total_cost \u001b[33mDESC\u001b[39m\r\n      \u001b[33mLIMIT\u001b[39m \u001b[34m1\u001b[39m;\r\n\r\n  \u001b[90mLIMIT N is your top-N pattern. LIMIT 1 is the \"single biggest\" idiom.\u001b[39m\r\n","\u001b[1m\u001b[33mEXAMPLE 2\u001b[39m\u001b[22m\r\n\r\n  Bucket continuous prices into named tiers. CASE creates a derived column.\r\n\r\n      \u001b[33mSELECT\u001b[39m id,\r\n             \u001b[33mCASE\u001b[39m\r\n                 \u001b[33mWHEN\u001b[39m total_cost < \u001b[34m500\u001b[39m  \u001b[33mTHEN\u001b[39m \u001b[32m'Small'\u001b[39m\r\n                 \u001b[33mWHEN\u001b[39m total_cost < \u001b[34m2000\u001b[39m \u001b[33mTHEN\u001b[39m \u001b[32m'Mid'\u001b[39m\r\n                 \u001b[33mELSE\u001b[39m \u001b[32m'Large'\u001b[39m\r\n             \u001b[33mEND\u001b[39m \u001b[33mAS\u001b[39m bucket\r\n      \u001b[33mFROM\u001b[39m work_orders;\r\n\r\n  \u001b[90mSame trick that ML uses to discretize a continuous feature into bins for\u001b[39m \u001b[90ma tree model. The label column is the threshold's output.\u001b[39m\r\n","\u001b[1m\u001b[33mEXAMPLE 3\u001b[39m\u001b[22m\r\n\r\n  Count by category, previewing GROUP BY at the next tier. Right now you can hand-count one bucket at a time:\r\n\r\n      \u001b[33mSELECT\u001b[39m \u001b[33mCOUNT\u001b[39m(*) \u001b[33mFROM\u001b[39m work_orders \u001b[33mWHERE\u001b[39m status = \u001b[32m'Open'\u001b[39m;\r\n      \u001b[33mSELECT\u001b[39m \u001b[33mCOUNT\u001b[39m(*) \u001b[33mFROM\u001b[39m work_orders \u001b[33mWHERE\u001b[39m status = \u001b[32m'Completed'\u001b[39m;\r\n\r\n  \u001b[90mThree queries for three statuses is fine for now. At Intermediate tier\u001b[39m \u001b[90mone \u001b[39m\u001b[33mGROUP BY\u001b[39m\u001b[90m gives you all categories in a single result. See\u001b[39m \u001b[90m\u001b[39m\u001b[34m\u001b[4msql_int_03\u001b[24m\u001b[39m\u001b[90m.\u001b[39m\r\n"],"3":["\u001b[1m\u001b[33mEXAMPLE 1\u001b[39m\u001b[22m\r\n\r\n  Average cost per status. One row per group, one aggregate per row.\r\n\r\n      \u001b[33mSELECT\u001b[39m status, \u001b[33mROUND\u001b[39m(\u001b[33mAVG\u001b[39m(total_cost), \u001b[34m2\u001b[39m) \u001b[33mAS\u001b[39m avg_cost\r\n      \u001b[33mFROM\u001b[39m work_orders\r\n      \u001b[33mGROUP BY\u001b[39m status;\r\n\r\n  \u001b[90mROUND keeps the output readable. AS gives the aggregate a name so you\u001b[39m \u001b[90mcan ORDER BY it, reference it elsewhere, or read the result without squinting\u001b[39m \u001b[90mat \"AVG(total_cost)\".\u001b[39m\r\n","\u001b[1m\u001b[33mEXAMPLE 2\u001b[39m\u001b[22m\r\n\r\n  LEFT JOIN to count children, including zeros. The grouping happens on the parent's id so each customer appears once even with no children.\r\n\r\n      \u001b[33mSELECT\u001b[39m customers.name, \u001b[33mCOUNT\u001b[39m(vehicles.id) \u001b[33mAS\u001b[39m vehicle_count\r\n      \u001b[33mFROM\u001b[39m customers\r\n      \u001b[33mLEFT JOIN\u001b[39m vehicles \u001b[33mON\u001b[39m customers.id = vehicles.customer_id\r\n      \u001b[33mGROUP BY\u001b[39m customers.id;\r\n\r\n  \u001b[90mCOUNT(vehicles.id) instead of COUNT(*) so a customer with no vehicles\u001b[39m \u001b[90mcounts as zero, not one. COUNT skips NULLs.\u001b[39m\r\n","\u001b[1m\u001b[33mEXAMPLE 3\u001b[39m\u001b[22m\r\n\r\n  Two filtering stages, previewing window functions. You want top spenders whose group is large enough to be meaningful.\r\n\r\n      \u001b[33mSELECT\u001b[39m customers.id, customers.name, \u001b[33mSUM\u001b[39m(work_orders.total_cost) \u001b[33mAS\u001b[39m spend\r\n      \u001b[33mFROM\u001b[39m customers\r\n      \u001b[33mJOIN\u001b[39m vehicles    \u001b[33mON\u001b[39m vehicles.customer_id = customers.id\r\n      \u001b[33mJOIN\u001b[39m work_orders \u001b[33mON\u001b[39m work_orders.vehicle_id = vehicles.id\r\n      \u001b[33mGROUP BY\u001b[39m customers.id\r\n      \u001b[33mHAVING\u001b[39m \u001b[33mCOUNT\u001b[39m(work_orders.id) >= \u001b[34m2\u001b[39m\r\n      \u001b[33mORDER BY\u001b[39m spend \u001b[33mDESC\u001b[39m;\r\n\r\n  \u001b[90mAt the next tier you'll add \u001b[39m\u001b[35mRANK\u001b[39m() \u001b[33mOVER\u001b[39m (...) \u001b[90mto\u001b[39m \u001b[90mnumber these without losing the per-row detail. GROUP BY destroys row-level\u001b[39m \u001b[90mrows; window functions preserve them.\u001b[39m\r\n"],"4":["\u001b[1m\u001b[33mEXAMPLE 1\u001b[39m\u001b[22m\r\n\r\n  Rank rows globally by a metric. The whole table is one window.\r\n\r\n      \u001b[33mSELECT\u001b[39m id, total_cost,\r\n             \u001b[35mRANK\u001b[39m() \u001b[33mOVER\u001b[39m (\u001b[33mORDER BY\u001b[39m total_cost \u001b[33mDESC\u001b[39m) \u001b[33mAS\u001b[39m rnk\r\n      \u001b[33mFROM\u001b[39m work_orders;\r\n\r\n  \u001b[90mrnk = 1 for the most expensive job. Ties get the same rank and the next\u001b[39m \u001b[90mnumber is skipped. ROW_NUMBER would force-break ties; DENSE_RANK would not\u001b[39m \u001b[90mskip.\u001b[39m\r\n","\u001b[1m\u001b[33mEXAMPLE 2\u001b[39m\u001b[22m\r\n\r\n  Window inside a partition. Rank within each status independently so you can ask \"biggest open job, biggest completed job\" in one query.\r\n\r\n      \u001b[33mSELECT\u001b[39m id, status, total_cost,\r\n             \u001b[35mRANK\u001b[39m() \u001b[33mOVER\u001b[39m (\r\n                 \u001b[33mPARTITION BY\u001b[39m status\r\n                 \u001b[33mORDER BY\u001b[39m total_cost \u001b[33mDESC\u001b[39m\r\n             ) \u001b[33mAS\u001b[39m within_status_rank\r\n      \u001b[33mFROM\u001b[39m work_orders;\r\n\r\n  \u001b[90mSame rank function, different window. Each status is its own\u001b[39m \u001b[90mleaderboard.\u001b[39m\r\n","\u001b[1m\u001b[33mEXAMPLE 3\u001b[39m\u001b[22m\r\n\r\n  Subquery in the FROM clause, previewing CTEs. Right now you nest:\r\n\r\n      \u001b[33mSELECT\u001b[39m mechanic_id, revenue\r\n      \u001b[33mFROM\u001b[39m (\r\n          \u001b[33mSELECT\u001b[39m mechanic_id, \u001b[33mSUM\u001b[39m(total_cost) \u001b[33mAS\u001b[39m revenue\r\n          \u001b[33mFROM\u001b[39m work_orders \u001b[33mGROUP BY\u001b[39m mechanic_id\r\n      ) \u001b[33mAS\u001b[39m rev\r\n      \u001b[33mWHERE\u001b[39m revenue > \u001b[34m5000\u001b[39m;\r\n\r\n  \u001b[90mAt Master tier you'll write the same logic with WITH rev AS (...). It\u001b[39m \u001b[90mreads top-down instead of inside-out and lets you reference the same\u001b[39m \u001b[90msubquery multiple times. See \u001b[39m\u001b[34m\u001b[4msql_mas_02\u001b[24m\u001b[39m\u001b[90m.\u001b[39m\r\n"],"5":["\u001b[1m\u001b[33mEXAMPLE 1\u001b[39m\u001b[22m\r\n\r\n  CTE used as a step in a multi-stage calculation. Each name describes one thing and the final query reads like a recipe.\r\n\r\n      \u001b[33mWITH\u001b[39m per_status \u001b[33mAS\u001b[39m (\r\n          \u001b[33mSELECT\u001b[39m status, \u001b[33mSUM\u001b[39m(total_cost) \u001b[33mAS\u001b[39m total\r\n          \u001b[33mFROM\u001b[39m work_orders \u001b[33mGROUP BY\u001b[39m status\r\n      ),\r\n      grand \u001b[33mAS\u001b[39m (\r\n          \u001b[33mSELECT\u001b[39m \u001b[33mSUM\u001b[39m(total) \u001b[33mAS\u001b[39m grand_total \u001b[33mFROM\u001b[39m per_status\r\n      )\r\n      \u001b[33mSELECT\u001b[39m status, total, total * \u001b[34m100.0\u001b[39m / grand_total \u001b[33mAS\u001b[39m pct\r\n      \u001b[33mFROM\u001b[39m per_status, grand;\r\n\r\n  \u001b[90mTwo CTEs, one final select. The second CTE depends on the first. This\u001b[39m \u001b[90mis the pattern any analyst query of moderate complexity ends up using.\u001b[39m\r\n","\u001b[1m\u001b[33mEXAMPLE 2\u001b[39m\u001b[22m\r\n\r\n  Self-join to find pairs sharing an attribute. Useful when you want to enumerate co-occurrences.\r\n\r\n      \u001b[33mSELECT\u001b[39m a.name \u001b[33mAS\u001b[39m mech_a, b.name \u001b[33mAS\u001b[39m mech_b, a.specialty\r\n      \u001b[33mFROM\u001b[39m mechanics a\r\n      \u001b[33mJOIN\u001b[39m mechanics b\r\n        \u001b[33mON\u001b[39m a.specialty = b.specialty\r\n       \u001b[33mAND\u001b[39m a.id < b.id;\r\n\r\n  \u001b[90mTwo rows of the same table aliased a and b. The id < id rule keeps each\u001b[39m \u001b[90munordered pair listed once. Drop the constraint and you get every pair\u001b[39m \u001b[90mtwice plus self-pairs.\u001b[39m\r\n","\u001b[1m\u001b[33mEXAMPLE 3\u001b[39m\u001b[22m\r\n\r\n  Tying it all together: a CTE plus a window function. Computes per-mechanic revenue and ranks against the global mean. This is roughly what a model evaluation cohort report looks like in production: bucket, rank, normalize.\r\n\r\n      \u001b[33mWITH\u001b[39m rev \u001b[33mAS\u001b[39m (\r\n          \u001b[33mSELECT\u001b[39m mechanic_id, \u001b[33mSUM\u001b[39m(total_cost) \u001b[33mAS\u001b[39m revenue\r\n          \u001b[33mFROM\u001b[39m work_orders \u001b[33mGROUP BY\u001b[39m mechanic_id\r\n      )\r\n      \u001b[33mSELECT\u001b[39m mechanic_id, revenue,\r\n             \u001b[35mRANK\u001b[39m() \u001b[33mOVER\u001b[39m (\u001b[33mORDER BY\u001b[39m revenue \u001b[33mDESC\u001b[39m) \u001b[33mAS\u001b[39m rnk,\r\n             revenue - \u001b[33mAVG\u001b[39m(revenue) \u001b[33mOVER\u001b[39m () \u001b[33mAS\u001b[39m dev_from_mean,\r\n             \u001b[35mNTILE\u001b[39m(\u001b[34m4\u001b[39m) \u001b[33mOVER\u001b[39m (\u001b[33mORDER BY\u001b[39m revenue \u001b[33mDESC\u001b[39m) \u001b[33mAS\u001b[39m quartile\r\n      \u001b[33mFROM\u001b[39m rev;\r\n\r\n  \u001b[90mThree windows, one CTE, one query. Rank, deviation from mean, and\u001b[39m \u001b[90mquartile bucket all computed in a single pass. If you can read this, you\u001b[39m \u001b[90mcan read most analyst SQL in the wild.\u001b[39m\r\n"]}},"python":{"cheatsheet":{"ansi":"\u001b[1m\u001b[33mPYTHON CHEATSHEET\u001b[39m\u001b[22m\r\n\r\n  \u001b[90mA working reference for the whole language. Skim it once, come back when stuck.\u001b[39m\r\n\r\n\u001b[1m\u001b[33mVARIABLES AND TYPES\u001b[39m\u001b[22m\r\n\r\n  No declaration keyword. Bind a name with \u001b[33m=\u001b[39m. Python infers the type from the value.\r\n\r\n      garage = \u001b[32m'Terminal Auto'\u001b[39m\r\n      count  = \u001b[34m42\u001b[39m\r\n      rate   = \u001b[34m0.075\u001b[39m\r\n      active = \u001b[33mTrue\u001b[39m\r\n\r\n  Strings, ints, floats, bools, \u001b[33mNone\u001b[39m. Convert between them with \u001b[33mint\u001b[39m(), \u001b[33mfloat\u001b[39m(), \u001b[33mstr\u001b[39m(), \u001b[33mbool\u001b[39m(). \u001b[90mConversions can fail at runtime. See \u001b[34m\u001b[4mpy_intro_09\u001b[24m\u001b[39m.\u001b[39m\r\n\r\n\u001b[1m\u001b[33mCOLLECTIONS\u001b[39m\u001b[22m\r\n\r\n  Four built-ins handle most needs. Pick by access pattern.\r\n\r\n      cars   = [\u001b[32m'Skyline'\u001b[39m, \u001b[32m'Supra'\u001b[39m]            \u001b[90mlist:  ordered, mutable\u001b[39m\r\n      coords = (\u001b[34m3\u001b[39m, \u001b[34m4\u001b[39m)                            \u001b[90mtuple: ordered, immutable\u001b[39m\r\n      tags   = {\u001b[32m'jdm'\u001b[39m, \u001b[32m'turbo'\u001b[39m}                \u001b[90mset:   unordered, unique\u001b[39m\r\n      car    = {\u001b[32m'make'\u001b[39m: \u001b[32m'Nissan'\u001b[39m, \u001b[32m'year'\u001b[39m: \u001b[34m1996\u001b[39m}     \u001b[90mdict:  key -> value\u001b[39m\r\n\r\n  Index with \u001b[1mobj[i]\u001b[22m. Slice with \u001b[1mobj[a:b]\u001b[22m. Length with \u001b[33mlen\u001b[39m(obj). Membership with \u001b[33min\u001b[39m.\r\n\r\n\u001b[1m\u001b[33mCONTROL FLOW\u001b[39m\u001b[22m\r\n\r\n  \u001b[33mif\u001b[39m / \u001b[33melif\u001b[39m / \u001b[33melse\u001b[39m for branching. \u001b[33mfor\u001b[39m / \u001b[33mwhile\u001b[39m for loops. Indentation is syntactic. Four spaces is the standard.\r\n\r\n      \u001b[33mfor\u001b[39m item \u001b[33min\u001b[39m cars:\r\n          \u001b[33mprint\u001b[39m(item)\r\n\r\n      \u001b[33mif\u001b[39m count > \u001b[34m0\u001b[39m:\r\n          \u001b[33mprint\u001b[39m(\u001b[32m'positive'\u001b[39m)\r\n      \u001b[33melif\u001b[39m count == \u001b[34m0\u001b[39m:\r\n          \u001b[33mprint\u001b[39m(\u001b[32m'zero'\u001b[39m)\r\n      \u001b[33melse\u001b[39m:\r\n          \u001b[33mprint\u001b[39m(\u001b[32m'negative'\u001b[39m)\r\n\r\n\u001b[1m\u001b[33mFUNCTIONS\u001b[39m\u001b[22m\r\n\r\n  \u001b[33mdef\u001b[39m declares one. Default arguments go after required ones. \u001b[33mreturn\u001b[39m sends a value back; without it, the function returns \u001b[33mNone\u001b[39m.\r\n\r\n      \u001b[33mdef\u001b[39m \u001b[36mtotal_with_tax\u001b[39m(amount, rate=\u001b[34m0.08\u001b[39m):\r\n          \u001b[33mreturn\u001b[39m amount * (\u001b[34m1\u001b[39m + rate)\r\n\r\n  Lambdas are one-line anonymous functions. Useful as arguments to \u001b[33msorted\u001b[39m, \u001b[33mmap\u001b[39m, \u001b[33mfilter\u001b[39m.\r\n\r\n      sorted_people = \u001b[33msorted\u001b[39m(people, key=\u001b[33mlambda\u001b[39m p: p[\u001b[32m'age'\u001b[39m])\r\n\r\n\u001b[1m\u001b[33mCOMPREHENSIONS\u001b[39m\u001b[22m\r\n\r\n  Build a list, dict, or set from an iterable in one expression. Equivalent to a for-loop with append, but tighter and faster.\r\n\r\n      squares  = [x**\u001b[34m2\u001b[39m \u001b[33mfor\u001b[39m x \u001b[33min\u001b[39m \u001b[33mrange\u001b[39m(\u001b[34m5\u001b[39m)]\r\n      lookup   = {k: \u001b[33mlen\u001b[39m(k) \u001b[33mfor\u001b[39m k \u001b[33min\u001b[39m words}\r\n      uniques  = {x.lower() \u001b[33mfor\u001b[39m x \u001b[33min\u001b[39m tags}\r\n\r\n  \u001b[90mComprehensions replace the loop-and-append pattern. See \u001b[34m\u001b[4mpy_int_01\u001b[24m\u001b[39m.\u001b[39m\r\n\r\n\u001b[1m\u001b[33mCLASSES\u001b[39m\u001b[22m\r\n\r\n  \u001b[33mclass\u001b[39m declares a type. \u001b[1m__init__\u001b[22m is the constructor. \u001b[1mself\u001b[22m is the instance.\r\n\r\n      \u001b[33mclass\u001b[39m \u001b[36mWorkOrder\u001b[39m:\r\n          \u001b[33mdef\u001b[39m \u001b[36m__init__\u001b[39m(self, id, cost, status):\r\n              self.id, self.cost, self.status = id, cost, status\r\n          \u001b[33mdef\u001b[39m \u001b[36mis_open\u001b[39m(self):\r\n              \u001b[33mreturn\u001b[39m self.status == \u001b[32m'Open'\u001b[39m\r\n\r\n  Decorators on methods: \u001b[35m@property\u001b[39m makes it look like an attribute, \u001b[35m@staticmethod\u001b[39m removes the implicit self.\r\n\r\n\u001b[1m\u001b[33mERRORS\u001b[39m\u001b[22m\r\n\r\n  \u001b[33mtry\u001b[39m / \u001b[33mexcept\u001b[39m catches exceptions. Catch the specific class. Bare \u001b[33mexcept\u001b[39m is a code smell.\r\n\r\n      \u001b[33mtry\u001b[39m:\r\n          result = a / b\r\n      \u001b[33mexcept\u001b[39m \u001b[31mZeroDivisionError\u001b[39m:\r\n          result = \u001b[33mNone\u001b[39m\r\n\r\n\u001b[1m\u001b[33mIMPORTS AND STDLIB\u001b[39m\u001b[22m\r\n\r\n  \u001b[33mfrom\u001b[39m module \u001b[33mimport\u001b[39m thing. \u001b[1mcollections\u001b[22m gives you \u001b[33mCounter\u001b[39m, \u001b[33mdefaultdict\u001b[39m, \u001b[33mnamedtuple\u001b[39m. \u001b[1mfunctools\u001b[22m gives you \u001b[33mreduce\u001b[39m, \u001b[35m@lru_cache\u001b[39m. \u001b[1mdataclasses\u001b[22m gives you \u001b[35m@dataclass\u001b[39m for boilerplate-free record types.\r\n\r\n\u001b[1m\u001b[33mF-STRINGS\u001b[39m\u001b[22m\r\n\r\n  Format with values inline. \u001b[1m:.2f\u001b[22m formats a float to two decimals. \u001b[1m,\u001b[22m adds thousand separators.\r\n\r\n      \u001b[32mf'Price: ${price:.2f}'\u001b[39m\r\n      \u001b[32mf'Count: {count:,}'\u001b[39m\r\n\r\n\u001b[1m\u001b[33mTAG REFERENCE\u001b[39m\u001b[22m\r\n\r\n  \u001b[33mamber\u001b[39m keywords/builtins. \u001b[36mteal\u001b[39m callables/types. \u001b[32mgreen\u001b[39m strings. \u001b[34mblue\u001b[39m numerics. \u001b[35mpurple\u001b[39m decorators. \u001b[31mred\u001b[39m warnings/exceptions. \u001b[90mdim\u001b[39m asides. \u001b[1mbold\u001b[22m emphasis.\r\n","html":"<div class=\"cs-section\"><h4 class=\"cs-h\">PYTHON CHEATSHEET</h4><p class=\"cs-prose\"><span class=\"cs-dim\">A working reference for the whole language. Skim it once, come back when stuck.</span></p></div><div class=\"cs-section\"><h4 class=\"cs-h\">VARIABLES AND TYPES</h4><p class=\"cs-prose\">No declaration keyword. Bind a name with <span class=\"cs-amber\">=</span>. Python infers the type from the value.</p><pre class=\"cs-code\"><code>  garage = <span class=\"cs-green\">'Terminal Auto'</span>\n  count  = <span class=\"cs-blue\">42</span>\n  rate   = <span class=\"cs-blue\">0.075</span>\n  active = <span class=\"cs-amber\">True</span></code></pre><p class=\"cs-prose\">Strings, ints, floats, bools, <span class=\"cs-amber\">None</span>. Convert between them with <span class=\"cs-amber\">int</span>(), <span class=\"cs-amber\">float</span>(), <span class=\"cs-amber\">str</span>(), <span class=\"cs-amber\">bool</span>(). <span class=\"cs-dim\">Conversions can fail at runtime. See <a class=\"cs-qid\" data-qid=\"py_intro_09\">py_intro_09</a>.</span></p></div><div class=\"cs-section\"><h4 class=\"cs-h\">COLLECTIONS</h4><p class=\"cs-prose\">Four built-ins handle most needs. Pick by access pattern.</p><pre class=\"cs-code\"><code>  cars   = [<span class=\"cs-green\">'Skyline'</span>, <span class=\"cs-green\">'Supra'</span>]            <span class=\"cs-dim\">list:  ordered, mutable</span>\n  coords = (<span class=\"cs-blue\">3</span>, <span class=\"cs-blue\">4</span>)                            <span class=\"cs-dim\">tuple: ordered, immutable</span>\n  tags   = {<span class=\"cs-green\">'jdm'</span>, <span class=\"cs-green\">'turbo'</span>}                <span class=\"cs-dim\">set:   unordered, unique</span>\n  car    = {<span class=\"cs-green\">'make'</span>: <span class=\"cs-green\">'Nissan'</span>, <span class=\"cs-green\">'year'</span>: <span class=\"cs-blue\">1996</span>}     <span class=\"cs-dim\">dict:  key -&gt; value</span></code></pre><p class=\"cs-prose\">Index with <span class=\"cs-bold\">obj[i]</span>. Slice with <span class=\"cs-bold\">obj[a:b]</span>. Length with <span class=\"cs-amber\">len</span>(obj). Membership with <span class=\"cs-amber\">in</span>.</p></div><div class=\"cs-section\"><h4 class=\"cs-h\">CONTROL FLOW</h4><p class=\"cs-prose\"><span class=\"cs-amber\">if</span> / <span class=\"cs-amber\">elif</span> / <span class=\"cs-amber\">else</span> for branching. <span class=\"cs-amber\">for</span> / <span class=\"cs-amber\">while</span> for loops. Indentation is syntactic. Four spaces is the standard.</p><pre class=\"cs-code\"><code>  <span class=\"cs-amber\">for</span> item <span class=\"cs-amber\">in</span> cars:\n      <span class=\"cs-amber\">print</span>(item)</code></pre><pre class=\"cs-code\"><code>  <span class=\"cs-amber\">if</span> count &gt; <span class=\"cs-blue\">0</span>:\n      <span class=\"cs-amber\">print</span>(<span class=\"cs-green\">'positive'</span>)\n  <span class=\"cs-amber\">elif</span> count == <span class=\"cs-blue\">0</span>:\n      <span class=\"cs-amber\">print</span>(<span class=\"cs-green\">'zero'</span>)\n  <span class=\"cs-amber\">else</span>:\n      <span class=\"cs-amber\">print</span>(<span class=\"cs-green\">'negative'</span>)</code></pre></div><div class=\"cs-section\"><h4 class=\"cs-h\">FUNCTIONS</h4><p class=\"cs-prose\"><span class=\"cs-amber\">def</span> declares one. Default arguments go after required ones. <span class=\"cs-amber\">return</span> sends a value back; without it, the function returns <span class=\"cs-amber\">None</span>.</p><pre class=\"cs-code\"><code>  <span class=\"cs-amber\">def</span> <span class=\"cs-teal\">total_with_tax</span>(amount, rate=<span class=\"cs-blue\">0.08</span>):\n      <span class=\"cs-amber\">return</span> amount * (<span class=\"cs-blue\">1</span> + rate)</code></pre><p class=\"cs-prose\">Lambdas are one-line anonymous functions. Useful as arguments to <span class=\"cs-amber\">sorted</span>, <span class=\"cs-amber\">map</span>, <span class=\"cs-amber\">filter</span>.</p><pre class=\"cs-code\"><code>  sorted_people = <span class=\"cs-amber\">sorted</span>(people, key=<span class=\"cs-amber\">lambda</span> p: p[<span class=\"cs-green\">'age'</span>])</code></pre></div><div class=\"cs-section\"><h4 class=\"cs-h\">COMPREHENSIONS</h4><p class=\"cs-prose\">Build a list, dict, or set from an iterable in one expression. Equivalent to a for-loop with append, but tighter and faster.</p><pre class=\"cs-code\"><code>  squares  = [x**<span class=\"cs-blue\">2</span> <span class=\"cs-amber\">for</span> x <span class=\"cs-amber\">in</span> <span class=\"cs-amber\">range</span>(<span class=\"cs-blue\">5</span>)]\n  lookup   = {k: <span class=\"cs-amber\">len</span>(k) <span class=\"cs-amber\">for</span> k <span class=\"cs-amber\">in</span> words}\n  uniques  = {x.lower() <span class=\"cs-amber\">for</span> x <span class=\"cs-amber\">in</span> tags}</code></pre><p class=\"cs-prose\"><span class=\"cs-dim\">Comprehensions replace the loop-and-append pattern. See <a class=\"cs-qid\" data-qid=\"py_int_01\">py_int_01</a>.</span></p></div><div class=\"cs-section\"><h4 class=\"cs-h\">CLASSES</h4><p class=\"cs-prose\"><span class=\"cs-amber\">class</span> declares a type. <span class=\"cs-bold\">__init__</span> is the constructor. <span class=\"cs-bold\">self</span> is the instance.</p><pre class=\"cs-code\"><code>  <span class=\"cs-amber\">class</span> <span class=\"cs-teal\">WorkOrder</span>:\n      <span class=\"cs-amber\">def</span> <span class=\"cs-teal\">__init__</span>(self, id, cost, status):\n          self.id, self.cost, self.status = id, cost, status\n      <span class=\"cs-amber\">def</span> <span class=\"cs-teal\">is_open</span>(self):\n          <span class=\"cs-amber\">return</span> self.status == <span class=\"cs-green\">'Open'</span></code></pre><p class=\"cs-prose\">Decorators on methods: <span class=\"cs-purple\">@property</span> makes it look like an attribute, <span class=\"cs-purple\">@staticmethod</span> removes the implicit self.</p></div><div class=\"cs-section\"><h4 class=\"cs-h\">ERRORS</h4><p class=\"cs-prose\"><span class=\"cs-amber\">try</span> / <span class=\"cs-amber\">except</span> catches exceptions. Catch the specific class. Bare <span class=\"cs-amber\">except</span> is a code smell.</p><pre class=\"cs-code\"><code>  <span class=\"cs-amber\">try</span>:\n      result = a / b\n  <span class=\"cs-amber\">except</span> <span class=\"cs-red\">ZeroDivisionError</span>:\n      result = <span class=\"cs-amber\">None</span></code></pre></div><div class=\"cs-section\"><h4 class=\"cs-h\">IMPORTS AND STDLIB</h4><p class=\"cs-prose\"><span class=\"cs-amber\">from</span> module <span class=\"cs-amber\">import</span> thing. <span class=\"cs-bold\">collections</span> gives you <span class=\"cs-amber\">Counter</span>, <span class=\"cs-amber\">defaultdict</span>, <span class=\"cs-amber\">namedtuple</span>. <span class=\"cs-bold\">functools</span> gives you <span class=\"cs-amber\">reduce</span>, <span class=\"cs-purple\">@lru_cache</span>. <span class=\"cs-bold\">dataclasses</span> gives you <span class=\"cs-purple\">@dataclass</span> for boilerplate-free record types.</p></div><div class=\"cs-section\"><h4 class=\"cs-h\">F-STRINGS</h4><p class=\"cs-prose\">Format with values inline. <span class=\"cs-bold\">:.2f</span> formats a float to two decimals. <span class=\"cs-bold\">,</span> adds thousand separators.</p><pre class=\"cs-code\"><code>  <span class=\"cs-green\">f'Price: ${price:.2f}'</span>\n  <span class=\"cs-green\">f'Count: {count:,}'</span></code></pre></div><div class=\"cs-section\"><h4 class=\"cs-h\">TAG REFERENCE</h4><p class=\"cs-prose\"><span class=\"cs-amber\">amber</span> keywords/builtins. <span class=\"cs-teal\">teal</span> callables/types. <span class=\"cs-green\">green</span> strings. <span class=\"cs-blue\">blue</span> numerics. <span class=\"cs-purple\">purple</span> decorators. <span class=\"cs-red\">red</span> warnings/exceptions. <span class=\"cs-dim\">dim</span> asides. <span class=\"cs-bold\">bold</span> emphasis.</p></div>"},"tiers":{"1":"\u001b[1m\u001b[33mPYTHON \u00b7 TIER 1 CONCEPTS (INTRODUCTORY)\u001b[39m\u001b[22m\r\n\r\n  \u001b[90mThe first ten questions cover variables, simple collections, basic control flow, and the built-in conversions you'll use forever.\u001b[39m\r\n\r\n  Python is a high-level interpreted language. You don't declare variable types or compile anything. You write expressions and Python evaluates them. At this tier the goal is to bind values to names and pull them back out.\r\n\r\n\u001b[1m\u001b[33mBINDING NAMES\u001b[39m\u001b[22m\r\n\r\n  \u001b[33m=\u001b[39m is assignment, not equality. The right side is evaluated, then the result is bound to the name on the left.\r\n\r\n      garage_name = \u001b[32m'Terminal Auto'\u001b[39m\r\n      count = \u001b[34m42\u001b[39m\r\n      is_open = \u001b[33mTrue\u001b[39m\r\n\r\n  Single or double quotes both make strings. Pick one and stay consistent. \u001b[33mTrue\u001b[39m / \u001b[33mFalse\u001b[39m are capitalized. \u001b[33mNone\u001b[39m means \"no value.\"\r\n\r\n\u001b[1m\u001b[33mCOLLECTIONS\u001b[39m\u001b[22m\r\n\r\n  Two basic containers at this tier. Lists are ordered and mutable. Dictionaries map keys to values.\r\n\r\n      mechanics = [\u001b[32m'Kris'\u001b[39m, \u001b[32m'Alex'\u001b[39m, \u001b[32m'Sam'\u001b[39m]\r\n      customer  = {\u001b[32m'id'\u001b[39m: \u001b[34m1\u001b[39m, \u001b[32m'name'\u001b[39m: \u001b[32m'Alice'\u001b[39m}\r\n\r\n  \u001b[33mlen\u001b[39m(obj) returns the size. Brackets index into a list (zero-based) or look up a dict key.\r\n\r\n      mechanics[\u001b[34m0\u001b[39m]      \u001b[90m'Kris'\u001b[39m\r\n      customer[\u001b[32m'name'\u001b[39m] \u001b[90m'Alice'\u001b[39m\r\n\r\n\u001b[1m\u001b[33mCONVERSIONS\u001b[39m\u001b[22m\r\n\r\n  Python won't auto-cast strings and numbers. You convert explicitly.\r\n\r\n      year = \u001b[33mint\u001b[39m(\u001b[32m'2024'\u001b[39m)         \u001b[90m'2024' -> 2024\u001b[39m\r\n      price = \u001b[33mfloat\u001b[39m(\u001b[32m'15.50'\u001b[39m)     \u001b[90m'15.50' -> 15.5\u001b[39m\r\n      label = \u001b[33mstr\u001b[39m(\u001b[34m42\u001b[39m)             \u001b[90m42 -> '42'\u001b[39m\r\n\r\n  \u001b[31mint('hello') raises ValueError\u001b[39m. Conversions can fail. At Experienced tier you'll wrap them in try/except.\r\n\r\n\u001b[1m\u001b[33mCONDITIONALS\u001b[39m\u001b[22m\r\n\r\n  \u001b[33mif\u001b[39m runs a block when the condition is truthy. The colon and indentation aren't optional, they're the syntax.\r\n\r\n      \u001b[33mif\u001b[39m cost > \u001b[34m1000\u001b[39m:\r\n          \u001b[33mprint\u001b[39m(\u001b[32m'High'\u001b[39m)\r\n\r\n  Indent the block four spaces. Tabs technically work but mixing them with spaces is the most common syntax-error cause for beginners.\r\n\r\n\u001b[1m\u001b[33mOUTPUT\u001b[39m\u001b[22m\r\n\r\n  \u001b[33mprint\u001b[39m(x) writes x to stdout followed by a newline. With multiple arguments it joins them with a space.\r\n\r\n  NEXT TIER: loops, functions, and the workhorse built-ins like \u001b[33msum\u001b[39m, \u001b[33msorted\u001b[39m, \u001b[33mzip\u001b[39m. You'll also meet tuples, while loops, and string methods like \u001b[1m.split\u001b[22m() and \u001b[1m.count\u001b[22m().\r\n","2":"\u001b[1m\u001b[33mPYTHON \u00b7 TIER 2 CONCEPTS (AMATEUR)\u001b[39m\u001b[22m\r\n\r\n  \u001b[90mLoops, functions, and the iterables story. Once these click, you can write any procedural script.\u001b[39m\r\n\r\n\u001b[1m\u001b[33mFOR LOOPS\u001b[39m\u001b[22m\r\n\r\n  \u001b[33mfor\u001b[39m iterates over an iterable. Lists, strings, dicts, ranges, files, anything that implements iteration.\r\n\r\n      \u001b[33mfor\u001b[39m m \u001b[33min\u001b[39m mechanics:\r\n          \u001b[33mprint\u001b[39m(m)\r\n\r\n  The variable \u001b[1mm\u001b[22m takes each value in turn. The loop body runs once per item. No counter to manage by hand. If you need an index, use \u001b[33menumerate\u001b[39m() at Experienced tier.\r\n\r\n\u001b[1m\u001b[33mWHILE LOOPS\u001b[39m\u001b[22m\r\n\r\n  \u001b[33mwhile\u001b[39m runs as long as the condition is truthy. You manage the termination yourself. Common pattern: maintain a counter and stop at a threshold.\r\n\r\n      nums, i = [], \u001b[34m1\u001b[39m\r\n      \u001b[33mwhile\u001b[39m i <= \u001b[34m5\u001b[39m:\r\n          nums.append(i)\r\n          i += \u001b[34m1\u001b[39m\r\n\r\n  \u001b[31mForgetting to update the counter is the easiest way to hang Python.\u001b[39m Use \u001b[33mfor\u001b[39m when the iteration count is known up front.\r\n\r\n\u001b[1m\u001b[33mFUNCTIONS\u001b[39m\u001b[22m\r\n\r\n  \u001b[33mdef\u001b[39m declares a reusable block. The signature names the parameters. \u001b[33mreturn\u001b[39m sends a value back; without it the function returns None.\r\n\r\n      \u001b[33mdef\u001b[39m \u001b[36madd_two\u001b[39m(x, y):\r\n          \u001b[33mreturn\u001b[39m x + y\r\n\r\n  Functions don't have type annotations at this tier (we'll get there at Master). Parameters are positional by default but can be passed by name.\r\n\r\n\u001b[1m\u001b[33mTUPLES AND UNPACKING\u001b[39m\u001b[22m\r\n\r\n  Tuples are immutable, ordered sequences. Parentheses are optional. The killer feature is multi-assignment: a tuple on the right binds to a tuple of names on the left.\r\n\r\n      make, year = \u001b[32m'Nissan'\u001b[39m, \u001b[34m1996\u001b[39m\r\n      a, b = b, a            \u001b[90mswap without a temp\u001b[39m\r\n\r\n  Functions can return tuples to give back multiple values, and the caller unpacks the result.\r\n\r\n\u001b[1m\u001b[33mWORKHORSE BUILT-INS\u001b[39m\u001b[22m\r\n\r\n  \u001b[33msum\u001b[39m(iterable) totals numbers. \u001b[33msorted\u001b[39m(iterable) returns a new sorted list. \u001b[33msorted\u001b[39m([..], reverse=\u001b[33mTrue\u001b[39m) sorts high to low. \u001b[33mzip\u001b[39m(a, b) pairs two iterables element-wise.\r\n\r\n      \u001b[33mlist\u001b[39m(\u001b[33mzip\u001b[39m([\u001b[34m1\u001b[39m, \u001b[34m2\u001b[39m], [\u001b[32m'a'\u001b[39m, \u001b[32m'b'\u001b[39m]))   \u001b[90m[(1, 'a'), (2, 'b')]\u001b[39m\r\n\r\n  Strings have \u001b[1m.split\u001b[22m(sep) and \u001b[1m.count\u001b[22m(sub). Lists have \u001b[1m.append\u001b[22m, \u001b[1m.count\u001b[22m, \u001b[1m.sort\u001b[22m (in place).\r\n\r\n\u001b[1m\u001b[33mF-STRING BASICS\u001b[39m\u001b[22m\r\n\r\n  \u001b[32mf'...'\u001b[39m interpolates expressions. Curly braces hold the value.\r\n\r\n      \u001b[32mf'Hello, {name}'\u001b[39m\r\n\r\n  At Intermediate tier you'll learn formatting specifiers like \u001b[1m:.2f\u001b[22m and \u001b[1m:,\u001b[22m.\r\n\r\n  NEXT TIER: list and dict comprehensions, lambdas, \u001b[33mmap\u001b[39m and \u001b[33mfilter\u001b[39m, default arguments. The shift is from \"loop and append\" to \"describe the result.\"\r\n","3":"\u001b[1m\u001b[33mPYTHON \u00b7 TIER 3 CONCEPTS (INTERMEDIATE)\u001b[39m\u001b[22m\r\n\r\n  \u001b[90mThe shift this tier: from imperative \"do these steps\" to declarative \"describe the result.\" Comprehensions, lambdas, and the functional triad (map, filter, reduce-style) all serve that shift.\u001b[39m\r\n\r\n\u001b[1m\u001b[33mLIST COMPREHENSIONS\u001b[39m\u001b[22m\r\n\r\n  A comprehension is a one-line expression that builds a collection from an iterable. Three pieces: the output expression, the \u001b[33mfor\u001b[39m clause, and an optional \u001b[33mif\u001b[39m filter.\r\n\r\n      squared    = [x**\u001b[34m2\u001b[39m \u001b[33mfor\u001b[39m x \u001b[33min\u001b[39m nums]\r\n      high       = [p \u001b[33mfor\u001b[39m p \u001b[33min\u001b[39m prices \u001b[33mif\u001b[39m p > \u001b[34m500\u001b[39m]\r\n      labeled    = [(name, len(name)) \u001b[33mfor\u001b[39m name \u001b[33min\u001b[39m mechanics]\r\n\r\n  \u001b[90mRead it left-to-right: \"for each x in nums, give me x squared.\" The filter, when present, runs before the output expression.\u001b[39m\r\n\r\n\u001b[1m\u001b[33mDICT AND SET COMPREHENSIONS\u001b[39m\u001b[22m\r\n\r\n  Same shape, different braces. Dict comprehensions need a key:value pair in the output expression.\r\n\r\n      squares = {x: x**\u001b[34m2\u001b[39m \u001b[33mfor\u001b[39m x \u001b[33min\u001b[39m \u001b[33mrange\u001b[39m(\u001b[34m1\u001b[39m, \u001b[34m6\u001b[39m)}\r\n      lower   = {tag.lower() \u001b[33mfor\u001b[39m tag \u001b[33min\u001b[39m tags}\r\n\r\n\u001b[1m\u001b[33mLAMBDAS\u001b[39m\u001b[22m\r\n\r\n  An anonymous, single-expression function. Useful as an argument to higher-order functions like \u001b[33msorted\u001b[39m, \u001b[33mmap\u001b[39m, \u001b[33mfilter\u001b[39m. No statements, just an expression.\r\n\r\n      sorted(people, key=\u001b[33mlambda\u001b[39m p: p[\u001b[32m'age'\u001b[39m])\r\n\r\n  \u001b[90mIf your lambda is more than one expression, write a real function with \u001b[39m\u001b[33mdef\u001b[39m\u001b[90m. Readability matters more than brevity.\u001b[39m\r\n\r\n\u001b[1m\u001b[33mMAP, FILTER, AND THE COMPREHENSION TRADEOFF\u001b[39m\u001b[22m\r\n\r\n  \u001b[33mmap\u001b[39m(fn, iter) applies fn to every element. \u001b[33mfilter\u001b[39m(pred, iter) keeps elements where pred is truthy. Both return iterators, so you usually wrap them in \u001b[33mlist\u001b[39m().\r\n\r\n      \u001b[33mlist\u001b[39m(\u001b[33mmap\u001b[39m(\u001b[33mlambda\u001b[39m x: x * \u001b[34m2\u001b[39m, nums))\r\n      \u001b[33mlist\u001b[39m(\u001b[33mfilter\u001b[39m(\u001b[33mlambda\u001b[39m x: x % \u001b[34m2\u001b[39m == \u001b[34m0\u001b[39m, nums))\r\n\r\n  Most Pythonistas prefer comprehensions for these because the syntax is more direct: \u001b[1m[x*2 for x in nums]\u001b[22m vs the map version. Both are correct. Comprehensions chain better and skip the \u001b[33mlist\u001b[39m() wrapper.\r\n\r\n\u001b[1m\u001b[33mDEFAULT ARGUMENTS AND .get()\u001b[39m\u001b[22m\r\n\r\n  Function defaults handle \"usually this, sometimes that\" without a wrapper. \u001b[1mdict.get\u001b[22m(key, default) does the same thing for dictionary lookups.\r\n\r\n      \u001b[33mdef\u001b[39m \u001b[36mtotal_with_tax\u001b[39m(amount, rate=\u001b[34m0.08\u001b[39m):\r\n          \u001b[33mreturn\u001b[39m amount * (\u001b[34m1\u001b[39m + rate)\r\n\r\n      d.get(\u001b[32m'missing'\u001b[39m, \u001b[34m0\u001b[39m)\r\n\r\n  \u001b[90mBoth protect you from \"this thing might not be present.\" Pick the form that fits the call site.\u001b[39m\r\n\r\n\u001b[1m\u001b[33mSETS\u001b[39m\u001b[22m\r\n\r\n  Unordered collections of unique elements. Useful when you need fast membership tests or set algebra. \u001b[1ma & b\u001b[22m is intersection, \u001b[1ma | b\u001b[22m is union, \u001b[1ma - b\u001b[22m is difference.\r\n\r\n\u001b[1m\u001b[33mF-STRING FORMATTING\u001b[39m\u001b[22m\r\n\r\n  Specifiers go after a colon inside the brace. \u001b[1m:.2f\u001b[22m is two-decimal float. \u001b[1m:,\u001b[22m is thousand separators. They compose: \u001b[1m:,.2f\u001b[22m.\r\n\r\n      \u001b[32mf'Price: ${price:.2f}'\u001b[39m    \u001b[90mPrice: $1500.00\u001b[39m\r\n      \u001b[32mf'Count: {n:,}'\u001b[39m            \u001b[90mCount: 1,234,567\u001b[39m\r\n\r\n  \u001b[90mML aside: comprehensions and lambdas are how you transform features in preprocessing pipelines without reaching for pandas or numpy. The \"describe the result\" mindset translates directly to vectorized operations.\u001b[39m\r\n\r\n  NEXT TIER: classes, exception handling, and the standard-library data structures (Counter, defaultdict). Once you can model entities and handle error paths, you can build real applications.\r\n","4":"\u001b[1m\u001b[33mPYTHON \u00b7 TIER 4 CONCEPTS (EXPERIENCED)\u001b[39m\u001b[22m\r\n\r\n  \u001b[90mObject-oriented building blocks plus the standard-library data structures that make data wrangling a one-liner.\u001b[39m\r\n\r\n\u001b[1m\u001b[33mCLASSES\u001b[39m\u001b[22m\r\n\r\n  A class defines a type. An instance is an object of that type. The \u001b[1m__init__\u001b[22m method runs at construction time. \u001b[1mself\u001b[22m is the current instance, passed implicitly when you call a method on an object.\r\n\r\n      \u001b[33mclass\u001b[39m \u001b[36mWorkOrder\u001b[39m:\r\n          \u001b[33mdef\u001b[39m \u001b[36m__init__\u001b[39m(self, id, cost, status):\r\n              self.id = id\r\n              self.cost = cost\r\n              self.status = status\r\n          \u001b[33mdef\u001b[39m \u001b[36mis_open\u001b[39m(self):\r\n              \u001b[33mreturn\u001b[39m self.status == \u001b[32m'Open'\u001b[39m\r\n\r\n  Construct with \u001b[1mWorkOrder(1, 100, 'Open')\u001b[22m. Call methods with \u001b[1morder.is_open()\u001b[22m. Attributes are accessed with dot notation.\r\n\r\n\u001b[1m\u001b[33mINHERITANCE\u001b[39m\u001b[22m\r\n\r\n  \u001b[33mclass\u001b[39m Child(Parent) inherits Parent's attributes and methods. Add new methods or override existing ones. \u001b[1msuper()\u001b[22m calls the parent's version when you need to extend rather than replace.\r\n\r\n      \u001b[33mclass\u001b[39m \u001b[36mSportsCar\u001b[39m(\u001b[36mVehicle\u001b[39m):\r\n          \u001b[33mdef\u001b[39m \u001b[36mis_fast\u001b[39m(self):\r\n              \u001b[33mreturn\u001b[39m \u001b[33mTrue\u001b[39m\r\n\r\n  \u001b[90mInheritance is one of three ways to share code (composition and duck-typing are the others). Use it when the relationship is genuinely \"is-a.\" A SportsCar is-a Vehicle. A Customer is not-a Address.\u001b[39m\r\n\r\n\u001b[1m\u001b[33mDUNDER METHODS\u001b[39m\u001b[22m\r\n\r\n  Methods named \u001b[1m__name__\u001b[22m hook into Python syntax. \u001b[1m__str__\u001b[22m controls what \u001b[33mstr\u001b[39m(obj) returns. \u001b[1m__repr__\u001b[22m controls \u001b[33mrepr\u001b[39m(obj). \u001b[1m__eq__\u001b[22m controls \u001b[1m==\u001b[22m. There are dozens.\r\n\r\n      \u001b[33mdef\u001b[39m \u001b[36m__str__\u001b[39m(self):\r\n          \u001b[33mreturn\u001b[39m \u001b[32mf'Mechanic: {self.name}'\u001b[39m\r\n\r\n\u001b[1m\u001b[33mDECORATORS ON METHODS\u001b[39m\u001b[22m\r\n\r\n  \u001b[35m@property\u001b[39m turns a method into a read-only attribute. The caller uses \u001b[1mobj.tax\u001b[22m not \u001b[1mobj.tax()\u001b[22m.\r\n\r\n      \u001b[35m@property\u001b[39m\r\n      \u001b[33mdef\u001b[39m \u001b[36mtax\u001b[39m(self):\r\n          \u001b[33mreturn\u001b[39m self.cost * \u001b[34m0.08\u001b[39m\r\n\r\n  \u001b[35m@staticmethod\u001b[39m removes the implicit \u001b[1mself\u001b[22m. Use it for utility functions that logically belong on the class but don't need instance state.\r\n\r\n\u001b[1m\u001b[33mEXCEPTIONS\u001b[39m\u001b[22m\r\n\r\n  \u001b[33mtry\u001b[39m runs a block. \u001b[33mexcept\u001b[39m catches a specific exception class. \u001b[33melse\u001b[39m runs if no exception. \u001b[33mfinally\u001b[39m runs either way.\r\n\r\n      \u001b[33mtry\u001b[39m:\r\n          result = a / b\r\n      \u001b[33mexcept\u001b[39m \u001b[31mZeroDivisionError\u001b[39m:\r\n          result = \u001b[33mNone\u001b[39m\r\n\r\n  \u001b[31mBare except: catches everything including KeyboardInterrupt\u001b[39m. Always catch the specific class.\r\n\r\n\u001b[1m\u001b[33mCOLLECTIONS LIBRARY\u001b[39m\u001b[22m\r\n\r\n  \u001b[1mCounter\u001b[22m tallies hashable items. Pass it an iterable, get back a dict-like with counts.\r\n\r\n      \u001b[33mfrom\u001b[39m collections \u001b[33mimport\u001b[39m \u001b[36mCounter\u001b[39m\r\n      \u001b[36mCounter\u001b[39m([\u001b[32m'red'\u001b[39m, \u001b[32m'blue'\u001b[39m, \u001b[32m'red'\u001b[39m])\r\n      \u001b[90mCounter({'red': 2, 'blue': 1})\u001b[39m\r\n\r\n  \u001b[1mdefaultdict(int)\u001b[22m is a dict that creates default values on missing keys, replacing the \u001b[1mif k not in d: d[k] = 0\u001b[22m dance. Pass any zero-arg callable: \u001b[33mint\u001b[39m (gives 0), \u001b[33mlist\u001b[39m (gives []), \u001b[33mset\u001b[39m (gives set()).\r\n\r\n\u001b[1m\u001b[33mENUMERATE\u001b[39m\u001b[22m\r\n\r\n  \u001b[33menumerate\u001b[39m(iter) yields (index, item) pairs. Cleaner than running your own counter alongside the loop.\r\n\r\n      \u001b[33mfor\u001b[39m i, item \u001b[33min\u001b[39m \u001b[33menumerate\u001b[39m(items):\r\n          \u001b[33mprint\u001b[39m(i, item)\r\n\r\n  NEXT TIER: generators, decorators, closures, recursion, \u001b[33mfunctools\u001b[39m tricks. Anything that treats functions themselves as values to compose.\r\n","5":"\u001b[1m\u001b[33mPYTHON \u00b7 TIER 5 CONCEPTS (MASTER)\u001b[39m\u001b[22m\r\n\r\n  \u001b[90mThe mental model that makes everything else click: in Python, functions are values. You pass them, return them, decorate them, and close over their environment. The same machinery that makes generators lazy makes decorators declarative.\u001b[39m\r\n\r\n\u001b[1m\u001b[33mGENERATORS\u001b[39m\u001b[22m\r\n\r\n  A function that contains \u001b[33myield\u001b[39m is a generator. Each \u001b[33myield\u001b[39m produces a value and pauses execution. The next call resumes where it left off. State persists across yields without you wiring it up.\r\n\r\n      \u001b[33mdef\u001b[39m \u001b[36mcount_up_to\u001b[39m(n):\r\n          \u001b[33mfor\u001b[39m i \u001b[33min\u001b[39m \u001b[33mrange\u001b[39m(\u001b[34m1\u001b[39m, n + \u001b[34m1\u001b[39m):\r\n              \u001b[33myield\u001b[39m i\r\n\r\n  \u001b[1mlist(count_up_to(4))\u001b[22m gives \u001b[1m[1, 2, 3, 4]\u001b[22m. The list call drives the generator to exhaustion. In a \u001b[33mfor\u001b[39m loop the generator yields one value per iteration with no intermediate list.\r\n\r\n  \u001b[90mThis is how the entire iterator protocol works. Files, ranges, enumerate, zip, dict.items() are all driven by the same yield-style pause-and-resume mechanism.\u001b[39m\r\n\r\n\u001b[1m\u001b[33mCLOSURES AND NONLOCAL\u001b[39m\u001b[22m\r\n\r\n  An inner function \"closes over\" the names visible at definition. Mutating those names from inside requires \u001b[33mnonlocal\u001b[39m (for enclosing scope) or \u001b[33mglobal\u001b[39m (for module scope). Reading is automatic.\r\n\r\n      \u001b[33mdef\u001b[39m \u001b[36mmake_counter\u001b[39m():\r\n          n = \u001b[34m0\u001b[39m\r\n          \u001b[33mdef\u001b[39m \u001b[36minner\u001b[39m():\r\n              \u001b[33mnonlocal\u001b[39m n\r\n              n += \u001b[34m1\u001b[39m\r\n              \u001b[33mreturn\u001b[39m n\r\n          \u001b[33mreturn\u001b[39m inner\r\n\r\n  Each call to \u001b[1mmake_counter()\u001b[22m creates a fresh \u001b[1mn\u001b[22m in a fresh scope. The returned \u001b[1minner\u001b[22m keeps a private reference to it. This is how state lives inside functional-looking code.\r\n\r\n\u001b[1m\u001b[33mDECORATORS\u001b[39m\u001b[22m\r\n\r\n  A decorator is a function that takes a function and returns a function. \u001b[35m@name\u001b[39m above a \u001b[33mdef\u001b[39m is sugar for \u001b[1mfn = name(fn)\u001b[22m.\r\n\r\n      \u001b[33mdef\u001b[39m \u001b[36mdouble\u001b[39m(fn):\r\n          \u001b[33mdef\u001b[39m \u001b[36mwrapper\u001b[39m(*a, **kw):\r\n              \u001b[33mreturn\u001b[39m fn(*a, **kw) * \u001b[34m2\u001b[39m\r\n          \u001b[33mreturn\u001b[39m wrapper\r\n\r\n      \u001b[35m@double\u001b[39m\r\n      \u001b[33mdef\u001b[39m \u001b[36mval\u001b[39m(): \u001b[33mreturn\u001b[39m \u001b[34m21\u001b[39m\r\n\r\n  \u001b[1mval()\u001b[22m now returns 42. The wrapper closure intercepts every call and transforms the result. Logging, retries, caching, timing, auth checks are all decorators in production code. \u001b[35m@functools.lru_cache\u001b[39m is memoization in one line.\r\n\r\n\u001b[1m\u001b[33mRECURSION AND MEMOIZATION\u001b[39m\u001b[22m\r\n\r\n  A recursive function calls itself with a smaller argument and a base case. Pure recursion blows up on overlapping subproblems. Caching the results (\u001b[1mmemoization\u001b[22m) restores polynomial behavior.\r\n\r\n      cache = {}\r\n      \u001b[33mdef\u001b[39m \u001b[36mfib\u001b[39m(n):\r\n          \u001b[33mif\u001b[39m n \u001b[33min\u001b[39m cache: \u001b[33mreturn\u001b[39m cache[n]\r\n          \u001b[33mif\u001b[39m n < \u001b[34m2\u001b[39m: \u001b[33mreturn\u001b[39m n\r\n          cache[n] = \u001b[36mfib\u001b[39m(n-\u001b[34m1\u001b[39m) + \u001b[36mfib\u001b[39m(n-\u001b[34m2\u001b[39m)\r\n          \u001b[33mreturn\u001b[39m cache[n]\r\n\r\n  \u001b[90mML aside: this is exactly the dynamic-programming trick used in Viterbi decoding, RNN forward passes, and any pipeline where overlapping subcomputations would otherwise dominate the cost.\u001b[39m\r\n\r\n\u001b[1m\u001b[33mREDUCE\u001b[39m\u001b[22m\r\n\r\n  \u001b[33mfunctools.reduce\u001b[39m(fn, iter) folds an iterable to a single value using a binary function. \u001b[33msum\u001b[39m is reduce with addition. \u001b[33mmax\u001b[39m is reduce with the larger-of-two function.\r\n\r\n      \u001b[33mfrom\u001b[39m functools \u001b[33mimport\u001b[39m \u001b[36mreduce\u001b[39m\r\n      \u001b[36mreduce\u001b[39m(\u001b[33mlambda\u001b[39m a, b: a + b, nums)\r\n\r\n  Mostly the built-ins (\u001b[33msum\u001b[39m, \u001b[33mmax\u001b[39m, \u001b[33mmin\u001b[39m) are clearer. Reach for \u001b[33mreduce\u001b[39m when the operation is custom: building a tree, composing transforms, applying a reduction not in the stdlib.\r\n\r\n\u001b[1m\u001b[33mNAMEDTUPLE AND DATACLASS\u001b[39m\u001b[22m\r\n\r\n  Two ways to define a record type without writing \u001b[1m__init__\u001b[22m yourself.\r\n\r\n      \u001b[33mfrom\u001b[39m collections \u001b[33mimport\u001b[39m \u001b[36mnamedtuple\u001b[39m\r\n      \u001b[36mPoint\u001b[39m = \u001b[36mnamedtuple\u001b[39m(\u001b[32m'Point'\u001b[39m, [\u001b[32m'x'\u001b[39m, \u001b[32m'y'\u001b[39m]])\r\n      p = \u001b[36mPoint\u001b[39m(\u001b[34m3\u001b[39m, \u001b[34m4\u001b[39m)\r\n      p.x, p[\u001b[34m0\u001b[39m]    \u001b[90mboth work\u001b[39m\r\n\r\n      \u001b[33mfrom\u001b[39m dataclasses \u001b[33mimport\u001b[39m \u001b[36mdataclass\u001b[39m\r\n      \u001b[35m@dataclass\u001b[39m\r\n      \u001b[33mclass\u001b[39m \u001b[36mCar\u001b[39m:\r\n          make: \u001b[36mstr\u001b[39m\r\n          year: \u001b[36mint\u001b[39m\r\n\r\n  \u001b[90mnamedtuple is immutable, lightweight, and tuple-compatible. dataclass is mutable by default, takes type hints, and gives you __eq__ / __repr__ / __init__ for free. Use namedtuple for value objects you'll never mutate. Use dataclass for everything else.\u001b[39m\r\n\r\n\u001b[1m\u001b[33mTHE ML CONNECTION\u001b[39m\u001b[22m\r\n\r\n  Generators are the pattern behind data loaders streaming batches without materializing the dataset. Decorators are how training-loop annotations (\u001b[35m@torch.no_grad\u001b[39m, \u001b[35m@tf.function\u001b[39m) hook in without changing the function body. Closures are how \u001b[1moptimizer.step\u001b[22m retains a reference to the model parameters. Recursion + memoization is the pattern behind any DP-style inference algorithm.\r\n\r\n  The Python tier ends here. The next axis is libraries: numpy for vectorized math, pandas for tabular data, then a deep-learning framework. But the language itself doesn't get harder than what's above.\r\n"},"examples":{"1":["\u001b[1m\u001b[33mEXAMPLE 1\u001b[39m\u001b[22m\r\n\r\n  Bind a few names and read them back. Python figures out the types.\r\n\r\n      shop = \u001b[32m'Terminal Auto'\u001b[39m\r\n      open_jobs = \u001b[34m7\u001b[39m\r\n      avg_ticket = \u001b[34m412.50\u001b[39m\r\n      \u001b[33mprint\u001b[39m(shop, open_jobs, avg_ticket)\r\n\r\n  \u001b[90mOne assignment per line. The output prints the three values space-separated because that's what print does with multiple args.\u001b[39m\r\n","\u001b[1m\u001b[33mEXAMPLE 2\u001b[39m\u001b[22m\r\n\r\n  Build a small dict and read a value out. Square brackets do lookup.\r\n\r\n      car = {\u001b[32m'make'\u001b[39m: \u001b[32m'Nissan'\u001b[39m, \u001b[32m'model'\u001b[39m: \u001b[32m'Skyline GT-R'\u001b[39m, \u001b[32m'year'\u001b[39m: \u001b[34m1996\u001b[39m}\r\n      \u001b[33mprint\u001b[39m(car[\u001b[32m'make'\u001b[39m])\r\n\r\n  \u001b[90mLooking up a missing key raises KeyError. At Intermediate tier you'll meet \u001b[39m\u001b[1m.get\u001b[22m(\u001b[32m'k'\u001b[39m, default)\u001b[90m for safe access. See \u001b[39m\u001b[34m\u001b[4mpy_int_08\u001b[24m\u001b[39m\u001b[90m.\u001b[39m\r\n","\u001b[1m\u001b[33mEXAMPLE 3\u001b[39m\u001b[22m\r\n\r\n  Branch on a value, previewing loops at the next tier. You can already check one item at a time:\r\n\r\n      cost = \u001b[34m1500\u001b[39m\r\n      \u001b[33mif\u001b[39m cost > \u001b[34m1000\u001b[39m:\r\n          \u001b[33mprint\u001b[39m(\u001b[32m'High'\u001b[39m)\r\n      \u001b[33melse\u001b[39m:\r\n          \u001b[33mprint\u001b[39m(\u001b[32m'Low'\u001b[39m)\r\n\r\n  \u001b[90mAt Amateur tier a \u001b[39m\u001b[33mfor\u001b[39m\u001b[90m loop runs the same check across every item in a list automatically. The branching shape stays identical; the loop just feeds the variable repeatedly. See \u001b[39m\u001b[34m\u001b[4mpy_am_01\u001b[24m\u001b[39m\u001b[90m.\u001b[39m\r\n"],"2":["\u001b[1m\u001b[33mEXAMPLE 1\u001b[39m\u001b[22m\r\n\r\n  Iterate a list and accumulate. Vanilla for-loop pattern.\r\n\r\n      total_cost = \u001b[34m0\u001b[39m\r\n      \u001b[33mfor\u001b[39m order \u001b[33min\u001b[39m [\u001b[34m100\u001b[39m, \u001b[34m250\u001b[39m, \u001b[34m75\u001b[39m, \u001b[34m300\u001b[39m]:\r\n          total_cost += order\r\n      \u001b[33mprint\u001b[39m(total_cost)\r\n\r\n  \u001b[90mThis is what \u001b[39m\u001b[33msum\u001b[39m()\u001b[90m does internally. The built-in is shorter and faster. Reach for it whenever you see \"loop, accumulate, return the total.\"\u001b[39m\r\n","\u001b[1m\u001b[33mEXAMPLE 2\u001b[39m\u001b[22m\r\n\r\n  Define a function with a default argument. Defaults are evaluated once at definition time.\r\n\r\n      \u001b[33mdef\u001b[39m \u001b[36mmarkup\u001b[39m(base, rate=\u001b[34m0.20\u001b[39m):\r\n          \u001b[33mreturn\u001b[39m base * (\u001b[34m1\u001b[39m + rate)\r\n\r\n      \u001b[33mprint\u001b[39m(\u001b[36mmarkup\u001b[39m(\u001b[34m100\u001b[39m))         \u001b[90m120.0 (rate defaulted)\u001b[39m\r\n      \u001b[33mprint\u001b[39m(\u001b[36mmarkup\u001b[39m(\u001b[34m100\u001b[39m, \u001b[34m0.40\u001b[39m))   \u001b[90m140.0 (rate explicit)\u001b[39m\r\n\r\n  \u001b[90mA subtle gotcha: never use mutable default values like an empty list or empty dict. They share state across calls. Use None and assign inside the body.\u001b[39m\r\n","\u001b[1m\u001b[33mEXAMPLE 3\u001b[39m\u001b[22m\r\n\r\n  Build a list with a loop, previewing list comprehensions. Right now:\r\n\r\n      doubled = []\r\n      \u001b[33mfor\u001b[39m x \u001b[33min\u001b[39m [\u001b[34m1\u001b[39m, \u001b[34m2\u001b[39m, \u001b[34m3\u001b[39m, \u001b[34m4\u001b[39m]:\r\n          doubled.append(x * \u001b[34m2\u001b[39m)\r\n\r\n  \u001b[90mAt the next tier the same logic compresses to one line:\u001b[39m\r\n\r\n  \u001b[90m\u001b[39m      doubled = [x * \u001b[34m2\u001b[39m \u001b[33mfor\u001b[39m x \u001b[33min\u001b[39m [\u001b[34m1\u001b[39m, \u001b[34m2\u001b[39m, \u001b[34m3\u001b[39m, \u001b[34m4\u001b[39m]]\r\n\r\n  \u001b[90mSame loop, same result, but the shape of the code matches the shape of the data: one input per output. See \u001b[39m\u001b[34m\u001b[4mpy_int_06\u001b[24m\u001b[39m\u001b[90m.\u001b[39m\r\n"],"3":["\u001b[1m\u001b[33mEXAMPLE 1\u001b[39m\u001b[22m\r\n\r\n  Comprehension with a filter. The shape is \u001b[1m[output for item in iter if predicate]\u001b[22m.\r\n\r\n      orders = [{\u001b[32m'cost'\u001b[39m: \u001b[34m100\u001b[39m, \u001b[32m'status'\u001b[39m: \u001b[32m'Open'\u001b[39m},\r\n                {\u001b[32m'cost'\u001b[39m: \u001b[34m250\u001b[39m, \u001b[32m'status'\u001b[39m: \u001b[32m'Closed'\u001b[39m},\r\n                {\u001b[32m'cost'\u001b[39m: \u001b[34m75\u001b[39m,  \u001b[32m'status'\u001b[39m: \u001b[32m'Open'\u001b[39m}]\r\n      open_costs = [o[\u001b[32m'cost'\u001b[39m] \u001b[33mfor\u001b[39m o \u001b[33min\u001b[39m orders \u001b[33mif\u001b[39m o[\u001b[32m'status'\u001b[39m] == \u001b[32m'Open'\u001b[39m]\r\n      \u001b[33mprint\u001b[39m(\u001b[33msum\u001b[39m(open_costs))    \u001b[90m175\u001b[39m\r\n\r\n  \u001b[90mReplace the for-loop-with-append-and-condition pattern with this. Same result, half the lines, easier to read once you've internalized the shape.\u001b[39m\r\n","\u001b[1m\u001b[33mEXAMPLE 2\u001b[39m\u001b[22m\r\n\r\n  Sort by a derived key with a lambda. Without a key, sorted compares whole elements. With one, sorted compares whatever the key returns.\r\n\r\n      people = [{\u001b[32m'name'\u001b[39m: \u001b[32m'Dave'\u001b[39m, \u001b[32m'age'\u001b[39m: \u001b[34m30\u001b[39m},\r\n                {\u001b[32m'name'\u001b[39m: \u001b[32m'Emily'\u001b[39m, \u001b[32m'age'\u001b[39m: \u001b[34m22\u001b[39m}]\r\n      youngest_first = \u001b[33msorted\u001b[39m(people, key=\u001b[33mlambda\u001b[39m p: p[\u001b[32m'age'\u001b[39m])\r\n\r\n  \u001b[90mAdd reverse=True to flip the order. Pass tuples in the key for tiebreakers: key=lambda p: (p\u001b[39m\u001b[32m'team'\u001b[39m\u001b[90m, -p\u001b[39m\u001b[32m'score'\u001b[39m\u001b[90m) sorts by team ascending then by score descending.\u001b[39m\r\n","\u001b[1m\u001b[33mEXAMPLE 3\u001b[39m\u001b[22m\r\n\r\n  Class-shaped data, previewing OOP at the next tier. Right now you model an entity as a dict and act on it with functions:\r\n\r\n      \u001b[33mdef\u001b[39m \u001b[36mis_open\u001b[39m(order):\r\n          \u001b[33mreturn\u001b[39m order[\u001b[32m'status'\u001b[39m] == \u001b[32m'Open'\u001b[39m\r\n\r\n      orders = [{\u001b[32m'cost'\u001b[39m: \u001b[34m100\u001b[39m, \u001b[32m'status'\u001b[39m: \u001b[32m'Open'\u001b[39m}, ...]\r\n      open_jobs = [o \u001b[33mfor\u001b[39m o \u001b[33min\u001b[39m orders \u001b[33mif\u001b[39m \u001b[36mis_open\u001b[39m(o)]\r\n\r\n  \u001b[90mAt Experienced tier the function moves onto the entity itself:\u001b[39m\r\n\r\n  \u001b[90m\u001b[39m      \u001b[33mclass\u001b[39m \u001b[36mWorkOrder\u001b[39m:\r\n          \u001b[33mdef\u001b[39m \u001b[36m__init__\u001b[39m(self, cost, status): ...\r\n          \u001b[33mdef\u001b[39m \u001b[36mis_open\u001b[39m(self): \u001b[33mreturn\u001b[39m self.status == \u001b[32m'Open'\u001b[39m\r\n\r\n  \u001b[90mSame logic, different attachment point. See \u001b[39m\u001b[34m\u001b[4mpy_exp_01\u001b[24m\u001b[39m\u001b[90m.\u001b[39m\r\n"],"4":["\u001b[1m\u001b[33mEXAMPLE 1\u001b[39m\u001b[22m\r\n\r\n  A class that combines \u001b[1m__init__\u001b[22m, a regular method, and a \u001b[35m@property\u001b[39m. This is the canonical \"domain object\" shape.\r\n\r\n      \u001b[33mclass\u001b[39m \u001b[36mOrder\u001b[39m:\r\n          \u001b[33mdef\u001b[39m \u001b[36m__init__\u001b[39m(self, cost, status):\r\n              self.cost = cost\r\n              self.status = status\r\n          \u001b[35m@property\u001b[39m\r\n          \u001b[33mdef\u001b[39m \u001b[36mtax\u001b[39m(self):\r\n              \u001b[33mreturn\u001b[39m self.cost * \u001b[34m0.08\u001b[39m\r\n          \u001b[33mdef\u001b[39m \u001b[36mis_open\u001b[39m(self):\r\n              \u001b[33mreturn\u001b[39m self.status == \u001b[32m'Open'\u001b[39m\r\n\r\n      o = \u001b[36mOrder\u001b[39m(\u001b[34m100\u001b[39m, \u001b[32m'Open'\u001b[39m)\r\n      \u001b[33mprint\u001b[39m(o.tax)         \u001b[90m8.0    (no parens, it's a property)\u001b[39m\r\n      \u001b[33mprint\u001b[39m(o.is_open())   \u001b[90mTrue   (parens, it's a method)\u001b[39m\r\n","\u001b[1m\u001b[33mEXAMPLE 2\u001b[39m\u001b[22m\r\n\r\n  Tally a list with Counter, then read the most common entries. Replaces twenty lines of dict bookkeeping.\r\n\r\n      \u001b[33mfrom\u001b[39m collections \u001b[33mimport\u001b[39m \u001b[36mCounter\u001b[39m\r\n      tags = [\u001b[32m'open'\u001b[39m, \u001b[32m'open'\u001b[39m, \u001b[32m'closed'\u001b[39m, \u001b[32m'open'\u001b[39m, \u001b[32m'wip'\u001b[39m]\r\n      counts = \u001b[36mCounter\u001b[39m(tags)\r\n      \u001b[33mprint\u001b[39m(counts)               \u001b[90mCounter({'open': 3, 'closed': 1, 'wip': 1})\u001b[39m\r\n      \u001b[33mprint\u001b[39m(counts.most_common(\u001b[34m2\u001b[39m))  \u001b[90m[('open', 3), ('closed', 1)]\u001b[39m\r\n\r\n  \u001b[90mCounter is the data structure that powers most \"frequency analysis\" tasks: word counts, label distributions, bag-of-words features.\u001b[39m\r\n","\u001b[1m\u001b[33mEXAMPLE 3\u001b[39m\u001b[22m\r\n\r\n  Generators, previewing the next tier. Right now you build a list eagerly:\r\n\r\n      \u001b[33mdef\u001b[39m \u001b[36mfirst_n_squares\u001b[39m(n):\r\n          result = []\r\n          \u001b[33mfor\u001b[39m i \u001b[33min\u001b[39m \u001b[33mrange\u001b[39m(\u001b[34m1\u001b[39m, n + \u001b[34m1\u001b[39m):\r\n              result.append(i * i)\r\n          \u001b[33mreturn\u001b[39m result\r\n\r\n  \u001b[90mAt Master tier you'll use \u001b[39m\u001b[33myield\u001b[39m\u001b[90m to produce values lazily, one at a time:\u001b[39m\r\n\r\n  \u001b[90m\u001b[39m      \u001b[33mdef\u001b[39m \u001b[36msquares\u001b[39m(n):\r\n          \u001b[33mfor\u001b[39m i \u001b[33min\u001b[39m \u001b[33mrange\u001b[39m(\u001b[34m1\u001b[39m, n + \u001b[34m1\u001b[39m):\r\n              \u001b[33myield\u001b[39m i * i\r\n\r\n  \u001b[90mThe generator computes each value on demand. It uses constant memory even for huge n, and you can pipe it through other iterators without materializing the whole list. See \u001b[39m\u001b[34m\u001b[4mpy_mas_03\u001b[24m\u001b[39m\u001b[90m.\u001b[39m\r\n"],"5":["\u001b[1m\u001b[33mEXAMPLE 1\u001b[39m\u001b[22m\r\n\r\n  A decorator that times a function. Real-world decorators are this shape: wrap, do something around the call, return the result.\r\n\r\n      \u001b[33mimport\u001b[39m time\r\n\r\n      \u001b[33mdef\u001b[39m \u001b[36mtimed\u001b[39m(fn):\r\n          \u001b[33mdef\u001b[39m \u001b[36mwrapper\u001b[39m(*a, **kw):\r\n              start = time.perf_counter()\r\n              result = fn(*a, **kw)\r\n              elapsed = time.perf_counter() - start\r\n              \u001b[33mprint\u001b[39m(\u001b[32mf'{fn.__name__} took {elapsed:.4f}s'\u001b[39m)\r\n              \u001b[33mreturn\u001b[39m result\r\n          \u001b[33mreturn\u001b[39m wrapper\r\n\r\n      \u001b[35m@timed\u001b[39m\r\n      \u001b[33mdef\u001b[39m \u001b[36mheavy\u001b[39m():\r\n          \u001b[33mreturn\u001b[39m \u001b[33msum\u001b[39m(\u001b[33mrange\u001b[39m(\u001b[34m10**6\u001b[39m))\r\n\r\n      \u001b[36mheavy\u001b[39m()    \u001b[90mheavy took 0.0142s\u001b[39m\r\n\r\n  \u001b[90mLogging frameworks, retry libraries, caching layers, and authorization hooks are all variations on this template. Read once, reach for it forever.\u001b[39m\r\n","\u001b[1m\u001b[33mEXAMPLE 2\u001b[39m\u001b[22m\r\n\r\n  A generator that streams transformed data without materializing the intermediate list. This is roughly how data pipelines work at scale.\r\n\r\n      \u001b[33mdef\u001b[39m \u001b[36mread_orders\u001b[39m(path):\r\n          \u001b[33mwith\u001b[39m \u001b[33mopen\u001b[39m(path) \u001b[33mas\u001b[39m f:\r\n              \u001b[33mfor\u001b[39m line \u001b[33min\u001b[39m f:\r\n                  yield line.strip().split(\u001b[32m','\u001b[39m)\r\n\r\n      \u001b[33mdef\u001b[39m \u001b[36mas_floats\u001b[39m(rows):\r\n          \u001b[33mfor\u001b[39m row \u001b[33min\u001b[39m rows:\r\n              \u001b[33myield\u001b[39m [\u001b[33mfloat\u001b[39m(x) \u001b[33mfor\u001b[39m x \u001b[33min\u001b[39m row]\r\n\r\n      \u001b[33mfor\u001b[39m cost, qty \u001b[33min\u001b[39m \u001b[36mas_floats\u001b[39m(\u001b[36mread_orders\u001b[39m(\u001b[32m'orders.csv'\u001b[39m)):\r\n          \u001b[33mprint\u001b[39m(cost * qty)\r\n\r\n  \u001b[90mTwo generators chained. Constant memory regardless of file size. This is the same pattern behind PyTorch's DataLoader and TensorFlow's tf.data.Dataset, just with batching and shuffling layered on.\u001b[39m\r\n","\u001b[1m\u001b[33mEXAMPLE 3\u001b[39m\u001b[22m\r\n\r\n  Putting it all together: a memoized recursive function defined with a decorator, applied to a problem that would be exponential without it. This is the production-ready pattern.\r\n\r\n      \u001b[33mfrom\u001b[39m functools \u001b[33mimport\u001b[39m \u001b[36mlru_cache\u001b[39m\r\n\r\n      \u001b[35m@lru_cache\u001b[39m(maxsize=\u001b[33mNone\u001b[39m)\r\n      \u001b[33mdef\u001b[39m \u001b[36mfib\u001b[39m(n):\r\n          \u001b[33mif\u001b[39m n < \u001b[34m2\u001b[39m:\r\n              \u001b[33mreturn\u001b[39m n\r\n          \u001b[33mreturn\u001b[39m \u001b[36mfib\u001b[39m(n - \u001b[34m1\u001b[39m) + \u001b[36mfib\u001b[39m(n - \u001b[34m2\u001b[39m)\r\n\r\n      \u001b[33mprint\u001b[39m(\u001b[36mfib\u001b[39m(\u001b[34m100\u001b[39m))\r\n\r\n  \u001b[90mWithout the decorator, fib(100) would do 1.7e21 calls. With it, 100. \u001b[39m\u001b[35m@lru_cache\u001b[39m\u001b[90m is closure + decorator + dict, all the ideas from this tier composed into a stdlib one-liner.\u001b[39m\r\n\r\n  \u001b[90mThat's the Python track. From \u001b[39m\u001b[32m'Hello, world'\u001b[39m\u001b[90m in tier 1 to a memoized recursive Fibonacci in five tiers. The vocabulary fits on a page; the patterns take longer to internalize. See \u001b[39m\u001b[34m\u001b[4mpy_mas_10\u001b[24m\u001b[39m\u001b[90m for the manual version of the same idea, then come back here when you want it in one line.\u001b[39m\r\n"]}},"javascript":{"cheatsheet":{"ansi":"\u001b[1m\u001b[33mJAVASCRIPT CHEATSHEET\u001b[39m\u001b[22m\r\n\r\n  \u001b[90mA working reference for the whole language. Skim it once, come back when stuck.\u001b[39m\r\n\r\n\u001b[1m\u001b[33mVARIABLES AND TYPES\u001b[39m\u001b[22m\r\n\r\n  Three declaration keywords. \u001b[33mconst\u001b[39m for values that won't be reassigned, \u001b[33mlet\u001b[39m for ones that will, \u001b[33mvar\u001b[39m for legacy code you're maintaining.\r\n\r\n      \u001b[33mconst\u001b[39m garage = \u001b[32m'Terminal Auto'\u001b[39m\r\n      \u001b[33mlet\u001b[39m count = \u001b[34m42\u001b[39m\r\n      \u001b[33mconst\u001b[39m active = \u001b[33mtrue\u001b[39m\r\n\r\n  \u001b[31mBooleans are lowercase\u001b[39m: \u001b[33mtrue\u001b[39m / \u001b[33mfalse\u001b[39m, not True/False. \u001b[33mnull\u001b[39m is \"no value\"; \u001b[33mundefined\u001b[39m is \"not yet set.\" They're different types and the distinction matters.\r\n\r\n\u001b[1m\u001b[33mCOLLECTIONS\u001b[39m\u001b[22m\r\n\r\n  Arrays are ordered, mutable, zero-indexed. Objects are key-value maps.\r\n\r\n      \u001b[33mconst\u001b[39m cars = [\u001b[32m'Skyline'\u001b[39m, \u001b[32m'Supra'\u001b[39m]\r\n      \u001b[33mconst\u001b[39m car = { make: \u001b[32m'Nissan'\u001b[39m, year: \u001b[34m1996\u001b[39m }\r\n\r\n  \u001b[1marr[i]\u001b[22m indexes. \u001b[1marr.length\u001b[22m is the count \u2014 a property, \u001b[31mno parentheses\u001b[39m. \u001b[1mobj.key\u001b[22m reads dot notation. \u001b[1mobj[k]\u001b[22m reads via a computed key. \u001b[90mSee \u001b[34m\u001b[4mjs_intro_07\u001b[24m\u001b[39m.\u001b[39m\r\n\r\n\u001b[1m\u001b[33mCONTROL FLOW\u001b[39m\u001b[22m\r\n\r\n  \u001b[33mif\u001b[39m / \u001b[33melse if\u001b[39m / \u001b[33melse\u001b[39m. \u001b[33mfor\u001b[39m / \u001b[33mwhile\u001b[39m / \u001b[33mfor...of\u001b[39m. Curly braces are required for blocks; semicolons end statements. \u001b[33m===\u001b[39m is strict equality (no type coercion); use it. \u001b[33m==\u001b[39m coerces and produces surprises.\r\n\r\n      \u001b[33mfor\u001b[39m (\u001b[33mconst\u001b[39m item \u001b[33mof\u001b[39m cars) {\r\n          console.log(item)\r\n      }\r\n\r\n\u001b[1m\u001b[33mFUNCTIONS\u001b[39m\u001b[22m\r\n\r\n  Two declaration styles. \u001b[33mfunction\u001b[39m for hoisted top-level definitions. Arrow functions for callbacks and anywhere lexical \u001b[1mthis\u001b[22m matters.\r\n\r\n      \u001b[33mfunction\u001b[39m \u001b[36mtotal_with_tax\u001b[39m(amount, rate=\u001b[34m0.08\u001b[39m) {\r\n          \u001b[33mreturn\u001b[39m amount * (\u001b[34m1\u001b[39m + rate)\r\n      }\r\n      \u001b[33mconst\u001b[39m double = x => x * \u001b[34m2\u001b[39m\r\n\r\n  Default parameters go after \u001b[33m=\u001b[39m in the signature. Arrow functions inherit \u001b[1mthis\u001b[22m from their enclosing scope; regular functions don't.\r\n\r\n\u001b[1m\u001b[33mARRAY METHODS\u001b[39m\u001b[22m\r\n\r\n  \u001b[1m.map\u001b[22m, \u001b[1m.filter\u001b[22m, \u001b[1m.reduce\u001b[22m are the workhorses. They return new arrays (or values) without mutating the original. Chain them.\r\n\r\n      \u001b[33mconst\u001b[39m open_costs = orders\r\n          .\u001b[35mfilter\u001b[39m(o => o.status === \u001b[32m'Open'\u001b[39m)\r\n          .\u001b[35mmap\u001b[39m(o => o.cost)\r\n\r\n  \u001b[90mFilter narrows; map transforms. See \u001b[34m\u001b[4mjs_am_09\u001b[24m\u001b[39m.\u001b[39m\r\n\r\n\u001b[1m\u001b[33mDESTRUCTURING\u001b[39m\u001b[22m\r\n\r\n  Pull values out of arrays and objects with one statement.\r\n\r\n      \u001b[33mconst\u001b[39m [x, y] = [\u001b[34m3\u001b[39m, \u001b[34m4\u001b[39m]                    \u001b[90marray form\u001b[39m\r\n      \u001b[33mconst\u001b[39m { name, phone } = customer    \u001b[90mobject form\u001b[39m\r\n\r\n  Rename with \u001b[1m{ name: customer_name }\u001b[22m. Set defaults with \u001b[1m{ name = 'unknown' }\u001b[22m. Combines with function parameters.\r\n\r\n\u001b[1m\u001b[33mTEMPLATE LITERALS\u001b[39m\u001b[22m\r\n\r\n  Backticks (not quotes) for interpolation. Multi-line strings work.\r\n\r\n      \u001b[32m`Welcome to ${shop_name}, you have ${count} jobs open.`\u001b[39m\r\n\r\n\u001b[1m\u001b[33mCLASSES\u001b[39m\u001b[22m\r\n\r\n  \u001b[33mclass\u001b[39m declares a type. \u001b[1mconstructor\u001b[22m runs at construction. \u001b[1mthis\u001b[22m is the instance. \u001b[33mextends\u001b[39m for inheritance; \u001b[33msuper\u001b[39m calls the parent.\r\n\r\n      \u001b[33mclass\u001b[39m \u001b[36mWorkOrder\u001b[39m {\r\n          \u001b[36mconstructor\u001b[39m(id, cost, status) {\r\n              this.id = id\r\n              this.cost = cost\r\n              this.status = status\r\n          }\r\n          \u001b[36mis_open\u001b[39m() { \u001b[33mreturn\u001b[39m this.status === \u001b[32m'Open'\u001b[39m }\r\n      }\r\n\r\n  \u001b[35mget\u001b[39m and \u001b[35mset\u001b[39m declare property accessors that look like attributes from the outside. Useful for derived properties.\r\n\r\n\u001b[1m\u001b[33mASYNC\u001b[39m\u001b[22m\r\n\r\n  \u001b[33mPromise\u001b[39m represents a future value. \u001b[33masync\u001b[39m declares a function that returns a Promise. \u001b[33mawait\u001b[39m unwraps one inside an async function. \u001b[33mPromise.all\u001b[39m runs Promises in parallel.\r\n\r\n      \u001b[33mconst\u001b[39m [x, y] = \u001b[33mawait\u001b[39m Promise.\u001b[35mall\u001b[39m([fetch_a(), fetch_b()])\r\n\r\n  Wrap \u001b[33mawait\u001b[39m in \u001b[33mtry\u001b[39m/\u001b[33mcatch\u001b[39m for rejection handling \u2014 a rejected Promise inside \u001b[33mawait\u001b[39m throws synchronously.\r\n\r\n\u001b[1m\u001b[33mJSON\u001b[39m\u001b[22m\r\n\r\n  \u001b[33mJSON.parse\u001b[39m(str) converts a JSON string to a value. \u001b[33mJSON.stringify\u001b[39m(v) converts back. The two roundtrip cleanly for plain data; functions and undefined values are dropped.\r\n\r\n\u001b[1m\u001b[33mGENERATORS AND ITERATION\u001b[39m\u001b[22m\r\n\r\n  \u001b[33mfunction*\u001b[39m declares a generator. \u001b[33myield\u001b[39m produces a value and pauses. Lazy by default \u2014 only computes what's consumed.\r\n\r\n      \u001b[33mfunction*\u001b[39m \u001b[36mrange_gen\u001b[39m(s, e) {\r\n          \u001b[33mfor\u001b[39m (\u001b[33mlet\u001b[39m i = s; i < e; i++) \u001b[33myield\u001b[39m i\r\n      }\r\n\r\n  \u001b[1m[...gen()]\u001b[22m or \u001b[1mArray.from(gen())\u001b[22m materializes the sequence.\r\n\r\n\u001b[1m\u001b[33mMODERN PATTERNS\u001b[39m\u001b[22m\r\n\r\n  Spread \u001b[1m...arr\u001b[22m unpacks arrays; rest \u001b[1m...args\u001b[22m gathers them. \u001b[33mMap\u001b[39m and \u001b[33mSet\u001b[39m are real collections beyond plain objects. \u001b[33mObject.entries\u001b[39m / \u001b[33mObject.values\u001b[39m iterate object data. \u001b[33mOptional chaining\u001b[39m \u001b[1mobj?.x?.y\u001b[22m safely reads through nulls.\r\n\r\n\u001b[1m\u001b[33mTAG REFERENCE\u001b[39m\u001b[22m\r\n\r\n  \u001b[33mamber\u001b[39m keywords. \u001b[36mteal\u001b[39m callables/types. \u001b[32mgreen\u001b[39m strings. \u001b[34mblue\u001b[39m numerics. \u001b[35mpurple\u001b[39m methods/decorators. \u001b[31mred\u001b[39m warnings. \u001b[90mdim\u001b[39m asides. \u001b[1mbold\u001b[22m emphasis.\r\n","html":"<div class=\"cs-section\"><h4 class=\"cs-h\">JAVASCRIPT CHEATSHEET</h4><p class=\"cs-prose\"><span class=\"cs-dim\">A working reference for the whole language. Skim it once, come back when stuck.</span></p></div><div class=\"cs-section\"><h4 class=\"cs-h\">VARIABLES AND TYPES</h4><p class=\"cs-prose\">Three declaration keywords. <span class=\"cs-amber\">const</span> for values that won't be reassigned, <span class=\"cs-amber\">let</span> for ones that will, <span class=\"cs-amber\">var</span> for legacy code you're maintaining.</p><pre class=\"cs-code\"><code>  <span class=\"cs-amber\">const</span> garage = <span class=\"cs-green\">'Terminal Auto'</span>\n  <span class=\"cs-amber\">let</span> count = <span class=\"cs-blue\">42</span>\n  <span class=\"cs-amber\">const</span> active = <span class=\"cs-amber\">true</span></code></pre><p class=\"cs-prose\"><span class=\"cs-red\">Booleans are lowercase</span>: <span class=\"cs-amber\">true</span> / <span class=\"cs-amber\">false</span>, not True/False. <span class=\"cs-amber\">null</span> is &quot;no value&quot;; <span class=\"cs-amber\">undefined</span> is &quot;not yet set.&quot; They're different types and the distinction matters.</p></div><div class=\"cs-section\"><h4 class=\"cs-h\">COLLECTIONS</h4><p class=\"cs-prose\">Arrays are ordered, mutable, zero-indexed. Objects are key-value maps.</p><pre class=\"cs-code\"><code>  <span class=\"cs-amber\">const</span> cars = [<span class=\"cs-green\">'Skyline'</span>, <span class=\"cs-green\">'Supra'</span>]\n  <span class=\"cs-amber\">const</span> car = { make: <span class=\"cs-green\">'Nissan'</span>, year: <span class=\"cs-blue\">1996</span> }</code></pre><p class=\"cs-prose\"><span class=\"cs-bold\">arr[i]</span> indexes. <span class=\"cs-bold\">arr.length</span> is the count \u2014 a property, <span class=\"cs-red\">no parentheses</span>. <span class=\"cs-bold\">obj.key</span> reads dot notation. <span class=\"cs-bold\">obj[k]</span> reads via a computed key. <span class=\"cs-dim\">See <a class=\"cs-qid\" data-qid=\"js_intro_07\">js_intro_07</a>.</span></p></div><div class=\"cs-section\"><h4 class=\"cs-h\">CONTROL FLOW</h4><p class=\"cs-prose\"><span class=\"cs-amber\">if</span> / <span class=\"cs-amber\">else if</span> / <span class=\"cs-amber\">else</span>. <span class=\"cs-amber\">for</span> / <span class=\"cs-amber\">while</span> / <span class=\"cs-amber\">for...of</span>. Curly braces are required for blocks; semicolons end statements. <span class=\"cs-amber\">===</span> is strict equality (no type coercion); use it. <span class=\"cs-amber\">==</span> coerces and produces surprises.</p><pre class=\"cs-code\"><code>  <span class=\"cs-amber\">for</span> (<span class=\"cs-amber\">const</span> item <span class=\"cs-amber\">of</span> cars) {\n      console.log(item)\n  }</code></pre></div><div class=\"cs-section\"><h4 class=\"cs-h\">FUNCTIONS</h4><p class=\"cs-prose\">Two declaration styles. <span class=\"cs-amber\">function</span> for hoisted top-level definitions. Arrow functions for callbacks and anywhere lexical <span class=\"cs-bold\">this</span> matters.</p><pre class=\"cs-code\"><code>  <span class=\"cs-amber\">function</span> <span class=\"cs-teal\">total_with_tax</span>(amount, rate=<span class=\"cs-blue\">0.08</span>) {\n      <span class=\"cs-amber\">return</span> amount * (<span class=\"cs-blue\">1</span> + rate)\n  }\n  <span class=\"cs-amber\">const</span> double = x =&gt; x * <span class=\"cs-blue\">2</span></code></pre><p class=\"cs-prose\">Default parameters go after <span class=\"cs-amber\">=</span> in the signature. Arrow functions inherit <span class=\"cs-bold\">this</span> from their enclosing scope; regular functions don't.</p></div><div class=\"cs-section\"><h4 class=\"cs-h\">ARRAY METHODS</h4><p class=\"cs-prose\"><span class=\"cs-bold\">.map</span>, <span class=\"cs-bold\">.filter</span>, <span class=\"cs-bold\">.reduce</span> are the workhorses. They return new arrays (or values) without mutating the original. Chain them.</p><pre class=\"cs-code\"><code>  <span class=\"cs-amber\">const</span> open_costs = orders\n      .<span class=\"cs-purple\">filter</span>(o =&gt; o.status === <span class=\"cs-green\">'Open'</span>)\n      .<span class=\"cs-purple\">map</span>(o =&gt; o.cost)</code></pre><p class=\"cs-prose\"><span class=\"cs-dim\">Filter narrows; map transforms. See <a class=\"cs-qid\" data-qid=\"js_am_09\">js_am_09</a>.</span></p></div><div class=\"cs-section\"><h4 class=\"cs-h\">DESTRUCTURING</h4><p class=\"cs-prose\">Pull values out of arrays and objects with one statement.</p><pre class=\"cs-code\"><code>  <span class=\"cs-amber\">const</span> [x, y] = [<span class=\"cs-blue\">3</span>, <span class=\"cs-blue\">4</span>]                    <span class=\"cs-dim\">array form</span>\n  <span class=\"cs-amber\">const</span> { name, phone } = customer    <span class=\"cs-dim\">object form</span></code></pre><p class=\"cs-prose\">Rename with <span class=\"cs-bold\">{ name: customer_name }</span>. Set defaults with <span class=\"cs-bold\">{ name = 'unknown' }</span>. Combines with function parameters.</p></div><div class=\"cs-section\"><h4 class=\"cs-h\">TEMPLATE LITERALS</h4><p class=\"cs-prose\">Backticks (not quotes) for interpolation. Multi-line strings work.</p><pre class=\"cs-code\"><code>  <span class=\"cs-green\">`Welcome to ${shop_name}, you have ${count} jobs open.`</span></code></pre></div><div class=\"cs-section\"><h4 class=\"cs-h\">CLASSES</h4><p class=\"cs-prose\"><span class=\"cs-amber\">class</span> declares a type. <span class=\"cs-bold\">constructor</span> runs at construction. <span class=\"cs-bold\">this</span> is the instance. <span class=\"cs-amber\">extends</span> for inheritance; <span class=\"cs-amber\">super</span> calls the parent.</p><pre class=\"cs-code\"><code>  <span class=\"cs-amber\">class</span> <span class=\"cs-teal\">WorkOrder</span> {\n      <span class=\"cs-teal\">constructor</span>(id, cost, status) {\n          this.id = id\n          this.cost = cost\n          this.status = status\n      }\n      <span class=\"cs-teal\">is_open</span>() { <span class=\"cs-amber\">return</span> this.status === <span class=\"cs-green\">'Open'</span> }\n  }</code></pre><p class=\"cs-prose\"><span class=\"cs-purple\">get</span> and <span class=\"cs-purple\">set</span> declare property accessors that look like attributes from the outside. Useful for derived properties.</p></div><div class=\"cs-section\"><h4 class=\"cs-h\">ASYNC</h4><p class=\"cs-prose\"><span class=\"cs-amber\">Promise</span> represents a future value. <span class=\"cs-amber\">async</span> declares a function that returns a Promise. <span class=\"cs-amber\">await</span> unwraps one inside an async function. <span class=\"cs-amber\">Promise.all</span> runs Promises in parallel.</p><pre class=\"cs-code\"><code>  <span class=\"cs-amber\">const</span> [x, y] = <span class=\"cs-amber\">await</span> Promise.<span class=\"cs-purple\">all</span>([fetch_a(), fetch_b()])</code></pre><p class=\"cs-prose\">Wrap <span class=\"cs-amber\">await</span> in <span class=\"cs-amber\">try</span>/<span class=\"cs-amber\">catch</span> for rejection handling \u2014 a rejected Promise inside <span class=\"cs-amber\">await</span> throws synchronously.</p></div><div class=\"cs-section\"><h4 class=\"cs-h\">JSON</h4><p class=\"cs-prose\"><span class=\"cs-amber\">JSON.parse</span>(str) converts a JSON string to a value. <span class=\"cs-amber\">JSON.stringify</span>(v) converts back. The two roundtrip cleanly for plain data; functions and undefined values are dropped.</p></div><div class=\"cs-section\"><h4 class=\"cs-h\">GENERATORS AND ITERATION</h4><p class=\"cs-prose\"><span class=\"cs-amber\">function*</span> declares a generator. <span class=\"cs-amber\">yield</span> produces a value and pauses. Lazy by default \u2014 only computes what's consumed.</p><pre class=\"cs-code\"><code>  <span class=\"cs-amber\">function*</span> <span class=\"cs-teal\">range_gen</span>(s, e) {\n      <span class=\"cs-amber\">for</span> (<span class=\"cs-amber\">let</span> i = s; i &lt; e; i++) <span class=\"cs-amber\">yield</span> i\n  }</code></pre><p class=\"cs-prose\"><span class=\"cs-bold\">[...gen()]</span> or <span class=\"cs-bold\">Array.from(gen())</span> materializes the sequence.</p></div><div class=\"cs-section\"><h4 class=\"cs-h\">MODERN PATTERNS</h4><p class=\"cs-prose\">Spread <span class=\"cs-bold\">...arr</span> unpacks arrays; rest <span class=\"cs-bold\">...args</span> gathers them. <span class=\"cs-amber\">Map</span> and <span class=\"cs-amber\">Set</span> are real collections beyond plain objects. <span class=\"cs-amber\">Object.entries</span> / <span class=\"cs-amber\">Object.values</span> iterate object data. <span class=\"cs-amber\">Optional chaining</span> <span class=\"cs-bold\">obj?.x?.y</span> safely reads through nulls.</p></div><div class=\"cs-section\"><h4 class=\"cs-h\">TAG REFERENCE</h4><p class=\"cs-prose\"><span class=\"cs-amber\">amber</span> keywords. <span class=\"cs-teal\">teal</span> callables/types. <span class=\"cs-green\">green</span> strings. <span class=\"cs-blue\">blue</span> numerics. <span class=\"cs-purple\">purple</span> methods/decorators. <span class=\"cs-red\">red</span> warnings. <span class=\"cs-dim\">dim</span> asides. <span class=\"cs-bold\">bold</span> emphasis.</p></div>"},"tiers":{"1":"\u001b[1m\u001b[33mJAVASCRIPT \u00b7 TIER 1 CONCEPTS (INTRODUCTORY)\u001b[39m\u001b[22m\r\n\r\n  \u001b[90mRead this once. The first ten questions cover binding values, simple collections, and getting them back out.\u001b[39m\r\n\r\n  JavaScript is a dynamically-typed language that runs in browsers, on servers (Node.js), and almost everywhere else. At this tier the goal is to bind values to names, build small collections, and read from them.\r\n\r\n\u001b[1m\u001b[33mBINDING NAMES\u001b[39m\u001b[22m\r\n\r\n  Three keywords for declaring variables. \u001b[33mconst\u001b[39m is the default \u2014 use it whenever the binding won't be reassigned. \u001b[33mlet\u001b[39m when you need reassignment. \u001b[33mvar\u001b[39m is legacy; you'll see it in older code but new code uses const/let.\r\n\r\n      \u001b[33mconst\u001b[39m garage_name = \u001b[32m'Terminal Auto'\u001b[39m\r\n      \u001b[33mlet\u001b[39m open_jobs = \u001b[34m7\u001b[39m\r\n      \u001b[33mconst\u001b[39m is_open = \u001b[33mtrue\u001b[39m\r\n\r\n  Single or double quotes both make strings. Pick one and stay consistent. \u001b[31mBooleans are lowercase\u001b[39m true/false \u2014 capitalized True/False is a Python habit that throws a ReferenceError in JS.\r\n\r\n\u001b[1m\u001b[33mCOLLECTIONS\u001b[39m\u001b[22m\r\n\r\n  Arrays are ordered, mutable lists. Objects are key-value maps. These cover most data shapes at this tier.\r\n\r\n      \u001b[33mconst\u001b[39m mechanics = [\u001b[32m'Kris'\u001b[39m, \u001b[32m'Alex'\u001b[39m, \u001b[32m'Sam'\u001b[39m]\r\n      \u001b[33mconst\u001b[39m customer = { id: \u001b[34m1\u001b[39m, name: \u001b[32m'Alice'\u001b[39m }\r\n\r\n  \u001b[1marr[i]\u001b[22m indexes into an array (zero-based). \u001b[1marr.length\u001b[22m gives the count \u2014 \u001b[31mproperty, not function, no parentheses\u001b[39m. \u001b[1mobj.key\u001b[22m reads dot-notation; \u001b[1mobj[\"key\"]\u001b[22m is the bracket form for keys with spaces or computed names.\r\n\r\n      mechanics[\u001b[34m0\u001b[39m]      \u001b[90m'Kris'\u001b[39m\r\n      mechanics.length    \u001b[90m3\u001b[39m\r\n      customer.name       \u001b[90m'Alice'\u001b[39m\r\n\r\n\u001b[1m\u001b[33mOUTPUT\u001b[39m\u001b[22m\r\n\r\n  \u001b[33mconsole.log\u001b[39m(x) writes x to stdout followed by a newline. With multiple arguments it joins them with a space. This is JavaScript's print().\r\n\r\n      console.log(\u001b[32m'Shop open'\u001b[39m)\r\n\r\n\u001b[1m\u001b[33mTEMPLATE LITERALS\u001b[39m\u001b[22m\r\n\r\n  Backticks (not quotes) let you interpolate expressions inside a string with \u001b[1m${...}\u001b[22m. Cleaner than concatenation with \u001b[1m+\u001b[22m.\r\n\r\n      \u001b[33mconst\u001b[39m greeting = \u001b[32m`Welcome to ${shop_name}`\u001b[39m\r\n\r\n  \u001b[90mThe backtick is the single subtle syntax point at this tier. The string is otherwise identical to a normal one.\u001b[39m\r\n\r\n  NEXT TIER: array methods (map/filter/reduce), destructuring, default arguments, and the start of light ML framing \u2014 one-hot encoding, threshold filtering. The shift is from \"store data\" to \"transform data.\"\r\n","2":"\u001b[1m\u001b[33mJAVASCRIPT \u00b7 TIER 2 CONCEPTS (AMATEUR)\u001b[39m\u001b[22m\r\n\r\n  \u001b[90mArray methods, destructuring, and the first taste of ML framing. The shift this tier: from \"loop and append\" to \"describe the result.\"\u001b[39m\r\n\r\n  At this tier the JS code starts to look like real-world JS. You stop writing for-loops with manual counters and start chaining array methods that read like English: filter these, then map those.\r\n\r\n\u001b[1m\u001b[33mARRAY METHODS: MAP, FILTER, REDUCE\u001b[39m\u001b[22m\r\n\r\n  Three methods cover most data transformations. They don't mutate the original array; they return a new value.\r\n\r\n      \u001b[33mconst\u001b[39m doubled = scores.\u001b[35mmap\u001b[39m(x => x * \u001b[34m2\u001b[39m)\r\n      \u001b[33mconst\u001b[39m high    = probs.\u001b[35mfilter\u001b[39m(p => p > \u001b[34m0.5\u001b[39m)\r\n      \u001b[33mconst\u001b[39m total   = counts.\u001b[35mreduce\u001b[39m((acc, v) => acc + v, \u001b[34m0\u001b[39m)\r\n\r\n  \u001b[1m.map\u001b[22m transforms each element. \u001b[1m.filter\u001b[22m keeps elements where the predicate returns true. \u001b[1m.reduce\u001b[22m folds the array down to a single value using a binary function and an initial accumulator.\r\n\r\n  \u001b[90mReduce's initial accumulator (the second argument) is critical \u2014 forgetting it makes the first array element the seed, which silently changes the answer for the empty-array case.\u001b[39m\r\n\r\n\u001b[1m\u001b[33mCHAINING\u001b[39m\u001b[22m\r\n\r\n  Array methods return arrays, so you can chain them. Filter narrows; map transforms. Together they replace most for-loops with branching logic.\r\n\r\n      \u001b[33mconst\u001b[39m open_costs = orders\r\n          .\u001b[35mfilter\u001b[39m(o => o.status === \u001b[32m'Open'\u001b[39m)\r\n          .\u001b[35mmap\u001b[39m(o => o.cost)\r\n\r\n  \u001b[90mEquivalent for-loop is six lines. The chained version is one expression and reads top-down. See \u001b[34m\u001b[4mjs_am_09\u001b[24m\u001b[39m.\u001b[39m\r\n\r\n\u001b[1m\u001b[33mDESTRUCTURING\u001b[39m\u001b[22m\r\n\r\n  Pull values out of arrays and objects with one statement.\r\n\r\n      \u001b[33mconst\u001b[39m [x, y] = point                  \u001b[90marray form\u001b[39m\r\n      \u001b[33mconst\u001b[39m { name, phone } = customer      \u001b[90mobject form\u001b[39m\r\n\r\n  Object destructuring matches by key name. Rename with \u001b[1m{ name: customer_name }\u001b[22m. Set defaults with \u001b[1m{ name = 'unknown' }\u001b[22m. This pattern shows up in function parameters constantly.\r\n\r\n\u001b[1m\u001b[33mDEFAULT ARGUMENTS\u001b[39m\u001b[22m\r\n\r\n  Function parameters can have default values. Used when the caller omits the argument.\r\n\r\n      \u001b[33mfunction\u001b[39m \u001b[36mtotal_with_tax\u001b[39m(amount, rate=\u001b[34m0.08\u001b[39m) {\r\n          \u001b[33mreturn\u001b[39m amount * (\u001b[34m1\u001b[39m + rate)\r\n      }\r\n\r\n  Defaults are evaluated each call, not once at definition time \u2014 different from Python's gotcha. Mutable defaults are safe in JS.\r\n\r\n\u001b[1m\u001b[33mSPREAD OPERATOR\u001b[39m\u001b[22m\r\n\r\n  \u001b[1m...arr\u001b[22m unpacks an array's elements into a context. Combine arrays: \u001b[1m[...a, ...b]\u001b[22m. Pass elements as separate arguments: \u001b[1mMath.max(...nums)\u001b[22m.\r\n\r\n      \u001b[33mconst\u001b[39m all = [...primary, ...backup]\r\n\r\n\u001b[1m\u001b[33mLIGHT ML FRAMING\u001b[39m\u001b[22m\r\n\r\n  At this tier you'll meet your first ML primitives, framed as JS tasks. \u001b[1mOne-hot encoding\u001b[22m turns a class index into a vector with 1 at that index and 0 elsewhere \u2014 used to feed categorical data into models. \u001b[1mArgmax\u001b[22m returns the index of the largest value \u2014 used to pick the predicted class from a vector of model scores.\r\n\r\n  \u001b[90mNo ML knowledge required to solve them. Both are pure array manipulation; the ML names are just the labels the field uses for these shapes.\u001b[39m\r\n\r\n  NEXT TIER: arrow functions in earnest, closures, async/await, JSON, and the first explicit-ML primitives \u2014 softmax and cosine similarity. Arrays give way to working with promises and shared state.\r\n","3":"\u001b[1m\u001b[33mJAVASCRIPT \u00b7 TIER 3 CONCEPTS (INTERMEDIATE)\u001b[39m\u001b[22m\r\n\r\n  \u001b[90mClosures, asynchronous code, and the first explicit-ML primitives. Each idea is small individually; together they're how real JS gets written.\u001b[39m\r\n\r\n\u001b[1m\u001b[33mARROW FUNCTIONS AND CLOSURES\u001b[39m\u001b[22m\r\n\r\n  Arrow functions are JS's anonymous-function syntax, optimized for use as callbacks. The classic non-trivial use is closing over an enclosing scope's variable.\r\n\r\n      \u001b[33mfunction\u001b[39m \u001b[36mmake_counter\u001b[39m() {\r\n          \u001b[33mlet\u001b[39m n = \u001b[34m0\u001b[39m\r\n          \u001b[33mreturn\u001b[39m () => ++n\r\n      }\r\n\r\n      \u001b[33mconst\u001b[39m a = \u001b[36mmake_counter\u001b[39m()\r\n      a()    \u001b[90m1\u001b[39m\r\n      a()    \u001b[90m2\u001b[39m\r\n\r\n  Each call to make_counter creates a fresh n in a fresh scope. The returned arrow function keeps a private reference to that n. This is how state lives inside functional-looking code.\r\n\r\n  \u001b[90mClosures are the prerequisite for understanding why generators work (Master tier), why React's useState returns what it does, and why decorators wrap state \u2014 they're the most leveraged single concept in modern JS. See \u001b[39m\u001b[34m\u001b[4mjs_int_02\u001b[24m\u001b[39m\u001b[90m.\u001b[39m\r\n\r\n\u001b[1m\u001b[33mASYNC/AWAIT\u001b[39m\u001b[22m\r\n\r\n  A \u001b[33mPromise\u001b[39m represents a future value. \u001b[33masync\u001b[39m declares a function that returns a Promise. \u001b[33mawait\u001b[39m unwraps one inside an async function \u2014 the function pauses, the resolved value is returned.\r\n\r\n      \u001b[33mconst\u001b[39m result = \u001b[33mawait\u001b[39m fake_fetch()\r\n\r\n  \u001b[1mPromise.all([p1, p2, p3])\u001b[22m runs Promises in parallel and resolves to an array of values. Use it whenever the next step doesn't depend on any specific Promise's result.\r\n\r\n      \u001b[33mconst\u001b[39m [a, b, c] = \u001b[33mawait\u001b[39m Promise.\u001b[35mall\u001b[39m([fa(), fb(), fc()])\r\n\r\n  Awaiting a sequence one-by-one is N times slower than Promise.all when the calls are independent.\r\n\r\n\u001b[1m\u001b[33mERROR HANDLING\u001b[39m\u001b[22m\r\n\r\n  \u001b[33mtry\u001b[39m / \u001b[33mcatch\u001b[39m catches synchronous throws AND awaited Promise rejections. This is the single biggest reason async code goes wrong: a Promise that rejects without try/catch surfaces as an unhandled-rejection warning, not a normal stack trace.\r\n\r\n      \u001b[33mtry\u001b[39m {\r\n          \u001b[33mconst\u001b[39m data = \u001b[33mawait\u001b[39m fetch_user(id)\r\n      } \u001b[33mcatch\u001b[39m (e) {\r\n          console.error(\u001b[32m'failed:'\u001b[39m, e.message)\r\n      }\r\n\r\n  Inside async/await, treat every external call as if it could reject.\r\n\r\n\u001b[1m\u001b[33mJSON\u001b[39m\u001b[22m\r\n\r\n  \u001b[33mJSON.parse\u001b[39m(str) converts a JSON string to a value. \u001b[33mJSON.stringify\u001b[39m(v) converts back. The two roundtrip cleanly for plain data \u2014 strings, numbers, booleans, null, arrays, objects.\r\n\r\n      \u001b[33mconst\u001b[39m obj = JSON.\u001b[35mparse\u001b[39m(raw)\r\n      obj.count += \u001b[34m1\u001b[39m\r\n      \u001b[33mconst\u001b[39m out = JSON.\u001b[35mstringify\u001b[39m(obj)\r\n\r\n  \u001b[90mParsing fails on malformed input by throwing \u2014 wrap in try/catch if input might be invalid. See \u001b[34m\u001b[4mjs_int_09\u001b[24m\u001b[39m.\u001b[39m\r\n\r\n\u001b[1m\u001b[33mOBJECT ITERATION\u001b[39m\u001b[22m\r\n\r\n  \u001b[33mObject.values\u001b[39m(obj) gives you the array of values. \u001b[33mObject.keys\u001b[39m(obj) gives the keys. \u001b[33mObject.entries\u001b[39m(obj) gives [key, value] pairs.\r\n\r\n      \u001b[33mconst\u001b[39m total = \u001b[33mObject\u001b[39m.values(status_counts).\u001b[35mreduce\u001b[39m((a,b)=>a+b, \u001b[34m0\u001b[39m)\r\n\r\n\u001b[1m\u001b[33mEXPLICIT-ML PRIMITIVES\u001b[39m\u001b[22m\r\n\r\n  This tier introduces the first ML algorithms you'll implement directly:\r\n\r\n  \u001b[1mSoftmax\u001b[22m turns a vector of arbitrary scores into a probability distribution. Each output is exp(x_i) / sum_of_all_exp_values. Outputs are positive and sum to 1.\r\n\r\n  \u001b[1mCosine similarity\u001b[22m measures the angle between two vectors, ignoring their magnitudes. dot(a,b) / (|a| \u00b7 |b|). Identical direction gives 1, orthogonal gives 0.\r\n\r\n  \u001b[1mDot product\u001b[22m is the sum of element-wise products. Building block for cosine similarity, matrix multiply, and any vector-vector computation in ML.\r\n\r\n  \u001b[1mEuclidean distance\u001b[22m is sqrt(sum of squared differences). The geometric distance between two vectors.\r\n\r\n  \u001b[90mAll four are array iterations with one or two accumulators. The algebraic content is light; the JS idioms are the actual lesson.\u001b[39m\r\n\r\n  NEXT TIER: classes, inheritance, getters and setters, fetch idioms, promise chaining, and ML primitives heavier in flavor \u2014 vector arithmetic, mean pooling, cross-entropy loss, a tiny feedforward pass.\r\n","4":"\u001b[1m\u001b[33mJAVASCRIPT \u00b7 TIER 4 CONCEPTS (EXPERIENCED)\u001b[39m\u001b[22m\r\n\r\n  \u001b[90mClasses plus the ML primitives that combine the array tools from earlier tiers into real model components. Where Intermediate teaches the pieces, Experienced teaches the assembly.\u001b[39m\r\n\r\n\u001b[1m\u001b[33mCLASSES\u001b[39m\u001b[22m\r\n\r\n  A class defines a type. The constructor runs at instantiation. \u001b[1mthis\u001b[22m is the current instance, passed implicitly when you call a method on an object.\r\n\r\n      \u001b[33mclass\u001b[39m \u001b[36mWorkOrder\u001b[39m {\r\n          \u001b[36mconstructor\u001b[39m(id, cost, status) {\r\n              this.id = id\r\n              this.cost = cost\r\n              this.status = status\r\n          }\r\n          \u001b[36mis_open\u001b[39m() {\r\n              \u001b[33mreturn\u001b[39m this.status === \u001b[32m'Open'\u001b[39m\r\n          }\r\n      }\r\n\r\n  Construct with \u001b[1mnew WorkOrder(1, 100, 'Open')\u001b[22m. Methods are declared without \u001b[33mfunction\u001b[39m inside the class body.\r\n\r\n\u001b[1m\u001b[33mINHERITANCE\u001b[39m\u001b[22m\r\n\r\n  \u001b[33mclass\u001b[39m Child extends Parent inherits Parent's methods. Use \u001b[33msuper\u001b[39m in the constructor to pass arguments up. \u001b[33msuper.method()\u001b[39m inside an overridden method calls the parent's version.\r\n\r\n      \u001b[33mclass\u001b[39m \u001b[36mSportsCar\u001b[39m \u001b[33mextends\u001b[39m \u001b[36mVehicle\u001b[39m {\r\n          \u001b[36mconstructor\u001b[39m(make, year, topSpeed) {\r\n              \u001b[33msuper\u001b[39m(make, year)\r\n              this.topSpeed = topSpeed\r\n          }\r\n          \u001b[36mis_fast\u001b[39m() { \u001b[33mreturn\u001b[39m this.topSpeed > \u001b[34m150\u001b[39m }\r\n      }\r\n\r\n  \u001b[90mInheritance is one of three ways to share behavior. Composition (objects that contain other objects) and duck-typing (any object with the right shape works) are the others. Use inheritance when the relationship is genuinely \"is-a.\"\u001b[39m\r\n\r\n\u001b[1m\u001b[33mGETTERS AND SETTERS\u001b[39m\u001b[22m\r\n\r\n  \u001b[35mget\u001b[39m and \u001b[35mset\u001b[39m inside a class declare property accessors. Callers read and write \u001b[1mobj.name\u001b[22m without parens; the class controls what happens.\r\n\r\n      \u001b[33mclass\u001b[39m \u001b[36mTemperature\u001b[39m {\r\n          \u001b[36mconstructor\u001b[39m(c) { this.celsius = c }\r\n          \u001b[35mget\u001b[39m \u001b[36mfahrenheit\u001b[39m() { \u001b[33mreturn\u001b[39m this.celsius * \u001b[34m9\u001b[39m/\u001b[34m5\u001b[39m + \u001b[34m32\u001b[39m }\r\n          \u001b[35mset\u001b[39m \u001b[36mfahrenheit\u001b[39m(v) { this.celsius = (v - \u001b[34m32\u001b[39m) * \u001b[34m5\u001b[39m/\u001b[34m9\u001b[39m }\r\n      }\r\n\r\n  Useful for derived properties (computed from internals), validation on write, or backwards compatibility when refactoring a stored value into a computed one.\r\n\r\n\u001b[1m\u001b[33mPROMISE CHAINING\u001b[39m\u001b[22m\r\n\r\n  Before async/await there was \u001b[1m.then()\u001b[22m. Both forms exist; await is sugar over then for sequential code, but raw chaining is still useful when transforming a Promise into another Promise without awaiting.\r\n\r\n      \u001b[33mconst\u001b[39m scaled = fetch_score().\u001b[35mthen\u001b[39m(x => x * \u001b[34m2\u001b[39m).\u001b[35mthen\u001b[39m(x => x + \u001b[34m1\u001b[39m)\r\n      \u001b[33mconst\u001b[39m final = \u001b[33mawait\u001b[39m scaled\r\n\r\n  Each \u001b[1m.then\u001b[22m returns a new Promise resolving to the callback's return value. Chaining is how you transform a value pipeline-style.\r\n\r\n\u001b[1m\u001b[33mFETCH IDIOMS\u001b[39m\u001b[22m\r\n\r\n  Real fetch calls do two awaits: one for the response object, one for the body. Forgetting the second is the most-common production fetch bug.\r\n\r\n      \u001b[33mconst\u001b[39m resp = \u001b[33mawait\u001b[39m fetch(url)\r\n      \u001b[33mconst\u001b[39m data = \u001b[33mawait\u001b[39m resp.json()\r\n\r\n  Wrap with try/catch to handle network errors and JSON parse errors separately. Check \u001b[1mresp.ok\u001b[22m for HTTP status before calling \u001b[1m.json()\u001b[22m \u2014 fetch only rejects on network failures, not on 404 or 500.\r\n\r\n\u001b[1m\u001b[33mML PRIMITIVES \u2014 VECTOR ARITHMETIC\u001b[39m\u001b[22m\r\n\r\n  At this tier the ML content gets denser. You're building model components.\r\n\r\n  \u001b[1mVector add\u001b[22m is element-wise sum, returning a new array. Building block for residual connections and bias addition.\r\n\r\n      \u001b[33mfunction\u001b[39m \u001b[36mvec_add\u001b[39m(a, b) { \u001b[33mreturn\u001b[39m a.\u001b[35mmap\u001b[39m((x, i) => x + b[i]) }\r\n\r\n  \u001b[1mVector mean\u001b[22m is sum / length. The base operation behind mean pooling, where multiple embeddings get averaged into one representation.\r\n\r\n  \u001b[1mStable softmax\u001b[22m is the version of softmax you actually use in practice. Subtract max(xs) before exponentiating \u2014 same answer, doesn't overflow.\r\n\r\n      \u001b[33mconst\u001b[39m shift = \u001b[33mMath\u001b[39m.max(...xs)\r\n      \u001b[33mconst\u001b[39m exps = xs.\u001b[35mmap\u001b[39m(x => \u001b[33mMath\u001b[39m.exp(x - shift))\r\n\r\n\u001b[1m\u001b[33mA TINY FEEDFORWARD PASS\u001b[39m\u001b[22m\r\n\r\n  Linear layer + ReLU is the fundamental building block of neural networks. Given an input vector x, a weight matrix W, and a bias vector b:\r\n\r\n      output[i] = max(0, dot(W[i], x) + b[i])\r\n\r\n  That's a layer. Stacking two of these with a softmax at the end is a one-hidden-layer classifier. Real models do the same operation, just with bigger matrices and more layers.\r\n\r\n  \u001b[90mImplementing this from scratch \u2014 once \u2014 gives you the mental model for what numpy / torch / tensorflow do under the hood. After that you can read the framework code without it feeling like magic. See \u001b[39m\u001b[34m\u001b[4mjs_exp_09\u001b[24m\u001b[39m\u001b[90m.\u001b[39m\r\n\r\n\u001b[1m\u001b[33mCROSS-ENTROPY LOSS\u001b[39m\u001b[22m\r\n\r\n  Given a probability distribution and the index of the true class, cross-entropy is \u001b[1m-log(probs[true_index])\u001b[22m. When the model puts high probability on the right answer, loss is small. When it's confident in the wrong answer, loss is large.\r\n\r\n  Pair this with softmax outputs and you have the loss function used to train almost every classification model.\r\n\r\n  NEXT TIER: generators, Proxy, typed arrays, performance patterns, and the closing image of the track \u2014 embedding lookup with cosine similarity, the foundation of semantic search.\r\n","5":"\u001b[1m\u001b[33mJAVASCRIPT \u00b7 TIER 5 CONCEPTS (MASTER)\u001b[39m\u001b[22m\r\n\r\n  \u001b[90mLast tier. The ideas here aren't more difficult; they're the patterns that production JS uses to express ML pipelines compactly. Generators stream data lazily. Proxy intercepts property access. Typed arrays let you work directly with the same memory layout your numerical libraries use.\u001b[39m\r\n\r\n\u001b[1m\u001b[33mGENERATORS\u001b[39m\u001b[22m\r\n\r\n  \u001b[33mfunction*\u001b[39m declares a generator. \u001b[33myield\u001b[39m produces a value and pauses. The next call resumes where it left off. State persists across yields without you wiring it up.\r\n\r\n      \u001b[33mfunction*\u001b[39m \u001b[36mrange_gen\u001b[39m(start, end) {\r\n          \u001b[33mfor\u001b[39m (\u001b[33mlet\u001b[39m i = start; i < end; i++) \u001b[33myield\u001b[39m i\r\n      }\r\n\r\n  \u001b[1mArray.from(range_gen(1, 5))\u001b[22m gives \u001b[1m[1, 2, 3, 4]\u001b[22m. Inside a \u001b[33mfor...of\u001b[39m loop the generator yields one value per iteration with no intermediate array.\r\n\r\n  \u001b[90mThis is how the iterator protocol works. for...of, spread, and Array.from all consume the same yield-based protocol. The same machinery powers data loaders that stream batches without materializing the full dataset.\u001b[39m\r\n\r\n\u001b[1m\u001b[33mPROXY\u001b[39m\u001b[22m\r\n\r\n  \u001b[33mProxy\u001b[39m wraps an object and intercepts operations on it. The handler defines \u001b[1mget\u001b[22m, \u001b[1mset\u001b[22m, \u001b[1mhas\u001b[22m, and other traps. Anything you don't define falls through to the target.\r\n\r\n      \u001b[33mconst\u001b[39m default_dict = () => \u001b[33mnew\u001b[39m Proxy({}, {\r\n          \u001b[36mget\u001b[39m(target, p) { \u001b[33mreturn\u001b[39m p \u001b[33min\u001b[39m target ? target[p] : \u001b[34m0\u001b[39m }\r\n      })\r\n\r\n  Use cases: validation on write, computed defaults on read, observability hooks. ORMs, state-management libraries, and reactive frameworks all use Proxy underneath.\r\n\r\n\u001b[1m\u001b[33mTYPED ARRAYS\u001b[39m\u001b[22m\r\n\r\n  \u001b[33mInt8Array\u001b[39m, \u001b[33mFloat32Array\u001b[39m, \u001b[33mFloat64Array\u001b[39m, and friends are arrays with fixed numeric layouts. Same memory representation numerical libraries use under the hood.\r\n\r\n      \u001b[33mconst\u001b[39m vec = \u001b[33mnew\u001b[39m Float32Array([\u001b[34m3\u001b[39m, \u001b[34m4\u001b[39m])\r\n      vec[\u001b[34m0\u001b[39m]    \u001b[90m3 (as Float32, not JS Number)\u001b[39m\r\n\r\n  Convert to a regular array with \u001b[1mArray.from(typed)\u001b[22m. Construct from a regular array by passing it to the constructor. Float32Array is what you'd use to interop with WASM models or shape memory the way a GPU expects.\r\n\r\n\u001b[1m\u001b[33mCLOSURES + FUNCTIONS AS VALUES\u001b[39m\u001b[22m\r\n\r\n  Functions are first-class. You pass them, return them, store them in arrays, decorate them. Memoization is the canonical Master example \u2014 wrap a function in a cache without changing its body.\r\n\r\n      \u001b[33mfunction\u001b[39m \u001b[36mmemoize\u001b[39m(fn) {\r\n          \u001b[33mconst\u001b[39m cache = \u001b[33mnew\u001b[39m \u001b[36mMap\u001b[39m()\r\n          \u001b[33mreturn\u001b[39m (x) => {\r\n              \u001b[33mif\u001b[39m (cache.has(x)) \u001b[33mreturn\u001b[39m cache.get(x)\r\n              \u001b[33mconst\u001b[39m v = fn(x)\r\n              cache.set(x, v)\r\n              \u001b[33mreturn\u001b[39m v\r\n          }\r\n      }\r\n\r\n  Same shape underlies retry wrappers, rate limiters, async-throttling. Reach for \"wrap a function in a function\" when you want to add behavior without modifying the original.\r\n\r\n\u001b[1m\u001b[33mTHE THIS BINDING GOTCHA\u001b[39m\u001b[22m\r\n\r\n  \u001b[1mthis\u001b[22m inside a regular \u001b[33mfunction\u001b[39m is determined by the call site \u2014 who's calling, not where it was defined. Inside an arrow function, \u001b[1mthis\u001b[22m is inherited from the enclosing lexical scope.\r\n\r\n      class Counter {\r\n          tick() {\r\n              \u001b[33mreturn\u001b[39m Promise.resolve().\u001b[35mthen\u001b[39m(() => this.start + \u001b[34m1\u001b[39m)\r\n          }\r\n      }\r\n\r\n  \u001b[31mReplace the arrow with \u001b[39m\u001b[33mfunction\u001b[39m\u001b[31m() { return this.start + 1 }\u001b[39m \u001b[31mand this is undefined inside the callback\u001b[39m \u2014 Promise.then doesn't pass the surrounding instance. The arrow function inherits this from tick's scope, which IS the instance. \u001b[90mSee \u001b[34m\u001b[4mjs_mas_07\u001b[24m\u001b[39m.\u001b[39m\r\n\r\n\u001b[1m\u001b[33mML PRIMITIVES \u2014 RETRIEVAL\u001b[39m\u001b[22m\r\n\r\n  This tier closes with the operations behind semantic search and retrieval-augmented generation:\r\n\r\n  \u001b[1mEmbedding lookup\u001b[22m selects rows from an embedding matrix by index. This is what a model's first layer does for token IDs.\r\n\r\n  \u001b[1mLayer normalization\u001b[22m standardizes a vector to mean 0, variance 1. Used in transformers between every attention block.\r\n\r\n  \u001b[1mTop-k retrieval\u001b[22m returns the k highest-scoring indices. Used to pick the most-similar embeddings to a query.\r\n\r\n  \u001b[1mMatrix-vector multiply (matvec)\u001b[22m is the core operation of a linear layer's forward pass \u2014 for each row of the matrix, dot it with the input vector.\r\n\r\n  \u001b[90mCombined: take a query, embed it, compute cosine similarity against every row of an embedding matrix, return the top-k indices. That's semantic search in 10 lines of JS. The capstone of this track.\u001b[39m\r\n\r\n  NEXT TIER: there isn't one. You've got the working vocabulary for ML primitives in JS. The next axes are libraries (numpy/torch in Python, ONNX in JS) and frameworks. The language itself doesn't get harder than what's here.\r\n"},"examples":{"1":["\u001b[1m\u001b[33mEXAMPLE 1\u001b[39m\u001b[22m\r\n\r\n  Bind a few names of different types and read them back. JavaScript figures out the types from the values.\r\n\r\n      \u001b[33mconst\u001b[39m shop = \u001b[32m'Terminal Auto'\u001b[39m\r\n      \u001b[33mconst\u001b[39m open_jobs = \u001b[34m7\u001b[39m\r\n      \u001b[33mconst\u001b[39m avg_ticket = \u001b[34m412.50\u001b[39m\r\n      \u001b[33mconst\u001b[39m is_open = \u001b[33mtrue\u001b[39m\r\n      console.log(shop, open_jobs, avg_ticket, is_open)\r\n\r\n  \u001b[90mOne assignment per line is the convention. console.log with multiple arguments space-separates them \u2014 that's just what console.log does, not a feature of the variables.\u001b[39m\r\n","\u001b[1m\u001b[33mEXAMPLE 2\u001b[39m\u001b[22m\r\n\r\n  Build a small object literal and read a property. Dot notation is cleanest for known keys.\r\n\r\n      \u001b[33mconst\u001b[39m car = { make: \u001b[32m'Nissan'\u001b[39m, model: \u001b[32m'Skyline GT-R'\u001b[39m, year: \u001b[34m1996\u001b[39m }\r\n      console.log(car.make)            \u001b[90m'Nissan'\u001b[39m\r\n      console.log(car[\u001b[32m'model'\u001b[39m])         \u001b[90m'Skyline GT-R' (bracket form)\u001b[39m\r\n\r\n  \u001b[90mReading a property that doesn't exist returns \u001b[39m\u001b[33mundefined\u001b[39m\u001b[90m, not an error \u2014 different from Python, which raises KeyError. Defensive code uses optional chaining (\u001b[39m\u001b[1mcar?.make?.brand\u001b[22m\u001b[90m) at higher tiers.\u001b[39m\r\n","\u001b[1m\u001b[33mEXAMPLE 3\u001b[39m\u001b[22m\r\n\r\n  Branch on a value, previewing arrays and loops at the next tier. You can already check one item at a time:\r\n\r\n      \u001b[33mconst\u001b[39m cost = \u001b[34m1500\u001b[39m\r\n      \u001b[33mif\u001b[39m (cost > \u001b[34m1000\u001b[39m) {\r\n          console.log(\u001b[32m'High'\u001b[39m)\r\n      } \u001b[33melse\u001b[39m {\r\n          console.log(\u001b[32m'Low'\u001b[39m)\r\n      }\r\n\r\n  \u001b[90mAt Amateur tier you'll meet \u001b[39m\u001b[33mmap\u001b[39m\u001b[90m and \u001b[39m\u001b[33mfilter\u001b[39m\u001b[90m, which run the same conditional logic across every element in an array without writing the loop yourself. The branching shape stays identical; the array method just feeds the variable repeatedly. See \u001b[39m\u001b[34m\u001b[4mjs_am_02\u001b[24m\u001b[39m\u001b[90m.\u001b[39m\r\n"],"2":["\u001b[1m\u001b[33mEXAMPLE 1\u001b[39m\u001b[22m\r\n\r\n  Chain filter and map. The shape is \u001b[1mnarrow then transform\u001b[22m.\r\n\r\n      \u001b[33mconst\u001b[39m orders = [\r\n          { cost: \u001b[34m100\u001b[39m, status: \u001b[32m'Open'\u001b[39m },\r\n          { cost: \u001b[34m250\u001b[39m, status: \u001b[32m'Closed'\u001b[39m },\r\n          { cost: \u001b[34m75\u001b[39m,  status: \u001b[32m'Open'\u001b[39m },\r\n      ]\r\n      \u001b[33mconst\u001b[39m open_costs = orders\r\n          .\u001b[35mfilter\u001b[39m(o => o.status === \u001b[32m'Open'\u001b[39m)\r\n          .\u001b[35mmap\u001b[39m(o => o.cost)\r\n      console.log(open_costs)    \u001b[90m[100, 75]\u001b[39m\r\n\r\n  \u001b[90mThree lines replace a six-line for-loop. The intent is in the verbs: \"filter to open, then map to cost.\" When you find yourself writing a for-loop with an if inside, reach for filter+map first.\u001b[39m\r\n","\u001b[1m\u001b[33mEXAMPLE 2\u001b[39m\u001b[22m\r\n\r\n  Object destructuring in a function parameter. The function reads its inputs straight from a config object.\r\n\r\n      \u001b[33mfunction\u001b[39m \u001b[36mformat_customer\u001b[39m({ name, phone = \u001b[32m'N/A'\u001b[39m }) {\r\n          \u001b[33mreturn\u001b[39m \u001b[32m`${name} \u2014 ${phone}`\u001b[39m\r\n      }\r\n      console.log(\u001b[36mformat_customer\u001b[39m({ name: \u001b[32m'Kara'\u001b[39m }))\r\n      \u001b[90m'Kara \u2014 N/A'\u001b[39m\r\n\r\n  \u001b[90mThree things in one signature: pull name and phone out of the arg, default phone to 'N/A' if missing, then build the output with a template literal. This is what a real-world API endpoint handler looks like.\u001b[39m\r\n","\u001b[1m\u001b[33mEXAMPLE 3\u001b[39m\u001b[22m\r\n\r\n  One-hot encoding, previewing the next tier's softmax problem. Right now the task is \"build an array with 1 at one index and 0 elsewhere\":\r\n\r\n      \u001b[33mfunction\u001b[39m \u001b[36mone_hot\u001b[39m(index, length) {\r\n          \u001b[33mreturn\u001b[39m Array.\u001b[35mfrom\u001b[39m({ length }, (_, i) => i === index ? \u001b[34m1\u001b[39m : \u001b[34m0\u001b[39m)\r\n      }\r\n      \u001b[36mone_hot\u001b[39m(\u001b[34m2\u001b[39m, \u001b[34m5\u001b[39m)    \u001b[90m[0, 0, 1, 0, 0]\u001b[39m\r\n\r\n  \u001b[90mAt Intermediate tier you'll write softmax, which goes the OTHER direction: it takes a vector of scores and returns a vector of probabilities. one_hot is the \"answer key\" shape; softmax is the \"model output\" shape. Both are arrays of length N where N is the number of classes. See \u001b[39m\u001b[34m\u001b[4mjs_int_01\u001b[24m\u001b[39m\u001b[90m.\u001b[39m\r\n"],"3":["\u001b[1m\u001b[33mEXAMPLE 1\u001b[39m\u001b[22m\r\n\r\n  A closure that maintains private state. The inner function \"remembers\" the variable from its enclosing scope across calls.\r\n\r\n      \u001b[33mfunction\u001b[39m \u001b[36mmake_logger\u001b[39m(prefix) {\r\n          \u001b[33mlet\u001b[39m count = \u001b[34m0\u001b[39m\r\n          \u001b[33mreturn\u001b[39m (msg) => {\r\n              count += \u001b[34m1\u001b[39m\r\n              console.log(\u001b[32m`[${prefix} ${count}] ${msg}`\u001b[39m)\r\n          }\r\n      }\r\n\r\n      \u001b[33mconst\u001b[39m log = \u001b[36mmake_logger\u001b[39m(\u001b[32m'INFO'\u001b[39m)\r\n      log(\u001b[32m'started'\u001b[39m)     \u001b[90m[INFO 1] started\u001b[39m\r\n      log(\u001b[32m'connected'\u001b[39m)   \u001b[90m[INFO 2] connected\u001b[39m\r\n\r\n  \u001b[90mThe count and prefix variables only live inside log. Two separate calls to make_logger produce two independent counters with independent prefixes. This is how event handlers, retry wrappers, and rate limiters are built in real code.\u001b[39m\r\n","\u001b[1m\u001b[33mEXAMPLE 2\u001b[39m\u001b[22m\r\n\r\n  Async work with try/catch and Promise.all. The pattern: do as much in parallel as possible, catch errors at the boundary.\r\n\r\n      \u001b[33masync\u001b[39m \u001b[33mfunction\u001b[39m \u001b[36mload_dashboard\u001b[39m(customer_id) {\r\n          \u001b[33mtry\u001b[39m {\r\n              \u001b[33mconst\u001b[39m [customer, vehicles, orders] = \u001b[33mawait\u001b[39m Promise.\u001b[35mall\u001b[39m([\r\n                  fetch_customer(customer_id),\r\n                  fetch_vehicles(customer_id),\r\n                  fetch_orders(customer_id),\r\n              ])\r\n              \u001b[33mreturn\u001b[39m { customer, vehicles, orders }\r\n          } \u001b[33mcatch\u001b[39m (e) {\r\n              console.error(\u001b[32m'dashboard load failed:'\u001b[39m, e.message)\r\n              \u001b[33mreturn\u001b[39m \u001b[33mnull\u001b[39m\r\n          }\r\n      }\r\n\r\n  \u001b[90mThree independent fetches run in parallel \u2014 total latency is the slowest one, not the sum. Any rejection lands in the catch, which returns null so the caller has a single shape to handle. This is the template for nearly every \"load page data\" function in a SPA.\u001b[39m\r\n","\u001b[1m\u001b[33mEXAMPLE 3\u001b[39m\u001b[22m\r\n\r\n  Softmax, the canonical first ML primitive. Two passes: compute the exponentials, then divide by their sum.\r\n\r\n      \u001b[33mfunction\u001b[39m \u001b[36msoftmax\u001b[39m(xs) {\r\n          \u001b[33mconst\u001b[39m exps = xs.\u001b[35mmap\u001b[39m(x => \u001b[33mMath\u001b[39m.exp(x))\r\n          \u001b[33mconst\u001b[39m sum  = exps.\u001b[35mreduce\u001b[39m((a, b) => a + b, \u001b[34m0\u001b[39m)\r\n          \u001b[33mreturn\u001b[39m exps.\u001b[35mmap\u001b[39m(e => e / sum)\r\n      }\r\n\r\n      \u001b[36msoftmax\u001b[39m([\u001b[34m1\u001b[39m, \u001b[34m2\u001b[39m, \u001b[34m3\u001b[39m])    \u001b[90m[0.090, 0.245, 0.665]\u001b[39m\r\n\r\n  \u001b[90mAt Experienced tier you'll write the numerically-stable version that subtracts max(xs) before exponentiating \u2014 same answer mathematically, but doesn't overflow on large inputs. The naive form above gives NaN on inputs around 700+. See \u001b[39m\u001b[34m\u001b[4mjs_exp_08\u001b[24m\u001b[39m\u001b[90m.\u001b[39m\r\n"],"4":["\u001b[1m\u001b[33mEXAMPLE 1\u001b[39m\u001b[22m\r\n\r\n  A class with a constructor, a method, and a property accessor. The canonical \"domain object\" shape in production code.\r\n\r\n      \u001b[33mclass\u001b[39m \u001b[36mOrder\u001b[39m {\r\n          \u001b[36mconstructor\u001b[39m(cost, status) {\r\n              this.cost = cost\r\n              this.status = status\r\n          }\r\n          \u001b[35mget\u001b[39m \u001b[36mtax\u001b[39m() { \u001b[33mreturn\u001b[39m this.cost * \u001b[34m0.08\u001b[39m }\r\n          \u001b[36mis_open\u001b[39m() { \u001b[33mreturn\u001b[39m this.status === \u001b[32m'Open'\u001b[39m }\r\n      }\r\n\r\n      \u001b[33mconst\u001b[39m o = \u001b[33mnew\u001b[39m \u001b[36mOrder\u001b[39m(\u001b[34m100\u001b[39m, \u001b[32m'Open'\u001b[39m)\r\n      console.log(o.tax)         \u001b[90m8 (no parens, it's a getter)\u001b[39m\r\n      console.log(o.is_open())   \u001b[90mtrue (parens, it's a method)\u001b[39m\r\n\r\n  \u001b[90mGetters look like attributes from outside; methods look like functions. The choice depends on whether the operation feels like \"what is this thing\" (getter) or \"do this thing\" (method). Tax is data derived from cost, so it's a getter.\u001b[39m\r\n","\u001b[1m\u001b[33mEXAMPLE 2\u001b[39m\u001b[22m\r\n\r\n  Stable softmax \u2014 the production version of the algorithm from Intermediate. The shift before exponentiating prevents overflow without changing the result.\r\n\r\n      \u001b[33mfunction\u001b[39m \u001b[36mstable_softmax\u001b[39m(xs) {\r\n          \u001b[33mconst\u001b[39m shift = \u001b[33mMath\u001b[39m.max(...xs)\r\n          \u001b[33mconst\u001b[39m exps  = xs.\u001b[35mmap\u001b[39m(x => \u001b[33mMath\u001b[39m.exp(x - shift))\r\n          \u001b[33mconst\u001b[39m sum   = exps.\u001b[35mreduce\u001b[39m((a, b) => a + b, \u001b[34m0\u001b[39m)\r\n          \u001b[33mreturn\u001b[39m exps.\u001b[35mmap\u001b[39m(e => e / sum)\r\n      }\r\n\r\n      \u001b[36mstable_softmax\u001b[39m([\u001b[34m1000\u001b[39m, \u001b[34m1001\u001b[39m, \u001b[34m1002\u001b[39m])\r\n      \u001b[90m[0.090, 0.245, 0.665] \u2014 same as softmax([1, 2, 3])\u001b[39m\r\n\r\n  \u001b[90mThe naive softmax from Intermediate would return [NaN, NaN, NaN] on this input because Math.exp(1002) overflows to Infinity, and Infinity / Infinity is NaN. The shift makes the largest input 0, so the largest exponential is exp(0) = 1.\u001b[39m\r\n","\u001b[1m\u001b[33mEXAMPLE 3\u001b[39m\u001b[22m\r\n\r\n  Tiny feedforward pass \u2014 the closing example of Experienced and the shape that Master tier extends. One linear layer with ReLU activation.\r\n\r\n      \u001b[33mfunction\u001b[39m \u001b[36mforward\u001b[39m(x, W, b) {\r\n          \u001b[33mreturn\u001b[39m W.\u001b[35mmap\u001b[39m((row, i) => {\r\n              \u001b[33mconst\u001b[39m z = row.\u001b[35mreduce\u001b[39m((acc, w, j) => acc + w * x[j], \u001b[34m0\u001b[39m) + b[i]\r\n              \u001b[33mreturn\u001b[39m \u001b[33mMath\u001b[39m.max(\u001b[34m0\u001b[39m, z)\r\n          })\r\n      }\r\n\r\n  \u001b[90mRead it as: for each row of the weight matrix, dot it with x, add the bias, apply ReLU. That's the entire forward pass of one layer. At Master tier you'll batch this with matrix-vector multiply (matvec) and use the output to drive nearest-neighbor retrieval. See \u001b[39m\u001b[34m\u001b[4mjs_mas_09\u001b[24m\u001b[39m\u001b[90m.\u001b[39m\r\n"],"5":["\u001b[1m\u001b[33mEXAMPLE 1\u001b[39m\u001b[22m\r\n\r\n  A generator that streams transformed data without materializing the intermediate array. Constant memory regardless of input size.\r\n\r\n      \u001b[33mfunction*\u001b[39m \u001b[36mas_floats\u001b[39m(rows) {\r\n          \u001b[33mfor\u001b[39m (\u001b[33mconst\u001b[39m row \u001b[33mof\u001b[39m rows) {\r\n              \u001b[33myield\u001b[39m row.\u001b[35mmap\u001b[39m(x => \u001b[33mNumber\u001b[39m(x))\r\n          }\r\n      }\r\n\r\n      \u001b[33mfor\u001b[39m (\u001b[33mconst\u001b[39m [cost, qty] \u001b[33mof\u001b[39m \u001b[36mas_floats\u001b[39m(csv_rows)) {\r\n          console.log(cost * qty)\r\n      }\r\n\r\n  \u001b[90mTwo iterators chained. The CSV rows are read lazily; as_floats yields each parsed row on demand; the for-of loop consumes them one at a time. This is the same pattern behind PyTorch's DataLoader and TensorFlow's tf.data.Dataset, just with batching and shuffling layered on.\u001b[39m\r\n","\u001b[1m\u001b[33mEXAMPLE 2\u001b[39m\u001b[22m\r\n\r\n  A Proxy that adds default values for missing keys. Same shape underlies reactive frameworks where reads trigger dependency tracking.\r\n\r\n      \u001b[33mfunction\u001b[39m \u001b[36mdefault_dict\u001b[39m(fallback) {\r\n          \u001b[33mreturn\u001b[39m \u001b[33mnew\u001b[39m Proxy({}, {\r\n              \u001b[36mget\u001b[39m(target, p) {\r\n                  \u001b[33mreturn\u001b[39m p \u001b[33min\u001b[39m target ? target[p] : fallback\r\n              }\r\n          })\r\n      }\r\n\r\n      \u001b[33mconst\u001b[39m counts = \u001b[36mdefault_dict\u001b[39m(\u001b[34m0\u001b[39m)\r\n      counts.apple += \u001b[34m1\u001b[39m    \u001b[90mreads 0 (default), writes 1\u001b[39m\r\n      counts.apple += \u001b[34m1\u001b[39m    \u001b[90mreads 1, writes 2\u001b[39m\r\n      console.log(counts.banana)   \u001b[90m0 (still default \u2014 never written)\u001b[39m\r\n\r\n  \u001b[90mSame pattern is how Vue's reactive() and MobX's observable() work. The trap intercepts every property read, so the framework can record which components depend on which fields and re-render when those fields change.\u001b[39m\r\n","\u001b[1m\u001b[33mEXAMPLE 3\u001b[39m\u001b[22m\r\n\r\n  The capstone \u2014 nearest-embedding lookup by cosine similarity. Pulls together cosine_sim from Intermediate, top_k from earlier in Master, and embedding indexing.\r\n\r\n      \u001b[33mfunction\u001b[39m \u001b[36mcosine_sim\u001b[39m(a, b) {\r\n          \u001b[33mlet\u001b[39m d = \u001b[34m0\u001b[39m, ma = \u001b[34m0\u001b[39m, mb = \u001b[34m0\u001b[39m\r\n          \u001b[33mfor\u001b[39m (\u001b[33mlet\u001b[39m i = \u001b[34m0\u001b[39m; i < a.length; i++) {\r\n              d  += a[i] * b[i]\r\n              ma += a[i] * a[i]\r\n              mb += b[i] * b[i]\r\n          }\r\n          \u001b[33mreturn\u001b[39m d / (\u001b[33mMath\u001b[39m.sqrt(ma) * \u001b[33mMath\u001b[39m.sqrt(mb))\r\n      }\r\n\r\n  Then nearest() pairs each row's similarity with its index, sorts descending, slices the top k, and returns just the indices:\r\n\r\n      \u001b[33mfunction\u001b[39m \u001b[36mnearest\u001b[39m(embeddings, query, k) {\r\n          \u001b[33mreturn\u001b[39m embeddings\r\n              .\u001b[35mmap\u001b[39m((row, i) => [\u001b[36mcosine_sim\u001b[39m(row, query), i])\r\n              .\u001b[35msort\u001b[39m((a, b) => b[\u001b[34m0\u001b[39m] - a[\u001b[34m0\u001b[39m] || a[\u001b[34m1\u001b[39m] - b[\u001b[34m1\u001b[39m])\r\n              .\u001b[35mslice\u001b[39m(\u001b[34m0\u001b[39m, k)\r\n              .\u001b[35mmap\u001b[39m(pair => pair[\u001b[34m1\u001b[39m])\r\n      }\r\n\r\n  \u001b[90mThis is the core operation behind semantic search and RAG. Encode a query into a vector, compute cosine similarity to every row of a precomputed embedding matrix, return the top-k matching indices. Real systems use ANN indexes (FAISS, HNSW) for scale, but the algorithmic shape is exactly this. If you can read this, you can read the source of nearly any retrieval system. See \u001b[39m\u001b[34m\u001b[4mjs_mas_10\u001b[24m\u001b[39m\u001b[90m.\u001b[39m\r\n\r\n  \u001b[90mThat's the JavaScript track. From \u001b[39m\u001b[32m'Hello, world'\u001b[39m\u001b[90m in Tier 1 to a working semantic-search loop in Tier 5. The vocabulary fits on a page; the patterns take longer to internalize.\u001b[39m\r\n"]}},"rust":{"cheatsheet":{"ansi":"\u001b[1m\u001b[33mRUST CHEATSHEET\u001b[39m\u001b[22m\r\n\r\n  \u001b[90mA working reference for the whole language. Skim it once, come back when stuck.\u001b[39m\r\n\r\n\u001b[1m\u001b[33mVARIABLES AND TYPES\u001b[39m\u001b[22m\r\n\r\n  \u001b[33mlet\u001b[39m binds an immutable name; \u001b[33mlet mut\u001b[39m makes it reassignable. Rust infers most types, or you annotate with \u001b[33m:\u001b[39m \u001b[36mType\u001b[39m.\r\n\r\n      \u001b[33mlet\u001b[39m rate: \u001b[36mf64\u001b[39m = \u001b[34m0.05\u001b[39m;\r\n      \u001b[33mlet\u001b[39m \u001b[33mmut\u001b[39m count = \u001b[34m0\u001b[39m;          \u001b[90mi32 by default\u001b[39m\r\n      \u001b[33mlet\u001b[39m open = \u001b[33mtrue\u001b[39m;            \u001b[90mbool\u001b[39m\r\n\r\n  \u001b[31mBooleans are lowercase\u001b[39m true/false. Numeric literals can carry a type suffix (\u001b[34m0u8\u001b[39m, \u001b[34m1.0f64\u001b[39m). Every statement ends with \u001b[33m;\u001b[39m.\r\n\r\n\u001b[1m\u001b[33mOWNERSHIP AND BORROWING\u001b[39m\u001b[22m\r\n\r\n  Each value has one owner. Assigning or passing it \u001b[1mmoves\u001b[22m ownership; the old name is then invalid \u2014 unless the type is \u001b[36mCopy\u001b[39m (integers, bool, f64).\r\n\r\n      \u001b[33mlet\u001b[39m a = \u001b[36mString\u001b[39m::from(\u001b[32m\"hi\"\u001b[39m);\r\n      \u001b[33mlet\u001b[39m b = a;\r\n          a  --X         \u001b[90mmoved out; using a is now a compile error\u001b[39m\r\n          b  -->  \"hi\"   \u001b[90mb owns the heap data\u001b[39m\r\n\r\n  \u001b[1mBorrow\u001b[22m instead of moving with \u001b[33m&\u001b[39m. A shared borrow \u001b[33m&T\u001b[39m allows many readers; an exclusive borrow \u001b[33m&mut T\u001b[39m allows exactly one writer.\r\n\r\n          &T      shared      many readers,  no writer\r\n          &mut T  exclusive   one writer,    nothing else at once\r\n\r\n  \u001b[31mA &mut borrow cannot coexist with any other borrow.\u001b[39m That rule, checked at compile time, is what makes Rust memory-safe without a garbage collector.\r\n\r\n\u001b[1m\u001b[33mCOLLECTIONS\u001b[39m\u001b[22m\r\n\r\n  \u001b[36mVec<T>\u001b[39m is a growable array; \u001b[36mString\u001b[39m is an owned, growable string; \u001b[36m&str\u001b[39m is a borrowed string slice. Tuples group fixed-size values.\r\n\r\n      \u001b[33mlet\u001b[39m xs: \u001b[36mVec<i32>\u001b[39m = \u001b[35mvec!\u001b[39m[\u001b[34m1\u001b[39m, \u001b[34m2\u001b[39m, \u001b[34m3\u001b[39m];\r\n      \u001b[33mlet\u001b[39m name: \u001b[36mString\u001b[39m = \u001b[36mString\u001b[39m::from(\u001b[32m\"ada\"\u001b[39m);\r\n      \u001b[33mlet\u001b[39m pair = (\u001b[34m3\u001b[39m, \u001b[34m5\u001b[39m);          \u001b[90m(i32, i32)\u001b[39m\r\n\r\n\u001b[1m\u001b[33mCONTROL FLOW\u001b[39m\u001b[22m\r\n\r\n  \u001b[33mif\u001b[39m takes no parentheses; braces are always required. \u001b[33mmatch\u001b[39m is an expression and must be exhaustive \u2014 \u001b[33m_\u001b[39m is the catch-all arm.\r\n\r\n      \u001b[33mif\u001b[39m cost > \u001b[34m1000\u001b[39m { \u001b[32m\"high\"\u001b[39m } \u001b[33melse\u001b[39m { \u001b[32m\"low\"\u001b[39m }\r\n      \u001b[33mmatch\u001b[39m n { \u001b[34m1\u001b[39m => \u001b[32m\"one\"\u001b[39m, _ => \u001b[32m\"many\"\u001b[39m }\r\n\r\n\u001b[1m\u001b[33mMACROS\u001b[39m\u001b[22m\r\n\r\n  A trailing \u001b[33m!\u001b[39m marks a \u001b[1mmacro\u001b[22m, not a function. \u001b[35mprintln!\u001b[39m prints a line \u2014 \u001b[33m{}\u001b[39m is a placeholder filled by the args that follow; \u001b[35mformat!\u001b[39m builds a \u001b[36mString\u001b[39m the same way; \u001b[35mvec!\u001b[39m constructs a \u001b[36mVec\u001b[39m.\r\n\r\n      \u001b[35mprintln!\u001b[39m(\u001b[32m\"open: {}\"\u001b[39m, count);\r\n      \u001b[33mlet\u001b[39m msg = \u001b[35mformat!\u001b[39m(\u001b[32m\"{} bays\"\u001b[39m, n);\r\n\r\n\u001b[1m\u001b[33mFUNCTIONS AND CLOSURES\u001b[39m\u001b[22m\r\n\r\n  \u001b[33mfn\u001b[39m declares a function; the final expression (no \u001b[33m;\u001b[39m) is the return value. Closures use \u001b[33m|args|\u001b[39m and capture their environment.\r\n\r\n      \u001b[33mfn\u001b[39m \u001b[36mdouble\u001b[39m(x: \u001b[36mi32\u001b[39m) -> \u001b[36mi32\u001b[39m { x * \u001b[34m2\u001b[39m }\r\n      \u001b[33mlet\u001b[39m add = |a, b| a + b;\r\n      \u001b[33mmove\u001b[39m || weights      \u001b[90mmove: the closure owns weights (non-Copy)\u001b[39m\r\n\r\n\u001b[1m\u001b[33mITERATORS\u001b[39m\u001b[22m\r\n\r\n  \u001b[35m.iter()\u001b[39m yields \u001b[33m&T\u001b[39m references. Chain \u001b[35m.map\u001b[39m, \u001b[35m.filter\u001b[39m, \u001b[35m.fold\u001b[39m, \u001b[35m.zip\u001b[39m, \u001b[35m.enumerate\u001b[39m; finish with \u001b[35m.sum\u001b[39m, \u001b[35m.count\u001b[39m, \u001b[35m.collect\u001b[39m, or \u001b[35m.max_by\u001b[39m.\r\n\r\n      \u001b[33mlet\u001b[39m ss: \u001b[36mf64\u001b[39m = xs.\u001b[35miter\u001b[39m().\u001b[35mmap\u001b[39m(|&x| x * x).\u001b[35msum\u001b[39m();\r\n\r\n  \u001b[90mIn a closure, \u001b[33m|&x|\u001b[39m destructures the reference so x is a value; \u001b[33m|x| *x\u001b[39m dereferences in the body. Both are accepted.\u001b[39m\r\n\r\n\u001b[1m\u001b[33mOPTION AND RESULT\u001b[39m\u001b[22m\r\n\r\n  \u001b[36mOption<T>\u001b[39m is \u001b[33mSome(v)\u001b[39m or \u001b[33mNone\u001b[39m; \u001b[36mResult<T, E>\u001b[39m is \u001b[33mOk(v)\u001b[39m or \u001b[33mErr(e)\u001b[39m. The \u001b[33m?\u001b[39m operator returns Err to your caller; \u001b[31m.unwrap() instead crashes the program on Err\u001b[39m.\r\n\r\n      \u001b[33mlet\u001b[39m v = s.\u001b[35mparse\u001b[39m()?;            \u001b[90mreturns Err early\u001b[39m\r\n      x.\u001b[35munwrap_or\u001b[39m(\u001b[34m0.0\u001b[39m)                \u001b[90mvalue, or a default\u001b[39m\r\n\r\n\u001b[1m\u001b[33mTRAITS AND GENERICS\u001b[39m\u001b[22m\r\n\r\n  A \u001b[33mtrait\u001b[39m defines shared behavior; \u001b[33mimpl\u001b[39m ... \u001b[33mfor\u001b[39m implements it for a type. Generics use \u001b[33m<T>\u001b[39m with bounds like \u001b[33mT: Copy + PartialOrd\u001b[39m.\r\n\r\n      \u001b[33mtrait\u001b[39m \u001b[36mActivation\u001b[39m { \u001b[33mfn\u001b[39m \u001b[36mapply\u001b[39m(&self, x: \u001b[36mf64\u001b[39m) -> \u001b[36mf64\u001b[39m; }\r\n      \u001b[33mimpl\u001b[39m \u001b[36mActivation\u001b[39m \u001b[33mfor\u001b[39m \u001b[36mRelu\u001b[39m { \u001b[90m...\u001b[39m }\r\n\r\n\u001b[1m\u001b[33mLIFETIMES\u001b[39m\u001b[22m\r\n\r\n  A lifetime \u001b[33m'a\u001b[39m ties a borrow's validity to a scope. A struct holding a reference must name one, so the borrow can't outlive the data it points to.\r\n\r\n      \u001b[33mstruct\u001b[39m \u001b[36mDoc<'a>\u001b[39m { text: &\u001b[33m'a\u001b[39m \u001b[36mstr\u001b[39m }\r\n          owner --> \"...\"   \u001b[90mthe string the slice points into\u001b[39m\r\n          Doc<'a> borrows it; Doc must not outlive owner\r\n\r\n\u001b[1m\u001b[33mSMART POINTERS\u001b[39m\u001b[22m\r\n\r\n  \u001b[36mBox<T>\u001b[39m heap-allocates one value (and enables \u001b[33mdyn\u001b[39m trait objects). \u001b[36mRc<T>\u001b[39m is single-threaded shared ownership; \u001b[36mArc<T>\u001b[39m is its atomic, thread-safe twin.\r\n\r\n      \u001b[33mlet\u001b[39m layer: \u001b[36mBox<dyn Activation>\u001b[39m = \u001b[36mBox\u001b[39m::new(relu);\r\n      \u001b[33mlet\u001b[39m shared = \u001b[36mRc\u001b[39m::new(table);    \u001b[36mRc\u001b[39m::clone(&shared);\r\n\r\n\u001b[1m\u001b[33mASYNC AND UNSAFE\u001b[39m\u001b[22m\r\n\r\n  \u001b[33masync fn\u001b[39m returns a future; drive it with a \u001b[31mpostfix\u001b[39m \u001b[33m.await\u001b[39m (\u001b[31mnot\u001b[39m a prefix as in Python/JS). \u001b[33munsafe\u001b[39m blocks permit raw-pointer deref and FFI; \u001b[33mextern \"C\"\u001b[39m exposes the C ABI.\r\n\r\n      \u001b[33mlet\u001b[39m w = load_checkpoint().\u001b[35mawait\u001b[39m;\r\n      \u001b[33munsafe\u001b[39m { *p }                \u001b[90mderef a raw pointer\u001b[39m\r\n\r\n\u001b[1m\u001b[33mTAG REFERENCE\u001b[39m\u001b[22m\r\n\r\n  \u001b[33mamber\u001b[39m keywords. \u001b[36mteal\u001b[39m types/callables. \u001b[32mgreen\u001b[39m strings. \u001b[34mblue\u001b[39m numerics. \u001b[35mpurple\u001b[39m methods. \u001b[31mred\u001b[39m warnings. \u001b[90mdim\u001b[39m asides. \u001b[1mbold\u001b[22m emphasis.\r\n","html":"<div class=\"cs-section\"><h4 class=\"cs-h\">RUST CHEATSHEET</h4><p class=\"cs-prose\"><span class=\"cs-dim\">A working reference for the whole language. Skim it once, come back when stuck.</span></p></div><div class=\"cs-section\"><h4 class=\"cs-h\">VARIABLES AND TYPES</h4><p class=\"cs-prose\"><span class=\"cs-amber\">let</span> binds an immutable name; <span class=\"cs-amber\">let mut</span> makes it reassignable. Rust infers most types, or you annotate with <span class=\"cs-amber\">:</span> <span class=\"cs-teal\">Type</span>.</p><pre class=\"cs-code\"><code>  <span class=\"cs-amber\">let</span> rate: <span class=\"cs-teal\">f64</span> = <span class=\"cs-blue\">0.05</span>;\n  <span class=\"cs-amber\">let</span> <span class=\"cs-amber\">mut</span> count = <span class=\"cs-blue\">0</span>;          <span class=\"cs-dim\">i32 by default</span>\n  <span class=\"cs-amber\">let</span> open = <span class=\"cs-amber\">true</span>;            <span class=\"cs-dim\">bool</span></code></pre><p class=\"cs-prose\"><span class=\"cs-red\">Booleans are lowercase</span> true/false. Numeric literals can carry a type suffix (<span class=\"cs-blue\">0u8</span>, <span class=\"cs-blue\">1.0f64</span>). Every statement ends with <span class=\"cs-amber\">;</span>.</p></div><div class=\"cs-section\"><h4 class=\"cs-h\">OWNERSHIP AND BORROWING</h4><p class=\"cs-prose\">Each value has one owner. Assigning or passing it <span class=\"cs-bold\">moves</span> ownership; the old name is then invalid \u2014 unless the type is <span class=\"cs-teal\">Copy</span> (integers, bool, f64).</p><pre class=\"cs-code\"><code>  <span class=\"cs-amber\">let</span> a = <span class=\"cs-teal\">String</span>::from(<span class=\"cs-green\">&quot;hi&quot;</span>);\n  <span class=\"cs-amber\">let</span> b = a;\n      a  --X         <span class=\"cs-dim\">moved out; using a is now a compile error</span>\n      b  --&gt;  &quot;hi&quot;   <span class=\"cs-dim\">b owns the heap data</span></code></pre><p class=\"cs-prose\"><span class=\"cs-bold\">Borrow</span> instead of moving with <span class=\"cs-amber\">&amp;</span>. A shared borrow <span class=\"cs-amber\">&amp;T</span> allows many readers; an exclusive borrow <span class=\"cs-amber\">&amp;mut T</span> allows exactly one writer.</p><pre class=\"cs-code\"><code>      &amp;T      shared      many readers,  no writer\n      &amp;mut T  exclusive   one writer,    nothing else at once</code></pre><p class=\"cs-prose\"><span class=\"cs-red\">A &amp;mut borrow cannot coexist with any other borrow.</span> That rule, checked at compile time, is what makes Rust memory-safe without a garbage collector.</p></div><div class=\"cs-section\"><h4 class=\"cs-h\">COLLECTIONS</h4><p class=\"cs-prose\"><span class=\"cs-teal\">Vec&lt;T&gt;</span> is a growable array; <span class=\"cs-teal\">String</span> is an owned, growable string; <span class=\"cs-teal\">&amp;str</span> is a borrowed string slice. Tuples group fixed-size values.</p><pre class=\"cs-code\"><code>  <span class=\"cs-amber\">let</span> xs: <span class=\"cs-teal\">Vec&lt;i32&gt;</span> = <span class=\"cs-purple\">vec!</span>[<span class=\"cs-blue\">1</span>, <span class=\"cs-blue\">2</span>, <span class=\"cs-blue\">3</span>];\n  <span class=\"cs-amber\">let</span> name: <span class=\"cs-teal\">String</span> = <span class=\"cs-teal\">String</span>::from(<span class=\"cs-green\">&quot;ada&quot;</span>);\n  <span class=\"cs-amber\">let</span> pair = (<span class=\"cs-blue\">3</span>, <span class=\"cs-blue\">5</span>);          <span class=\"cs-dim\">(i32, i32)</span></code></pre></div><div class=\"cs-section\"><h4 class=\"cs-h\">CONTROL FLOW</h4><p class=\"cs-prose\"><span class=\"cs-amber\">if</span> takes no parentheses; braces are always required. <span class=\"cs-amber\">match</span> is an expression and must be exhaustive \u2014 <span class=\"cs-amber\">_</span> is the catch-all arm.</p><pre class=\"cs-code\"><code>  <span class=\"cs-amber\">if</span> cost &gt; <span class=\"cs-blue\">1000</span> { <span class=\"cs-green\">&quot;high&quot;</span> } <span class=\"cs-amber\">else</span> { <span class=\"cs-green\">&quot;low&quot;</span> }\n  <span class=\"cs-amber\">match</span> n { <span class=\"cs-blue\">1</span> =&gt; <span class=\"cs-green\">&quot;one&quot;</span>, _ =&gt; <span class=\"cs-green\">&quot;many&quot;</span> }</code></pre></div><div class=\"cs-section\"><h4 class=\"cs-h\">MACROS</h4><p class=\"cs-prose\">A trailing <span class=\"cs-amber\">!</span> marks a <span class=\"cs-bold\">macro</span>, not a function. <span class=\"cs-purple\">println!</span> prints a line \u2014 <span class=\"cs-amber\">{}</span> is a placeholder filled by the args that follow; <span class=\"cs-purple\">format!</span> builds a <span class=\"cs-teal\">String</span> the same way; <span class=\"cs-purple\">vec!</span> constructs a <span class=\"cs-teal\">Vec</span>.</p><pre class=\"cs-code\"><code>  <span class=\"cs-purple\">println!</span>(<span class=\"cs-green\">&quot;open: {}&quot;</span>, count);\n  <span class=\"cs-amber\">let</span> msg = <span class=\"cs-purple\">format!</span>(<span class=\"cs-green\">&quot;{} bays&quot;</span>, n);</code></pre></div><div class=\"cs-section\"><h4 class=\"cs-h\">FUNCTIONS AND CLOSURES</h4><p class=\"cs-prose\"><span class=\"cs-amber\">fn</span> declares a function; the final expression (no <span class=\"cs-amber\">;</span>) is the return value. Closures use <span class=\"cs-amber\">|args|</span> and capture their environment.</p><pre class=\"cs-code\"><code>  <span class=\"cs-amber\">fn</span> <span class=\"cs-teal\">double</span>(x: <span class=\"cs-teal\">i32</span>) -&gt; <span class=\"cs-teal\">i32</span> { x * <span class=\"cs-blue\">2</span> }\n  <span class=\"cs-amber\">let</span> add = |a, b| a + b;\n  <span class=\"cs-amber\">move</span> || weights      <span class=\"cs-dim\">move: the closure owns weights (non-Copy)</span></code></pre></div><div class=\"cs-section\"><h4 class=\"cs-h\">ITERATORS</h4><p class=\"cs-prose\"><span class=\"cs-purple\">.iter()</span> yields <span class=\"cs-amber\">&amp;T</span> references. Chain <span class=\"cs-purple\">.map</span>, <span class=\"cs-purple\">.filter</span>, <span class=\"cs-purple\">.fold</span>, <span class=\"cs-purple\">.zip</span>, <span class=\"cs-purple\">.enumerate</span>; finish with <span class=\"cs-purple\">.sum</span>, <span class=\"cs-purple\">.count</span>, <span class=\"cs-purple\">.collect</span>, or <span class=\"cs-purple\">.max_by</span>.</p><pre class=\"cs-code\"><code>  <span class=\"cs-amber\">let</span> ss: <span class=\"cs-teal\">f64</span> = xs.<span class=\"cs-purple\">iter</span>().<span class=\"cs-purple\">map</span>(|&amp;x| x * x).<span class=\"cs-purple\">sum</span>();</code></pre><p class=\"cs-prose\"><span class=\"cs-dim\">In a closure, <span class=\"cs-amber\">|&amp;x|</span> destructures the reference so x is a value; <span class=\"cs-amber\">|x| *x</span> dereferences in the body. Both are accepted.</span></p></div><div class=\"cs-section\"><h4 class=\"cs-h\">OPTION AND RESULT</h4><p class=\"cs-prose\"><span class=\"cs-teal\">Option&lt;T&gt;</span> is <span class=\"cs-amber\">Some(v)</span> or <span class=\"cs-amber\">None</span>; <span class=\"cs-teal\">Result&lt;T, E&gt;</span> is <span class=\"cs-amber\">Ok(v)</span> or <span class=\"cs-amber\">Err(e)</span>. The <span class=\"cs-amber\">?</span> operator returns Err to your caller; <span class=\"cs-red\">.unwrap() instead crashes the program on Err</span>.</p><pre class=\"cs-code\"><code>  <span class=\"cs-amber\">let</span> v = s.<span class=\"cs-purple\">parse</span>()?;            <span class=\"cs-dim\">returns Err early</span>\n  x.<span class=\"cs-purple\">unwrap_or</span>(<span class=\"cs-blue\">0.0</span>)                <span class=\"cs-dim\">value, or a default</span></code></pre></div><div class=\"cs-section\"><h4 class=\"cs-h\">TRAITS AND GENERICS</h4><p class=\"cs-prose\">A <span class=\"cs-amber\">trait</span> defines shared behavior; <span class=\"cs-amber\">impl</span> ... <span class=\"cs-amber\">for</span> implements it for a type. Generics use <span class=\"cs-amber\">&lt;T&gt;</span> with bounds like <span class=\"cs-amber\">T: Copy + PartialOrd</span>.</p><pre class=\"cs-code\"><code>  <span class=\"cs-amber\">trait</span> <span class=\"cs-teal\">Activation</span> { <span class=\"cs-amber\">fn</span> <span class=\"cs-teal\">apply</span>(&amp;self, x: <span class=\"cs-teal\">f64</span>) -&gt; <span class=\"cs-teal\">f64</span>; }\n  <span class=\"cs-amber\">impl</span> <span class=\"cs-teal\">Activation</span> <span class=\"cs-amber\">for</span> <span class=\"cs-teal\">Relu</span> { <span class=\"cs-dim\">...</span> }</code></pre></div><div class=\"cs-section\"><h4 class=\"cs-h\">LIFETIMES</h4><p class=\"cs-prose\">A lifetime <span class=\"cs-amber\">'a</span> ties a borrow's validity to a scope. A struct holding a reference must name one, so the borrow can't outlive the data it points to.</p><pre class=\"cs-code\"><code>  <span class=\"cs-amber\">struct</span> <span class=\"cs-teal\">Doc&lt;'a&gt;</span> { text: &amp;<span class=\"cs-amber\">'a</span> <span class=\"cs-teal\">str</span> }\n      owner --&gt; &quot;...&quot;   <span class=\"cs-dim\">the string the slice points into</span>\n      Doc&lt;'a&gt; borrows it; Doc must not outlive owner</code></pre></div><div class=\"cs-section\"><h4 class=\"cs-h\">SMART POINTERS</h4><p class=\"cs-prose\"><span class=\"cs-teal\">Box&lt;T&gt;</span> heap-allocates one value (and enables <span class=\"cs-amber\">dyn</span> trait objects). <span class=\"cs-teal\">Rc&lt;T&gt;</span> is single-threaded shared ownership; <span class=\"cs-teal\">Arc&lt;T&gt;</span> is its atomic, thread-safe twin.</p><pre class=\"cs-code\"><code>  <span class=\"cs-amber\">let</span> layer: <span class=\"cs-teal\">Box&lt;dyn Activation&gt;</span> = <span class=\"cs-teal\">Box</span>::new(relu);\n  <span class=\"cs-amber\">let</span> shared = <span class=\"cs-teal\">Rc</span>::new(table);    <span class=\"cs-teal\">Rc</span>::clone(&amp;shared);</code></pre></div><div class=\"cs-section\"><h4 class=\"cs-h\">ASYNC AND UNSAFE</h4><p class=\"cs-prose\"><span class=\"cs-amber\">async fn</span> returns a future; drive it with a <span class=\"cs-red\">postfix</span> <span class=\"cs-amber\">.await</span> (<span class=\"cs-red\">not</span> a prefix as in Python/JS). <span class=\"cs-amber\">unsafe</span> blocks permit raw-pointer deref and FFI; <span class=\"cs-amber\">extern &quot;C&quot;</span> exposes the C ABI.</p><pre class=\"cs-code\"><code>  <span class=\"cs-amber\">let</span> w = load_checkpoint().<span class=\"cs-purple\">await</span>;\n  <span class=\"cs-amber\">unsafe</span> { *p }                <span class=\"cs-dim\">deref a raw pointer</span></code></pre></div><div class=\"cs-section\"><h4 class=\"cs-h\">TAG REFERENCE</h4><p class=\"cs-prose\"><span class=\"cs-amber\">amber</span> keywords. <span class=\"cs-teal\">teal</span> types/callables. <span class=\"cs-green\">green</span> strings. <span class=\"cs-blue\">blue</span> numerics. <span class=\"cs-purple\">purple</span> methods. <span class=\"cs-red\">red</span> warnings. <span class=\"cs-dim\">dim</span> asides. <span class=\"cs-bold\">bold</span> emphasis.</p></div>"},"tiers":{"1":"\u001b[1m\u001b[33mRUST \u00b7 TIER 1 CONCEPTS (INTRODUCTORY)\u001b[39m\u001b[22m\r\n\r\n  \u001b[90mRead this once. The first ten questions cover binding values, simple types, printing, and reading from small collections.\u001b[39m\r\n\r\n  Rust is a compiled, statically-typed systems language built around memory safety without a garbage collector. At this tier the goal is to bind values to names, give them types, and read them back.\r\n\r\n\u001b[1m\u001b[33mBINDING VALUES\u001b[39m\u001b[22m\r\n\r\n  \u001b[33mlet\u001b[39m binds a name. Bindings are \u001b[1mimmutable by default\u001b[22m \u2014 add \u001b[33mmut\u001b[39m when you intend to reassign. Every statement ends with \u001b[33m;\u001b[39m.\r\n\r\n      \u001b[33mlet\u001b[39m garage = \u001b[32m\"Terminal Auto\"\u001b[39m;   \u001b[90mtype inferred: &str\u001b[39m\r\n      \u001b[33mlet\u001b[39m \u001b[33mmut\u001b[39m bays = \u001b[34m4\u001b[39m;              \u001b[90mmutable i32\u001b[39m\r\n      bays = \u001b[34m5\u001b[39m;                       \u001b[90mok, because mut\u001b[39m\r\n\r\n  \u001b[31mBooleans are lowercase\u001b[39m true/false \u2014 capital True/False is a Python habit that won't compile. Annotate a type with \u001b[33m:\u001b[39m when you want one explicitly.\r\n\r\n\u001b[1m\u001b[33mNUMBERS\u001b[39m\u001b[22m\r\n\r\n  Integer literals default to \u001b[36mi32\u001b[39m; decimals to \u001b[36mf64\u001b[39m. An \u001b[36mf64\u001b[39m literal needs the decimal point (\u001b[34m95.0\u001b[39m, not \u001b[34m95\u001b[39m). A literal may carry a suffix to pin its type: \u001b[34m0u8\u001b[39m, \u001b[34m1.0f64\u001b[39m.\r\n\r\n\u001b[1m\u001b[33mPRINTING\u001b[39m\u001b[22m\r\n\r\n  \u001b[35mprintln!\u001b[39m is a \u001b[1mmacro\u001b[22m \u2014 the \u001b[33m!\u001b[39m marks it. \u001b[33m{}\u001b[39m is a placeholder filled by the arguments that follow.\r\n\r\n      \u001b[35mprintln!\u001b[39m(\u001b[32m\"bays open: {}\"\u001b[39m, bays);\r\n\r\n\u001b[1m\u001b[33mCOLLECTIONS AND TUPLES\u001b[39m\u001b[22m\r\n\r\n  \u001b[36mVec<T>\u001b[39m is a growable array, built with the \u001b[35mvec!\u001b[39m macro and indexed with \u001b[33m[i]\u001b[39m. A \u001b[1mtuple\u001b[22m groups a fixed set of values, reached by position with \u001b[33m.0\u001b[39m, \u001b[33m.1\u001b[39m.\r\n\r\n      \u001b[33mlet\u001b[39m hours = \u001b[35mvec!\u001b[39m[\u001b[34m9\u001b[39m, \u001b[34m10\u001b[39m, \u001b[34m11\u001b[39m];\r\n      \u001b[33mlet\u001b[39m first = hours[\u001b[34m0\u001b[39m];        \u001b[90m9\u001b[39m\r\n      \u001b[33mlet\u001b[39m shift = (\u001b[34m9\u001b[39m, \u001b[34m17\u001b[39m);         \u001b[90m(i32, i32)\u001b[39m\r\n\r\n\u001b[1m\u001b[33mCONTROL FLOW AND FUNCTIONS\u001b[39m\u001b[22m\r\n\r\n  \u001b[33mif\u001b[39m takes no parentheses and is an \u001b[1mexpression\u001b[22m \u2014 it produces a value. \u001b[33mmatch\u001b[39m compares against patterns and must be exhaustive. \u001b[33mfn\u001b[39m declares a function; its final expression (no \u001b[33m;\u001b[39m) is what it returns.\r\n\r\n      \u001b[33mfn\u001b[39m \u001b[36mbusy\u001b[39m(n: \u001b[36mi32\u001b[39m) -> \u001b[36mbool\u001b[39m { n > \u001b[34m8\u001b[39m }\r\n\r\n  NEXT TIER: owned \u001b[36mString\u001b[39m vs borrowed \u001b[36m&str\u001b[39m, \u001b[36mVec\u001b[39m methods, and \u001b[36mOption\u001b[39m / \u001b[36mResult\u001b[39m for values that might be missing or fail. The shift is from \"store and print\" to \"handle presence and absence.\"\r\n","2":"\u001b[1m\u001b[33mRUST \u00b7 TIER 2 CONCEPTS (AMATEUR)\u001b[39m\u001b[22m\r\n\r\n  \u001b[90mThis tier is about collections that grow, strings you own, and values that might be missing or might fail.\u001b[39m\r\n\r\n  Introductory bound and printed values. Now you build them up: push onto a \u001b[36mVec\u001b[39m, own a \u001b[36mString\u001b[39m, and model \"maybe absent\" with \u001b[36mOption\u001b[39m and \"maybe failed\" with \u001b[36mResult\u001b[39m \u2014 Rust's stand-ins for null and exceptions.\r\n\r\n\u001b[1m\u001b[33mVECTORS AND STRINGS\u001b[39m\u001b[22m\r\n\r\n  \u001b[36mVec<T>\u001b[39m starts empty with \u001b[36mVec\u001b[39m::new() and grows with \u001b[35m.push\u001b[39m; pushing needs \u001b[33mmut\u001b[39m. An owned \u001b[36mString\u001b[39m (heap, growable) is distinct from a borrowed \u001b[36m&str\u001b[39m slice; build one with \u001b[36mString\u001b[39m::from.\r\n\r\n      \u001b[33mlet\u001b[39m \u001b[33mmut\u001b[39m queue: \u001b[36mVec<i32>\u001b[39m = \u001b[36mVec\u001b[39m::new();\r\n      queue.\u001b[35mpush\u001b[39m(\u001b[34m7\u001b[39m);\r\n      \u001b[33mlet\u001b[39m shop: \u001b[36mString\u001b[39m = \u001b[36mString\u001b[39m::from(\u001b[32m\"Terminal\"\u001b[39m);\r\n\r\n  \u001b[35m.len()\u001b[39m returns the element count as \u001b[36musize\u001b[39m \u2014 a method, \u001b[31mnot a field, and not .length()\u001b[39m.\r\n\r\n\u001b[1m\u001b[33mOPTION: MAYBE A VALUE\u001b[39m\u001b[22m\r\n\r\n  \u001b[36mOption<T>\u001b[39m is either \u001b[33mSome(v)\u001b[39m or \u001b[33mNone\u001b[39m. It's how Rust says \"this might be empty\" without a null that could crash you later.\r\n\r\n      \u001b[33mlet\u001b[39m found: \u001b[36mOption<i32>\u001b[39m = \u001b[33mSome\u001b[39m(\u001b[34m10\u001b[39m);\r\n\r\n  Pull the value out safely with \u001b[35m.unwrap_or\u001b[39m(default), or branch with \u001b[33mif let\u001b[39m (one case) or \u001b[33mmatch\u001b[39m (both cases). Reach for \u001b[33mif let\u001b[39m when you only care about the \u001b[33mSome\u001b[39m case and want to ignore \u001b[33mNone\u001b[39m; reach for \u001b[33mmatch\u001b[39m when both arms do real work and the compiler should force you to handle each.\r\n\r\n      \u001b[33mif let\u001b[39m \u001b[33mSome\u001b[39m(v) = found { \u001b[35mprintln!\u001b[39m(\u001b[32m\"{}\"\u001b[39m, v); }\r\n\r\n\u001b[1m\u001b[33mRESULT: MAYBE A FAILURE\u001b[39m\u001b[22m\r\n\r\n  \u001b[36mResult<T, E>\u001b[39m is \u001b[33mOk(v)\u001b[39m for success or \u001b[33mErr(e)\u001b[39m for failure. A function that can fail returns one; the caller decides what to do.\r\n\r\n      \u001b[33mfn\u001b[39m \u001b[36mhalf\u001b[39m(n: \u001b[36mi32\u001b[39m) -> \u001b[36mResult<i32, String>\u001b[39m {\r\n          \u001b[33mif\u001b[39m n % \u001b[34m2\u001b[39m == \u001b[34m0\u001b[39m { \u001b[33mOk\u001b[39m(n / \u001b[34m2\u001b[39m) } \u001b[33melse\u001b[39m { \u001b[33mErr\u001b[39m(\u001b[36mString\u001b[39m::from(\u001b[32m\"odd\"\u001b[39m)) }\r\n      }\r\n\r\n  NEXT TIER: \u001b[1mownership\u001b[22m and \u001b[1mborrowing\u001b[22m \u2014 passing a value by reference (\u001b[33m&\u001b[39m) instead of moving it \u2014 plus iterators and closures for transforming collections without writing the loop yourself.\r\n","3":"\u001b[1m\u001b[33mRUST \u00b7 TIER 3 CONCEPTS (INTERMEDIATE)\u001b[39m\u001b[22m\r\n\r\n  \u001b[90mThe heart of Rust: who owns a value, who may borrow it, and how to transform collections with iterators and closures.\u001b[39m\r\n\r\n  Every value has a single owner. You can hand out \u001b[1mborrows\u001b[22m \u2014 temporary read or write access \u2014 but the compiler enforces one rule that prevents whole classes of bugs. Then iterators let you express \"do this to each element\" without a manual loop.\r\n\r\n\u001b[1m\u001b[33mOWNERSHIP AND BORROWING\u001b[39m\u001b[22m\r\n\r\n  Passing a value by name \u001b[1mmoves\u001b[22m it. To let a function read a value without taking it, pass a \u001b[1mborrow\u001b[22m with \u001b[33m&\u001b[39m. A shared borrow \u001b[33m&T\u001b[39m is read-only; an exclusive borrow \u001b[33m&mut T\u001b[39m can modify.\r\n\r\n      \u001b[33mfn\u001b[39m \u001b[36mpeek\u001b[39m(xs: &\u001b[36mVec<i32>\u001b[39m)      \u001b[90mreads, caller keeps ownership\u001b[39m\r\n      \u001b[33mfn\u001b[39m \u001b[36mgrow\u001b[39m(xs: &\u001b[33mmut\u001b[39m \u001b[36mVec<i32>\u001b[39m)  \u001b[90mcan push; needs mut access\u001b[39m\r\n\r\n  The one rule the borrow checker enforces, at compile time:\r\n\r\n      at any moment, a value has EITHER\r\n        - any number of  &T   shared borrows   (readers)   OR\r\n        - exactly one    &mut T exclusive borrow (writer)\r\n      never both at once\r\n\r\n  \u001b[31mA writer and a reader cannot coexist.\u001b[39m That is what stops data races and use-after-free before the program ever runs.\r\n\r\n\u001b[1m\u001b[33mITERATORS\u001b[39m\u001b[22m\r\n\r\n  \u001b[35m.iter()\u001b[39m turns a collection into a lazy sequence of \u001b[33m&T\u001b[39m references. Chain adapters, then finish with a consumer.\r\n\r\n      \u001b[33mlet\u001b[39m total: \u001b[36mi32\u001b[39m = xs.\u001b[35miter\u001b[39m().\u001b[35msum\u001b[39m();\r\n      \u001b[33mlet\u001b[39m evens: \u001b[36mVec<i32>\u001b[39m = xs.\u001b[35miter\u001b[39m().\u001b[35mfilter\u001b[39m(|&x| x % \u001b[34m2\u001b[39m == \u001b[34m0\u001b[39m).\u001b[35mcopied\u001b[39m().\u001b[35mcollect\u001b[39m();\r\n\r\n  \u001b[35m.map\u001b[39m transforms, \u001b[35m.filter\u001b[39m keeps, \u001b[35m.fold\u001b[39m accumulates, \u001b[35m.sum\u001b[39m/\u001b[35m.count\u001b[39m/\u001b[35m.collect\u001b[39m finish.\r\n\r\n\u001b[1m\u001b[33mCLOSURES\u001b[39m\u001b[22m\r\n\r\n  A closure is an inline function written \u001b[33m|args| body\u001b[39m; it can capture variables from the surrounding scope. Since \u001b[35m.iter()\u001b[39m yields references, closures often deref their argument.\r\n\r\n      xs.\u001b[35miter\u001b[39m().\u001b[35mmap\u001b[39m(|&x| x * x)    \u001b[90m|&x| binds x as the value\u001b[39m\r\n      xs.\u001b[35miter\u001b[39m().\u001b[35mmap\u001b[39m(|x| *x * *x)   \u001b[90mor deref in the body\u001b[39m\r\n\r\n  Add \u001b[33mmove\u001b[39m to force the closure to \u001b[1mown\u001b[22m its captures \u2014 required when the closure outlives the current scope (e.g. handed to a thread).\r\n\r\n  NEXT TIER: \u001b[1mtraits\u001b[22m (shared behavior across types) and \u001b[1mgenerics\u001b[22m (\u001b[33m<T>\u001b[39m with bounds). You'll define an interface once and implement it for many types, and write functions that work over any type that fits.\r\n","4":"\u001b[1m\u001b[33mRUST \u00b7 TIER 4 CONCEPTS (EXPERIENCED)\u001b[39m\u001b[22m\r\n\r\n  \u001b[90mAbstraction without overhead: traits define shared behavior, generics write code once for many types, and lifetimes keep borrows honest.\u001b[39m\r\n\r\n  Intermediate moved values around safely. Now you generalize: a \u001b[36mtrait\u001b[39m names behavior any type can implement, a generic works over every type that satisfies its bounds, and a lifetime annotation lets a struct hold a borrow without ever dangling.\r\n\r\n\u001b[1m\u001b[33mTRAITS\u001b[39m\u001b[22m\r\n\r\n  A \u001b[33mtrait\u001b[39m is an interface \u2014 a set of methods a type promises to provide. \u001b[33mimpl\u001b[39m \u001b[36mTrait\u001b[39m \u001b[33mfor\u001b[39m \u001b[36mType\u001b[39m supplies them. A trait may give a \u001b[1mdefault\u001b[22m method body, which implementors inherit unless they override.\r\n\r\n      \u001b[33mtrait\u001b[39m \u001b[36mLayer\u001b[39m {\r\n          \u001b[33mfn\u001b[39m \u001b[36mforward\u001b[39m(&self, x: \u001b[36mf64\u001b[39m) -> \u001b[36mf64\u001b[39m;          \u001b[90mrequired\u001b[39m\r\n          \u001b[33mfn\u001b[39m \u001b[36mname\u001b[39m(&self) -> &\u001b[36mstr\u001b[39m { \u001b[32m\"layer\"\u001b[39m }       \u001b[90mdefault\u001b[39m\r\n      }\r\n\r\n\u001b[1m\u001b[33mGENERICS AND BOUNDS\u001b[39m\u001b[22m\r\n\r\n  A generic parameter \u001b[33m<T>\u001b[39m stands for a type chosen by the caller. \u001b[1mBounds\u001b[22m constrain it: \u001b[33mT: Clone\u001b[39m means \"any T that is Clone.\" Combine bounds with \u001b[33m+\u001b[39m.\r\n\r\n      \u001b[33mfn\u001b[39m \u001b[36mfirst\u001b[39m\u001b[33m<T: Clone>\u001b[39m(xs: &[\u001b[36mT\u001b[39m]) -> \u001b[36mT\u001b[39m { xs[\u001b[34m0\u001b[39m].\u001b[35mclone\u001b[39m() }\r\n\r\n  Without the \u001b[33mClone\u001b[39m bound this would not compile \u2014 you can't clone a value whose type isn't known to support it.\r\n\r\n\u001b[1m\u001b[33mLIFETIMES\u001b[39m\u001b[22m\r\n\r\n  When a struct stores a reference, Rust needs to know the reference will outlive the struct. A lifetime parameter \u001b[33m'a\u001b[39m expresses that tie.\r\n\r\n      \u001b[33mstruct\u001b[39m \u001b[36mView<'a>\u001b[39m { data: &\u001b[33m'a\u001b[39m \u001b[36m[f64]\u001b[39m }\r\n\r\n  \u001b[31mAlways anchor lifetimes to a real scenario\u001b[39m \u2014 a struct holding a slice, a function returning a borrow. They are bookkeeping for borrows, not a puzzle to solve in the abstract.\r\n\r\n\u001b[1m\u001b[33mRETURNING RESULTS\u001b[39m\u001b[22m\r\n\r\n  A fallible function returns \u001b[36mResult<T, E>\u001b[39m. The \u001b[33m?\u001b[39m operator unwraps an \u001b[33mOk\u001b[39m or returns the \u001b[33mErr\u001b[39m to the caller \u2014 \u001b[31mit propagates, it does not crash\u001b[39m (that is .unwrap()).\r\n\r\n      \u001b[33mlet\u001b[39m n: \u001b[36mi32\u001b[39m = text.\u001b[35mparse\u001b[39m()?;\r\n\r\n  NEXT TIER: heap and shared ownership \u2014 \u001b[36mBox\u001b[39m, \u001b[36mRc\u001b[39m, \u001b[36mArc\u001b[39m \u2014 plus \u001b[33masync\u001b[39m/\u001b[33m.await\u001b[39m and \u001b[33munsafe\u001b[39m. The capstone composes these into a small machine-learning primitive.\r\n","5":"\u001b[1m\u001b[33mRUST \u00b7 TIER 5 CONCEPTS (MASTER)\u001b[39m\u001b[22m\r\n\r\n  \u001b[90mThe systems tier: futures you await, pointers you share, escape hatches you reach for deliberately \u2014 and the primitives that build a model.\u001b[39m\r\n\r\n  Everything so far ran start to finish on one thread, with the borrow checker watching. Master adds the tools real systems need: \u001b[33masync\u001b[39m for work that waits, smart pointers for shared ownership, and \u001b[33munsafe\u001b[39m for the rare moment you step outside the checker's guarantees on purpose.\r\n\r\n\u001b[1m\u001b[33mASYNC AND AWAIT\u001b[39m\u001b[22m\r\n\r\n  \u001b[33masync fn\u001b[39m returns a \u001b[1mfuture\u001b[22m \u2014 a value that does nothing until driven. You drive it with \u001b[33m.await\u001b[39m, which is \u001b[31mpostfix\u001b[39m in Rust: \u001b[33mexpr.await\u001b[39m, not \u001b[33mawait expr\u001b[39m as in Python or JavaScript.\r\n\r\n      \u001b[33masync fn\u001b[39m \u001b[36mwarm\u001b[39m() -> \u001b[36mi32\u001b[39m { \u001b[34m1\u001b[39m }\r\n      \u001b[33mlet\u001b[39m ready = warm().\u001b[35mawait\u001b[39m;\r\n\r\n\u001b[1m\u001b[33mSMART POINTERS\u001b[39m\u001b[22m\r\n\r\n  \u001b[36mBox<T>\u001b[39m owns one value on the heap and powers \u001b[33mdyn\u001b[39m trait objects (\u001b[36mBox<dyn Layer>\u001b[39m). \u001b[36mRc<T>\u001b[39m gives several owners a shared, reference-counted value on one thread; \u001b[36mArc<T>\u001b[39m is the atomic version that is safe to share across threads.\r\n\r\n      \u001b[33mlet\u001b[39m owned = \u001b[36mBox\u001b[39m::new(\u001b[34m3.0\u001b[39m);          \u001b[90mone heap value\u001b[39m\r\n      \u001b[33mlet\u001b[39m shared = \u001b[36mRc\u001b[39m::new(\u001b[34m5\u001b[39m);            \u001b[90mclone bumps a refcount\u001b[39m\r\n      \u001b[33mlet\u001b[39m across = \u001b[36mArc\u001b[39m::new(\u001b[34m5\u001b[39m);           \u001b[90msame, thread-safe\u001b[39m\r\n\r\n  \u001b[35mRc::clone\u001b[39m(&x) makes another handle to the same data \u2014 cheap, no deep copy. Reach for \u001b[36mArc\u001b[39m only when the data crosses threads; it costs a little more.\r\n\r\n\u001b[1m\u001b[33mUNSAFE AND FFI\u001b[39m\u001b[22m\r\n\r\n  Most Rust is checked at compile time. An \u001b[33munsafe\u001b[39m block is where you tell the compiler \"I have verified this myself\" \u2014 dereferencing a raw pointer, or calling across an \u001b[33mextern \"C\"\u001b[39m boundary.\r\n\r\n      \u001b[33mlet\u001b[39m p = &x \u001b[33mas\u001b[39m *\u001b[33mconst\u001b[39m \u001b[36mi32\u001b[39m;     \u001b[90mmaking a raw pointer is safe\u001b[39m\r\n      \u001b[33mlet\u001b[39m v = \u001b[33munsafe\u001b[39m { *p };           \u001b[90mdereferencing it is not\u001b[39m\r\n\r\n  \u001b[33mextern \"C\"\u001b[39m gives a function the C ABI so other languages can call it \u2014 the bridge to GPUs and existing numeric libraries.\r\n\r\n  THE CAPSTONE: the final question composes iterators and closures into a \u001b[1mdot product\u001b[22m \u2014 the inner loop of every matrix multiply and dense layer. Everything in this track has been building toward writing real numeric code in safe Rust.\r\n"},"examples":{"1":["\u001b[1m\u001b[33mEXAMPLE 1\u001b[39m\u001b[22m\r\n\r\n  Bind a few names of different types and let Rust infer where it can.\r\n\r\n      \u001b[33mlet\u001b[39m shop = \u001b[32m\"Terminal Auto\"\u001b[39m;\r\n      \u001b[33mlet\u001b[39m bays = \u001b[34m4\u001b[39m;                 \u001b[90mi32\u001b[39m\r\n      \u001b[33mlet\u001b[39m hourly: \u001b[36mf64\u001b[39m = \u001b[34m95.0\u001b[39m;      \u001b[90mexplicit f64\u001b[39m\r\n      \u001b[33mlet\u001b[39m open = \u001b[33mtrue\u001b[39m;             \u001b[90mbool, lowercase\u001b[39m\r\n\r\n  \u001b[90mOne binding per line. Inference handles the first two; the f64 is annotated because 95.0 alone would just be \"some float.\"\u001b[39m\r\n","\u001b[1m\u001b[33mEXAMPLE 2\u001b[39m\u001b[22m\r\n\r\n  Build a small Vec and a tuple, then read from each.\r\n\r\n      \u001b[33mlet\u001b[39m hours = \u001b[35mvec!\u001b[39m[\u001b[34m9\u001b[39m, \u001b[34m10\u001b[39m, \u001b[34m11\u001b[39m];\r\n      \u001b[33mlet\u001b[39m opening = hours[\u001b[34m0\u001b[39m];       \u001b[90m9\u001b[39m\r\n      \u001b[33mlet\u001b[39m shift = (\u001b[34m9\u001b[39m, \u001b[34m17\u001b[39m);\r\n      \u001b[33mlet\u001b[39m ends = shift.\u001b[34m1\u001b[39m;          \u001b[90m17 \u2014 tuple field by position\u001b[39m\r\n\r\n  \u001b[90mVec indexing and tuple-field access both start at 0, but a tuple's fields use .0 / .1, not [0].\u001b[39m\r\n","\u001b[1m\u001b[33mEXAMPLE 3\u001b[39m\u001b[22m\r\n\r\n  \u001b[33mif\u001b[39m is an expression, so it can feed a binding directly. A function returns its final expression.\r\n\r\n      \u001b[33mfn\u001b[39m \u001b[36mbusy\u001b[39m(n: \u001b[36mi32\u001b[39m) -> \u001b[36mbool\u001b[39m {\r\n          n > \u001b[34m8\u001b[39m                      \u001b[90mno semicolon: this is the return\u001b[39m\r\n      }\r\n      \u001b[33mlet\u001b[39m level = \u001b[33mif\u001b[39m busy(\u001b[34m10\u001b[39m) { \u001b[32m\"high\"\u001b[39m } \u001b[33melse\u001b[39m { \u001b[32m\"low\"\u001b[39m };\r\n\r\n  \u001b[90mA trailing semicolon on that last function line would discard the value and return the unit type instead. Leave it off to return.\u001b[39m\r\n","\u001b[1m\u001b[33mEXAMPLE 4\u001b[39m\u001b[22m\r\n\r\n  A preview of Amateur tier: \u001b[36mOption<i32>\u001b[39m represents a value that might be missing, and \u001b[33mmatch\u001b[39m handles both cases.\r\n\r\n      \u001b[33mlet\u001b[39m maybe_bay: \u001b[36mOption<i32>\u001b[39m = \u001b[33mSome\u001b[39m(\u001b[34m3\u001b[39m);\r\n      \u001b[33mlet\u001b[39m note = \u001b[33mmatch\u001b[39m maybe_bay {\r\n          \u001b[33mSome\u001b[39m(n) => n,\r\n          \u001b[33mNone\u001b[39m => \u001b[34m0\u001b[39m,\r\n      };\r\n\r\n  \u001b[90mNext tier leans on this: Option, Result, and match together are how Rust handles \"might not be there\" without null.\u001b[39m\r\n"],"2":["\u001b[1m\u001b[33mEXAMPLE 1\u001b[39m\u001b[22m\r\n\r\n  Grow a vector, then ask it for its length.\r\n\r\n      \u001b[33mlet\u001b[39m \u001b[33mmut\u001b[39m tickets: \u001b[36mVec<i32>\u001b[39m = \u001b[36mVec\u001b[39m::new();\r\n      tickets.\u001b[35mpush\u001b[39m(\u001b[34m101\u001b[39m);\r\n      tickets.\u001b[35mpush\u001b[39m(\u001b[34m102\u001b[39m);\r\n      \u001b[33mlet\u001b[39m open = tickets.\u001b[35mlen\u001b[39m();    \u001b[90m2, a usize\u001b[39m\r\n\r\n  \u001b[90mWithout \u001b[33mmut\u001b[39m the push lines would not compile. .len() reads the count back; it never changes the vector.\u001b[39m\r\n","\u001b[1m\u001b[33mEXAMPLE 2\u001b[39m\u001b[22m\r\n\r\n  Own a String, then borrow it as a &str to read without taking ownership.\r\n\r\n      \u001b[33mlet\u001b[39m make = \u001b[36mString\u001b[39m::from(\u001b[32m\"Nissan\"\u001b[39m);\r\n      \u001b[33mlet\u001b[39m view: &\u001b[36mstr\u001b[39m = &make;      \u001b[90ma borrowed slice of make\u001b[39m\r\n      \u001b[35mprintln!\u001b[39m(\u001b[32m\"{}\"\u001b[39m, view);\r\n\r\n  \u001b[90mmake owns the text; view borrows it. Both can be read here because a shared borrow doesn't move the owner. More on borrowing next tier.\u001b[39m\r\n","\u001b[1m\u001b[33mEXAMPLE 3\u001b[39m\u001b[22m\r\n\r\n  Handle an Option both ways: a default with unwrap_or, and a branch with match.\r\n\r\n      \u001b[33mlet\u001b[39m reading: \u001b[36mOption<f64>\u001b[39m = \u001b[33mNone\u001b[39m;\r\n      \u001b[33mlet\u001b[39m safe = reading.\u001b[35munwrap_or\u001b[39m(\u001b[34m0.0\u001b[39m);   \u001b[90m0.0, since None\u001b[39m\r\n      \u001b[33mlet\u001b[39m tag = \u001b[33mmatch\u001b[39m reading {\r\n          \u001b[33mSome\u001b[39m(v) => v,\r\n          \u001b[33mNone\u001b[39m => \u001b[34m-1.0\u001b[39m,\r\n      };\r\n\r\n  \u001b[90munwrap_or gives a fallback in one move; match lets each arm do different work. Reach for match when the cases diverge.\u001b[39m\r\n","\u001b[1m\u001b[33mEXAMPLE 4\u001b[39m\u001b[22m\r\n\r\n  A preview of Intermediate tier: borrow a Vec by reference so a function can read it without taking ownership.\r\n\r\n      \u001b[33mfn\u001b[39m \u001b[36mtotal\u001b[39m(xs: &\u001b[36mVec<i32>\u001b[39m) -> \u001b[36mi32\u001b[39m {\r\n          \u001b[33mlet\u001b[39m \u001b[33mmut\u001b[39m sum = \u001b[34m0\u001b[39m;\r\n          \u001b[33mfor\u001b[39m v \u001b[33min\u001b[39m xs { sum += v; }\r\n          sum\r\n      }\r\n\r\n  \u001b[90mThe \u001b[33m&\u001b[39m means total borrows the vector; the caller keeps owning it. Next tier replaces this hand-written loop with .iter().sum().\u001b[39m\r\n"],"3":["\u001b[1m\u001b[33mEXAMPLE 1\u001b[39m\u001b[22m\r\n\r\n  Borrow a slice to read it; take &mut to change it. Two functions, two kinds of access.\r\n\r\n      \u001b[33mfn\u001b[39m \u001b[36mbiggest\u001b[39m(xs: &\u001b[36mVec<i32>\u001b[39m) -> \u001b[36mi32\u001b[39m {\r\n          \u001b[33mlet\u001b[39m \u001b[33mmut\u001b[39m best = xs[\u001b[34m0\u001b[39m];\r\n          \u001b[33mfor\u001b[39m &v \u001b[33min\u001b[39m xs { \u001b[33mif\u001b[39m v > best { best = v; } }\r\n          best\r\n      }\r\n      \u001b[33mfn\u001b[39m \u001b[36mbump\u001b[39m(xs: &\u001b[33mmut\u001b[39m \u001b[36mVec<i32>\u001b[39m) { xs.\u001b[35mpush\u001b[39m(\u001b[34m0\u001b[39m); }\r\n\r\n  \u001b[90mbiggest only reads, so &Vec is enough. bump mutates, so it needs &mut. You could not hold both borrows at the same time.\u001b[39m\r\n","\u001b[1m\u001b[33mEXAMPLE 2\u001b[39m\u001b[22m\r\n\r\n  Replace a manual loop with an iterator chain: keep the big readings, scale them, collect the result.\r\n\r\n      \u001b[33mlet\u001b[39m readings = \u001b[35mvec!\u001b[39m[\u001b[34m0.2\u001b[39m, \u001b[34m0.9\u001b[39m, \u001b[34m0.5\u001b[39m];\r\n      \u001b[33mlet\u001b[39m strong: \u001b[36mVec<f64>\u001b[39m = readings.\u001b[35miter\u001b[39m()\r\n          .\u001b[35mfilter\u001b[39m(|&r| r > \u001b[34m0.4\u001b[39m)\r\n          .\u001b[35mmap\u001b[39m(|r| r * \u001b[34m10.0\u001b[39m)\r\n          .\u001b[35mcollect\u001b[39m();\r\n\r\n  \u001b[90mEach adapter is lazy; nothing runs until .collect() consumes the chain. Read it top to bottom as a pipeline: filter, then map, then gather.\u001b[39m\r\n","\u001b[1m\u001b[33mEXAMPLE 3\u001b[39m\u001b[22m\r\n\r\n  A closure can capture a value from its scope. Here it captures a threshold and counts how many readings clear it.\r\n\r\n      \u001b[33mlet\u001b[39m cutoff = \u001b[34m0.5\u001b[39m;\r\n      \u001b[33mlet\u001b[39m passing = readings.\u001b[35miter\u001b[39m().\u001b[35mfilter\u001b[39m(|&r| r >= cutoff).\u001b[35mcount\u001b[39m();\r\n\r\n  \u001b[90mcutoff is captured by the closure automatically. Because f64 is Copy, no move is needed; for a captured Vec or String you would add move.\u001b[39m\r\n","\u001b[1m\u001b[33mEXAMPLE 4\u001b[39m\u001b[22m\r\n\r\n  A preview of Experienced tier: a \u001b[1mgeneric\u001b[22m function that works for any type implementing a \u001b[36mtrait\u001b[39m. This one debug-prints any such value.\r\n\r\n      \u001b[33mfn\u001b[39m \u001b[36mdescribe\u001b[39m\u001b[33m<T: std::fmt::Debug>\u001b[39m(item: &\u001b[36mT\u001b[39m) {\r\n          \u001b[35mprintln!\u001b[39m(\u001b[32m\"{:?}\"\u001b[39m, item);\r\n      }\r\n\r\n  \u001b[90mThe \u001b[33m<T: Debug>\u001b[39m bound says \"any type T that can be debug-printed.\" Next tier defines traits and implements them, instead of just requiring one as a bound here.\u001b[39m\r\n"],"4":["\u001b[1m\u001b[33mEXAMPLE 1\u001b[39m\u001b[22m\r\n\r\n  Define a trait with one required method, then implement it for a type.\r\n\r\n      \u001b[33mtrait\u001b[39m \u001b[36mScore\u001b[39m {\r\n          \u001b[33mfn\u001b[39m \u001b[36mscore\u001b[39m(&self) -> \u001b[36mf64\u001b[39m;\r\n      }\r\n      \u001b[33mstruct\u001b[39m \u001b[36mRun\u001b[39m { hits: \u001b[36mf64\u001b[39m, total: \u001b[36mf64\u001b[39m }\r\n      \u001b[33mimpl\u001b[39m \u001b[36mScore\u001b[39m \u001b[33mfor\u001b[39m \u001b[36mRun\u001b[39m {\r\n          \u001b[33mfn\u001b[39m \u001b[36mscore\u001b[39m(&self) -> \u001b[36mf64\u001b[39m { self.hits / self.total }\r\n      }\r\n\r\n  \u001b[90mThe impl block fills in every required method. Once implemented, a Run can be used anywhere a Score is expected.\u001b[39m\r\n","\u001b[1m\u001b[33mEXAMPLE 2\u001b[39m\u001b[22m\r\n\r\n  A generic function with a trait bound: it works for any type that can be added, returning the sum.\r\n\r\n      \u001b[33muse\u001b[39m std::ops::\u001b[36mAdd\u001b[39m;\r\n      \u001b[33mfn\u001b[39m \u001b[36mcombine\u001b[39m\u001b[33m<T: Add<Output = T> + Copy>\u001b[39m(a: \u001b[36mT\u001b[39m, b: \u001b[36mT\u001b[39m) -> \u001b[36mT\u001b[39m {\r\n          a + b\r\n      }\r\n\r\n  \u001b[90mThe bound T: Add<Output = T> says \"T can be added to itself and yields a T.\" Copy lets the function use a and b by value. Bounds are the contract a generic relies on.\u001b[39m\r\n","\u001b[1m\u001b[33mEXAMPLE 3\u001b[39m\u001b[22m\r\n\r\n  A struct that borrows data needs a lifetime so the borrow can't outlive its source.\r\n\r\n      \u001b[33mstruct\u001b[39m \u001b[36mWindow<'a>\u001b[39m { samples: &\u001b[33m'a\u001b[39m \u001b[36m[i32]\u001b[39m }\r\n      \u001b[33mimpl\u001b[39m\u001b[33m<'a>\u001b[39m \u001b[36mWindow<'a>\u001b[39m {\r\n          \u001b[33mfn\u001b[39m \u001b[36mfirst\u001b[39m(&self) -> \u001b[36mi32\u001b[39m { self.samples[\u001b[34m0\u001b[39m] }\r\n      }\r\n\r\n  \u001b[90mWindow borrows a slice it does not own; 'a ties the two together so the compiler rejects any use of Window after samples is gone.\u001b[39m\r\n","\u001b[1m\u001b[33mEXAMPLE 4\u001b[39m\u001b[22m\r\n\r\n  A preview of Master tier: \u001b[36mBox\u001b[39m puts a value on the heap, and a \u001b[36mBox<dyn Score>\u001b[39m holds any scorer behind its trait interface.\r\n\r\n      \u001b[33mlet\u001b[39m boxed: \u001b[36mBox<dyn Score>\u001b[39m = \u001b[36mBox\u001b[39m::new(\u001b[36mRun\u001b[39m { hits: \u001b[34m8.0\u001b[39m, total: \u001b[34m10.0\u001b[39m });\r\n\r\n  \u001b[90mboxed holds a heap-allocated Run, reachable only through the Score trait. Next tier adds Rc/Arc for sharing, async for awaiting, and the ML capstone.\u001b[39m\r\n"],"5":["\u001b[1m\u001b[33mEXAMPLE 1\u001b[39m\u001b[22m\r\n\r\n  An async function returns a future; await drives it to a value.\r\n\r\n      \u001b[33masync fn\u001b[39m \u001b[36mfetch_batch\u001b[39m() -> \u001b[36mi32\u001b[39m { \u001b[34m32\u001b[39m }\r\n      \u001b[33mlet\u001b[39m size = fetch_batch().\u001b[35mawait\u001b[39m;   \u001b[90mpostfix .await, not a prefix\u001b[39m\r\n\r\n  \u001b[90mCalling fetch_batch() alone does no work \u2014 it hands back a future. .await is what runs it. The postfix position is the Rust-specific habit.\u001b[39m\r\n","\u001b[1m\u001b[33mEXAMPLE 2\u001b[39m\u001b[22m\r\n\r\n  Share one allocation through several handles with Rc, then reach for Arc when the data must cross threads.\r\n\r\n      \u001b[33mlet\u001b[39m cache = \u001b[36mRc\u001b[39m::new(\u001b[35mvec!\u001b[39m[\u001b[34m1\u001b[39m, \u001b[34m2\u001b[39m, \u001b[34m3\u001b[39m]);\r\n      \u001b[33mlet\u001b[39m alias = \u001b[36mRc\u001b[39m::clone(&cache);     \u001b[90msecond handle, same data\u001b[39m\r\n      \u001b[33mlet\u001b[39m pool = \u001b[36mArc\u001b[39m::new(\u001b[35mvec!\u001b[39m[\u001b[34m1\u001b[39m, \u001b[34m2\u001b[39m, \u001b[34m3\u001b[39m]);  \u001b[90mthread-safe variant\u001b[39m\r\n\r\n  \u001b[90mcache and alias point at the same vector; dropping one just lowers the count. The data frees when the last handle goes away.\u001b[39m\r\n","\u001b[1m\u001b[33mEXAMPLE 3\u001b[39m\u001b[22m\r\n\r\n  A boxed closure stores behavior on the heap behind the Fn trait \u2014 here, a single activation function.\r\n\r\n      \u001b[33mlet\u001b[39m relu: \u001b[36mBox<dyn Fn(f64) -> f64>\u001b[39m =\r\n          \u001b[36mBox\u001b[39m::new(|x| \u001b[33mif\u001b[39m x > \u001b[34m0.0\u001b[39m { x } \u001b[33melse\u001b[39m { \u001b[34m0.0\u001b[39m });\r\n      \u001b[33mlet\u001b[39m y = relu(\u001b[34m-2.0\u001b[39m);              \u001b[90m0.0\u001b[39m\r\n\r\n  \u001b[90mThe closure has an anonymous type, so storing it needs the Box behind the Fn trait. Call it like any function once boxed.\u001b[39m\r\n","\u001b[1m\u001b[33mEXAMPLE 4\u001b[39m\u001b[22m\r\n\r\n  Closing the track: compose iterators into a numeric primitive \u2014 here the mean activation of a layer's outputs.\r\n\r\n      \u001b[33mlet\u001b[39m acts = \u001b[35mvec!\u001b[39m[\u001b[34m0.5\u001b[39m, \u001b[34m1.5\u001b[39m, \u001b[34m-0.5\u001b[39m];\r\n      \u001b[33mlet\u001b[39m mean = acts.\u001b[35miter\u001b[39m().\u001b[35msum\u001b[39m::<f64>() / acts.\u001b[35mlen\u001b[39m() \u001b[33mas\u001b[39m \u001b[36mf64\u001b[39m;\r\n\r\n  \u001b[90mThis is where the track has been heading: real numeric code, written in safe Rust. The capstone question builds the dot product the same way; the planned C++ and CUDA tracks pick up where Rust leaves off.\u001b[39m\r\n"]}}};
